\echo '--- update 66: Telegram — one-time code, private chats, consent = an owner-MCP grant in the Vault, one door, confirmations, source telegram'
create temporary table t66 (k text primary key, v text);
grant all on t66 to public;

set role service_role;
do $$
declare
  v_a uuid := (select id from public.shops where slug = 'potraviny-centrum');
begin
  insert into t66 values ('had_plan', public.shop_has_plan(v_a)::text),
    ('sub', (select to_jsonb(s) from public.subscriptions s where s.shop_id = v_a)::text), ('d', (current_date + 30)::text);
  insert into public.subscriptions (shop_id, status, plan, current_period_end, stripe_subscription_id)
  values (v_a, 'active', 'pro', now() + interval '30 days', 'sub_test_66')
  on conflict (shop_id) do update set status = 'active', current_period_end = now() + interval '30 days',
    stripe_subscription_id = coalesce(public.subscriptions.stripe_subscription_id, 'sub_test_66');
end $$;
reset role;

-- the owner asks for a code (≤ 5 an hour)
set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000a';
do $$
declare
  vj jsonb := public.owner_telegram_link_start();
begin
  assert vj ->> 'code' ~ '^tg[0-9a-f]{40}$', vj::text;
  insert into t66 values ('code', vj ->> 'code');
  insert into t66 values ('code2', public.owner_telegram_link_start() ->> 'code');
  assert public.owner_telegram_status() is null, 'not linked yet';
  begin perform public.owner_telegram_consent(array[(select id from public.shops where slug = 'potraviny-centrum')], array['shop.read']);
    raise exception 'consent before linking';
  exception when no_data_found then if sqlerrm <> 'not_linked' then raise; end if; end;
end $$;
reset role;

-- the bot: private chats only, the code once, within 10 minutes
set role service_role;
do $$
declare
  vj jsonb;
begin
  begin perform public.telegram_claim((select v from t66 where k = 'code'), 9001, -5001, 'group', 'davide', 'sk');
    raise exception 'a group was linked';
  exception when invalid_parameter_value then if sqlerrm <> 'chat' then raise; end if; end;
  vj := public.telegram_claim((select v from t66 where k = 'code'), 9001, 9001, 'private', 'davide', 'sk');
  assert (vj ->> 'ok')::boolean, vj::text;
  begin perform public.telegram_claim((select v from t66 where k = 'code'), 9001, 9001, 'private', 'davide', 'sk');
    raise exception 'code used twice';
  exception when invalid_parameter_value then if sqlerrm <> 'code' then raise; end if; end;
  update public.telegram_link_codes set expires_at = now() - interval '1 second' where code_hash = public.mcp_hash((select v from t66 where k = 'code2'));
  begin perform public.telegram_claim((select v from t66 where k = 'code2'), 9001, 9001, 'private', 'davide', 'sk');
    raise exception 'expired code';
  exception when invalid_parameter_value then if sqlerrm <> 'code' then raise; end if; end;
  vj := public.telegram_whoami(9001);
  assert (vj ->> 'linked')::boolean and not (vj ->> 'granted')::boolean, 'linked, no permissions yet: ' || vj::text;
  assert not (public.telegram_whoami(4242) ->> 'linked')::boolean, 'unknown users are not linked';
  begin perform public.telegram_call(9001, 'list_shops', '{}'); raise exception 'tools before consent';
  exception when invalid_authorization_specification then null; end;
end $$;
reset role;

-- consent: Pro shops of the owner only; a grant of kind telegram with its token only in the Vault
set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000a';
do $$
declare
  v_a uuid := (select id from public.shops where slug = 'potraviny-centrum');
  v_b uuid := (select id from public.shops where slug = 'drogeria-kostolne');
  vj jsonb;
  i integer;
begin
  begin perform public.owner_telegram_consent(array[v_b], array['shop.read']); raise exception 'another owner''s shop';
  exception when insufficient_privilege then null; end;
  begin perform public.owner_telegram_consent(array[v_a], array['shop.write']); raise exception 'without shop.read';
  exception when invalid_parameter_value then null; end;
  vj := public.owner_telegram_consent(array[v_a], array['shop.read', 'shop.write']);
  assert (vj ->> 'ok')::boolean;
  vj := public.owner_telegram_status();
  assert vj ->> 'username' = 'davide' and vj -> 'scopes' = '["shop.read", "shop.write"]'::jsonb
     and vj -> 'shops' -> 0 ->> 'slug' = 'potraviny-centrum', vj::text;
  begin perform count(*) from public.telegram_links; raise exception 'owner read the links table';
  exception when insufficient_privilege then null; end;
  -- the owner's choices per shop: only known notification kinds, quiet hours both or none, only the grant's shops
  assert public.owner_telegram_save_prefs(v_a, false, '{"booking_new": true, "callback": false, "everything": true}', '22:00', '07:00');
  vj := public.owner_telegram_prefs() -> 0;
  assert vj -> 'notify' = '{"booking_new": true}'::jsonb and not (vj ->> 'ai_on')::boolean
     and vj ->> 'quiet_from' = '22:00' and vj ->> 'quiet_to' = '07:00', vj::text;
  begin perform public.owner_telegram_save_prefs(v_a, true, '{}', '22:00', ''); raise exception 'half quiet hours';
  exception when invalid_parameter_value then if sqlerrm <> 'quiet' then raise; end if; end;
  begin perform public.owner_telegram_save_prefs(v_a, true, '{}', '25:00', '07:00'); raise exception 'bad time';
  exception when invalid_parameter_value then if sqlerrm <> 'quiet' then raise; end if; end;
  begin perform public.owner_telegram_save_prefs(v_b, true, '{}', '', ''); raise exception 'another owner''s shop';
  exception when insufficient_privilege then null; end;
  -- a test notification: 5 an hour
  for i in 1..5 loop perform public.owner_telegram_test(v_a); end loop;
  begin perform public.owner_telegram_test(v_a); raise exception 'no limit on test notifications';
  exception when program_limit_exceeded then null; end;
  begin perform count(*) from public.telegram_outbox; raise exception 'owner read the outbox';
  exception when insufficient_privilege then null; end;
end $$;
reset role;

-- (as the database owner: the Vault is not readable by the service role's queries)
do $$ begin
  assert exists (select 1 from vault.secrets s join public.telegram_links l on l.vault_id = s.id
                 where l.tg_user_id = 9001 and s.secret ~ '^ctg_[0-9a-f]{64}$'), 'the token only in the Vault';
  assert not exists (select 1 from public.telegram_links l join public.owner_mcp_tokens t on t.id = l.grant_id
                     join vault.secrets s on s.id = l.vault_id where t.access_hash = s.secret), 'the table keeps only its hash';
end $$;

set role service_role;
do $$
declare
  v_a uuid := (select id from public.shops where slug = 'potraviny-centrum');
  v_d date := (select v::date from t66 where k = 'd');
  vj jsonb;
  v_p uuid;
  v_b1 uuid;
  v_b2 uuid;
begin
  assert exists (select 1 from public.owner_mcp_tokens t join public.telegram_links l on l.grant_id = t.id
                 where l.tg_user_id = 9001 and t.kind = 'telegram' and t.revoked_at is null), 'a telegram grant';
  assert (select vault_id is not null from public.telegram_links where tg_user_id = 9001), 'its token is in the Vault';
  -- reads through the one door
  vj := public.telegram_call(9001, 'get_shop_details', '{}');
  assert vj ->> 'shop' = 'potraviny-centrum', vj::text;
  -- a write only through a confirmation; read tools never wait for one
  begin perform public.telegram_pending_new(9001, 'get_shop_details', '{}', '{}'); raise exception 'pending read tool';
  exception when invalid_parameter_value then if sqlerrm <> 'unknown_tool' then raise; end if; end;
  -- the database refuses a write outside "Potvrdiť"; update_stock without confirm only previews
  begin perform public.telegram_call(9001, 'set_opening_hours', jsonb_build_object('special',
          jsonb_build_array(jsonb_build_object('from', v_d, 'closed', true)))); raise exception 'write without Potvrdiť';
  exception when insufficient_privilege then if sqlerrm <> 'needs_confirmation' then raise; end if; end;
  begin perform public.telegram_call(9001, 'update_stock', jsonb_build_object('item_id', gen_random_uuid(), 'quantity', 1, 'confirm', true));
    raise exception 'stock write without Potvrdiť';
  exception when insufficient_privilege then if sqlerrm <> 'needs_confirmation' then raise; end if; end;
  begin perform public.telegram_call(9001, 'update_stock', jsonb_build_object('item_id', gen_random_uuid(), 'quantity', 1));
    raise exception 'unknown item previewed';
  exception when no_data_found then null; end;
  v_p := public.telegram_pending_new(9001, 'set_opening_hours', jsonb_build_object('special',
           jsonb_build_array(jsonb_build_object('from', v_d, 'closed', true))), '{"what":"close"}');
  assert not exists (select 1 from public.shop_special_hours where shop_id = v_a and date = v_d), 'nothing before Potvrdiť';
  begin perform public.telegram_confirm(4242, v_p); raise exception 'another Telegram user confirmed';
  exception when no_data_found then null; end;
  vj := public.telegram_confirm(9001, v_p);
  assert exists (select 1 from public.shop_special_hours where shop_id = v_a and date = v_d and closed), 'closed that day';
  assert exists (select 1 from public.shop_activity where shop_id = v_a and action = 'hours_changed' and details ->> 'source' = 'telegram'),
    'the activity log says telegram';
  begin perform public.telegram_confirm(9001, v_p); raise exception 'confirmed twice';
  exception when invalid_parameter_value then if sqlerrm <> 'used' then raise; end if; end;
  v_p := public.telegram_pending_new(9001, 'set_opening_hours', '{"special": []}', '{}');
  update public.telegram_pending set expires_at = now() - interval '1 second' where id = v_p;
  begin perform public.telegram_confirm(9001, v_p); raise exception 'expired confirmation';
  exception when invalid_parameter_value then if sqlerrm <> 'expired' then raise; end if; end;
  assert public.telegram_cancel(9001, public.telegram_pending_new(9001, 'set_opening_hours', '{"special": []}', '{}'));
  -- the bot's shop: only one of the grant
  assert public.telegram_set(9001, 'potraviny-centrum', '{"await":"qty"}');
  begin perform public.telegram_set(9001, 'drogeria-kostolne', null); raise exception 'shop outside the grant';
  exception when insufficient_privilege then null; end;
  -- 30 messages a minute per Telegram user
  update public.telegram_links set window_start = now(), window_count = 30 where tg_user_id = 9001;
  begin perform public.telegram_whoami(9001); raise exception 'no rate limit';
  exception when program_limit_exceeded then null; end;
  update public.telegram_links set window_count = 0 where tg_user_id = 9001;
  -- phase 2: the AI only with both switches on, within the daily limit
  update public.telegram_shop_prefs set ai_on = true where shop_id = v_a;
  update public.telegram_settings set ai_enabled = true, ai_daily_limit = 2 where id;
  assert public.telegram_ai_hit(9001, 'potraviny-centrum') = 1;
  assert public.telegram_ai_hit(9001, 'potraviny-centrum') = 0;
  begin perform public.telegram_ai_hit(9001, 'potraviny-centrum'); raise exception 'no AI limit';
  exception when program_limit_exceeded then if sqlerrm <> 'ai_limit' then raise; end if; end;
  delete from public.telegram_ai_usage;
  update public.telegram_shop_prefs set ai_on = false where shop_id = v_a;
  begin perform public.telegram_ai_hit(9001, 'potraviny-centrum'); raise exception 'AI on for a shop that switched it off';
  exception when raise_exception then if sqlerrm <> 'ai_off' then raise; end if; end;
  update public.telegram_shop_prefs set ai_on = true where shop_id = v_a;
  update public.telegram_settings set ai_enabled = false, ai_daily_limit = 50 where id;
  begin perform public.telegram_ai_hit(9001, 'potraviny-centrum'); raise exception 'AI on while the admin switched it off';
  exception when raise_exception then if sqlerrm <> 'ai_off' then raise; end if; end;
  update public.telegram_settings set ai_enabled = true where id;
  delete from public.telegram_ai_usage;

  -- phase 3: notifications only when ticked; a customer's booking, never the owner's own
  -- (telegram_call above acted as the owner in this transaction: back to a shopper's request without a login)
  perform set_config('request.jwt.claims', '', true);
  perform set_config('request.jwt.claim.sub', '', true);
  delete from public.telegram_outbox;
  update public.telegram_shop_prefs set notify = '{}', quiet_from = null, quiet_to = null where shop_id = v_a;
  v_b1 := gen_random_uuid();
  insert into public.shop_bookings (id, shop_id, starts_at, ends_at, status, name, phone, consent_at, consent_version, token_hash, confirmed_at)
  values (v_b1, v_a, now() + interval '40 days', now() + interval '40 days 30 minutes', 'confirmed', 'Tg Jeden', '+421905131313', now(), 'v', 'x', now());
  assert not exists (select 1 from public.telegram_outbox), 'nothing without ticking';
  update public.telegram_shop_prefs set notify = '{"booking_new": true, "booking_cancelled": true}' where shop_id = v_a;
  perform set_config('request.jwt.claim.sub', '00000000-0000-0000-0000-00000000000a', true);
  insert into public.shop_bookings (id, shop_id, starts_at, ends_at, status, name, phone, consent_at, consent_version, token_hash, confirmed_at)
  values (gen_random_uuid(), v_a, now() + interval '42 days', now() + interval '42 days 30 minutes', 'confirmed', 'Od majiteľa', '+421905141414', now(), 'v', 'x', now());
  perform set_config('request.jwt.claim.sub', '', true);
  assert not exists (select 1 from public.telegram_outbox), 'the owner''s own booking is not announced';
  v_b2 := gen_random_uuid();
  insert into public.shop_bookings (id, shop_id, starts_at, ends_at, status, name, phone, consent_at, consent_version, token_hash, confirmed_at)
  values (v_b2, v_a, now() + interval '41 days', now() + interval '41 days 30 minutes', 'confirmed', 'Tg Dva', '+421905151515', now(), 'v', 'x', now());
  assert (select count(*) from public.telegram_outbox where kind = 'booking_new' and ref_id = v_b2) = 1, 'a customer''s booking';
  -- quiet hours (the shop's time): the notification waits until they end
  update public.telegram_shop_prefs
  set quiet_from = ((now() at time zone 'Europe/Bratislava') - interval '1 hour')::time,
      quiet_to = ((now() at time zone 'Europe/Bratislava') + interval '1 hour')::time
  where shop_id = v_a;
  assert jsonb_array_length(public.telegram_notify_due(20)) = 0, 'waits in quiet hours';
  assert (select not_before > now() + interval '50 minutes' from public.telegram_outbox where ref_id = v_b2), 'moved to their end';
  update public.telegram_shop_prefs set quiet_from = null, quiet_to = null where shop_id = v_a;
  update public.telegram_outbox set not_before = now() where ref_id = v_b2;
  vj := public.telegram_notify_due(20);
  assert jsonb_array_length(vj) = 1 and vj -> 0 ->> 'kind' = 'booking_new' and vj -> 0 -> 'booking' ->> 'name' = 'Tg Dva'
     and not (vj -> 0 -> 'booking' ? 'phone') and (vj -> 0 ->> 'chat_id')::bigint = 9001, vj::text;
  assert jsonb_array_length(public.telegram_notify_due(20)) = 0, 'claimed once';
  perform public.telegram_notify_result((vj -> 0 ->> 'id')::bigint, true, null);
  assert (select status from public.telegram_outbox where ref_id = v_b2) = 'sent';
  -- the customer cancels → "zrušil"; the cap of the day skips it
  update public.shop_bookings set status = 'cancelled', status_changed_at = now() where id = v_b2;
  assert exists (select 1 from public.telegram_outbox where kind = 'booking_cancelled' and ref_id = v_b2), 'a cancellation';
  update public.telegram_settings set notify_daily_cap = 1 where id;
  assert jsonb_array_length(public.telegram_notify_due(20)) = 0, 'over the cap';
  assert (select reason from public.telegram_outbox where kind = 'booking_cancelled' and ref_id = v_b2) = 'daily_cap';
  update public.telegram_settings set notify_daily_cap = 30 where id;
  -- a failed send is tried again later, at most 5 times
  insert into public.telegram_outbox (link_id, shop_id, kind) select id, v_a, 'test' from public.telegram_links where tg_user_id = 9001;
  vj := public.telegram_notify_due(20);
  perform public.telegram_notify_result((vj -> 0 ->> 'id')::bigint, false, 'telegram');
  assert (select status = 'queued' and not_before > now() from public.telegram_outbox where id = (vj -> 0 ->> 'id')::bigint), 'retried later';
  delete from public.shop_bookings where id in (v_b1, v_b2) or name = 'Od majiteľa';
  delete from public.telegram_outbox;
  -- Pro ended: the bot stops for that shop
  update public.subscriptions set status = 'canceled', current_period_end = now() - interval '1 day' where shop_id = v_a;
  begin perform public.telegram_call(9001, 'get_shop_details', '{}'); raise exception 'works without Pro';
  exception when raise_exception then if sqlerrm <> 'no_plan' then raise; end if; end;
  assert not ((public.telegram_whoami(9001, false) -> 'shops' -> 0 ->> 'usable')::boolean), 'shown as not usable';
  update public.subscriptions set status = 'active', current_period_end = now() + interval '30 days' where shop_id = v_a;
  -- /odpojit: the grant revoked, the token gone, the link gone
  assert public.telegram_unlink_by_bot(9001);
  assert not exists (select 1 from public.telegram_links where tg_user_id = 9001);
  assert exists (select 1 from public.shop_activity where shop_id = v_a and action = 'telegram_disconnected');
  begin perform public.telegram_call(9001, 'get_shop_details', '{}'); raise exception 'works after unlinking';
  exception when invalid_authorization_specification then null; end;
end $$;
reset role;

do $$ begin
  assert not exists (select 1 from vault.secrets where name like 'ppi_tg_grant_%'), 'the token is deleted';
end $$;

-- visitors and other owners never reach the bot's functions
set role anon;
do $$ begin
  begin perform public.telegram_whoami(9001); raise exception 'anon whoami';
  exception when insufficient_privilege then null; end;
  begin perform public.telegram_call(9001, 'list_shops', '{}'); raise exception 'anon call';
  exception when insufficient_privilege then null; end;
end $$;
reset role;
set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000b';
do $$ begin
  begin perform public.telegram_claim('x', 1, 1, 'private', null, null); raise exception 'owner claimed';
  exception when insufficient_privilege then null; end;
  begin perform public.admin_save_telegram_settings(false, 1, 1); raise exception 'not admin';
  exception when insufficient_privilege then null; end;
end $$;
reset role;

set role service_role;
do $$
declare
  v_a uuid := (select id from public.shops where slug = 'potraviny-centrum');
begin
  delete from public.shop_special_hours where shop_id = v_a and date = (select v::date from t66 where k = 'd');
  delete from public.telegram_link_codes;
  delete from public.subscriptions where shop_id = v_a;
  insert into public.subscriptions
  select * from jsonb_populate_record(null::public.subscriptions, (select v::jsonb from t66 where k = 'sub'))
  where (select v from t66 where k = 'sub') is not null;
  assert public.shop_has_plan(v_a) = (select v::boolean from t66 where k = 'had_plan');
end $$;
reset role;
drop table t66;

\echo '--- update 67: Sklad v Cacaduu — the only writer while it is the source, movements once by their id, per location, transfer, freshness, plan limit, private costs'
create temporary table t67 (k text primary key, v text);
grant all on t67 to public;
create temporary table t67_inv as
  select inv.* from public.inventory inv join public.shop_items si on si.id = inv.shop_item_id
  join public.shops s on s.id = si.shop_id where s.slug = 'potraviny-centrum';
grant all on t67_inv to public;

set role service_role;
do $$
declare
  v_a uuid := (select id from public.shops where slug = 'potraviny-centrum');
begin
  insert into t67 values ('had_plan', public.shop_has_plan(v_a)::text),
    ('sub', (select to_jsonb(s) from public.subscriptions s where s.shop_id = v_a)::text),
    ('fresh', (select latest_file_time from public.sync_sources where shop_id = v_a)::text),
    ('items', (select count(*) from public.shop_items where shop_id = v_a)::text);
  delete from public.subscriptions where shop_id = v_a;   -- free: 50 Sklad products
  assert not public.shop_has_plan(v_a);
  assert public.sklad_product_limit(v_a) = 50;
end $$;
reset role;

-- the owner switches "Zdroj zásob" to Sklad: the existing products are taken over (opening count, the file's price)
set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000a';
do $$
declare
  v_a uuid := (select id from public.shops where slug = 'potraviny-centrum');
  vj jsonb;
begin
  assert (public.owner_stock_source(v_a) ->> 'active') = 'file';
  perform public.owner_set_stock_source(v_a, 'sklad');
  vj := public.owner_stock_source(v_a);
  assert vj ->> 'active' = 'sklad' and (vj ->> 'sklad_products')::int = (select v::int from t67 where k = 'items'), vj::text;
  vj := public.owner_sklad_overview(v_a);
  assert jsonb_array_length(vj -> 'locations') = 2 and vj -> 'locations' -> 0 ->> 'name' = 'Predajňa'
     and (vj -> 'locations' -> 0 ->> 'sale_default')::boolean and (vj -> 'locations' -> 1 ->> 'receipt_default')::boolean, vj::text;
  insert into t67 values ('shop', (vj -> 'locations' -> 0 ->> 'id')), ('back', (vj -> 'locations' -> 1 ->> 'id'));
  -- the folder / upload is refused while Sklad is the source
  begin perform public.upload_check_in(v_a); raise exception 'upload while sklad';
  exception when object_not_in_prerequisite_state then if sqlerrm <> 'sklad_active' then raise; end if; end;
  assert public.owner_inventory_can_connect(v_a, 'superfaktura') = 'sklad';
  -- a new product (price with VAT), then the plan limit
  insert into t67 values ('p', public.owner_sklad_save_product(v_a, null,
    '{"name":"Farba fasádna biela 5 l","ean":"8580000102315","sale_price":"24.90","min_qty":5,"supplier":"Dodávateľ s.r.o."}')::text);
  begin perform public.owner_sklad_save_product(v_a, null, '{"name":"Iná","ean":"8580000102315"}'); raise exception 'EAN twice';
  exception when unique_violation then if sqlerrm <> 'ean_taken' then raise; end if; end;
  vj := public.owner_sklad_product(v_a, (select v::uuid from t67 where k = 'p'));
  assert vj ->> 'code' ~ '^C[0-9]{5}$' and (vj ->> 'sale_price')::numeric = 24.90 and (vj ->> 'total')::numeric = 0
     and (vj ->> 'public')::boolean, vj::text;
end $$;
reset role;

-- movements: once by their id, per location, the total; a transfer keeps the total; the public side follows
set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000a';
do $$
declare
  v_a uuid := (select id from public.shops where slug = 'potraviny-centrum');
  v_p uuid := (select v::uuid from t67 where k = 'p');
  v_shop uuid := (select v::uuid from t67 where k = 'shop');
  v_back uuid := (select v::uuid from t67 where k = 'back');
  v_r uuid := gen_random_uuid();
  vj jsonb;
begin
  -- a receipt into "Sklad" (the receipt default) with a cost: twice with the same id = counted once
  vj := public.owner_sklad_move(v_a, v_r, v_p, 'receipt', 12, null, null, 15.80, null, 'P-1');
  assert not (vj ->> 'duplicate')::boolean and (vj ->> 'total')::numeric = 12, vj::text;
  vj := public.owner_sklad_move(v_a, v_r, v_p, 'receipt', 12, null, null, 15.80, null, 'P-1');
  assert (vj ->> 'duplicate')::boolean, 'the same id again: ' || vj::text;
  assert jsonb_array_length(public.owner_sklad_movements(v_a, v_p) -> 'rows') = 1;
  assert (public.owner_sklad_movements(v_a, v_p) ->> 'total')::int = 1;
  -- a transfer Sklad → Predajňa keeps the total
  vj := public.owner_sklad_move(v_a, gen_random_uuid(), v_p, 'transfer', 4, v_back, v_shop);
  assert (vj ->> 'total')::numeric = 12, vj::text;
  vj := public.owner_sklad_product(v_a, v_p);
  assert (select (l ->> 'qty')::numeric from jsonb_array_elements(vj -> 'locations') l where l ->> 'location_id' = v_shop::text) = 4
     and (select (l ->> 'qty')::numeric from jsonb_array_elements(vj -> 'locations') l where l ->> 'location_id' = v_back::text) = 8, vj::text;
  -- a sale (from Predajňa, the sale default), a write-off needs a reason, a count stores the difference
  vj := public.owner_sklad_move(v_a, gen_random_uuid(), v_p, 'sale', 2);
  assert (vj ->> 'total')::numeric = 10, vj::text;
  begin perform public.owner_sklad_move(v_a, gen_random_uuid(), v_p, 'writeoff', 1); raise exception 'write-off without a reason';
  exception when invalid_parameter_value then if sqlerrm <> 'reason' then raise; end if; end;
  perform public.owner_sklad_move(v_a, gen_random_uuid(), v_p, 'writeoff', 1, v_shop, null, null, 'poškodené vedro');
  vj := public.owner_sklad_move(v_a, gen_random_uuid(), v_p, 'count', 7, v_back);
  assert (vj ->> 'total')::numeric = 8, 'Sklad 8 counted 7, Predajňa 1: ' || vj::text;
  begin perform public.owner_sklad_move(v_a, gen_random_uuid(), v_p, 'correction', 1); raise exception 'correction without a reason';
  exception when invalid_parameter_value then if sqlerrm <> 'reason' then raise; end if; end;
  begin perform public.owner_sklad_move(v_a, gen_random_uuid(), v_p, 'transfer', 1, v_shop, v_shop); raise exception 'transfer to itself';
  exception when invalid_parameter_value then if sqlerrm <> 'to_location' then raise; end if; end;
  -- the private costs: last 15.80, average 15.80
  vj := public.owner_sklad_product(v_a, v_p);
  assert (vj ->> 'last_cost')::numeric = 15.80 and (vj ->> 'avg_cost')::numeric = 15.80 and vj ->> 'supplier' = 'Dodávateľ s.r.o.', vj::text;
  perform public.owner_sklad_move(v_a, gen_random_uuid(), v_p, 'receipt', 8, v_back, null, 16.80);
  vj := public.owner_sklad_product(v_a, v_p);
  assert (vj ->> 'avg_cost')::numeric = 16.3 and (vj ->> 'total')::numeric = 16, 'weighted average of 8 × 15.80 and 8 × 16.80: ' || vj::text;
end $$;
reset role;

-- the public side: quantity = the total, price = the sale price, current; nothing private
set role anon;
do $$
declare
  v_p uuid := (select v::uuid from t67 where k = 'p');
  r record;
begin
  select * into r from public.public_stock where item_id = v_p;
  assert r.quantity = 16 and r.price = 24.90 and r.currency = 'EUR' and r.freshness_state = 'current', row_to_json(r)::text;
  assert not exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'public_stock'
                       and column_name in ('last_cost', 'avg_cost', 'supplier', 'unit_cost')), 'costs in public_stock';
  begin perform count(*) from public.sklad_items; raise exception 'anon read sklad_items';
  exception when insufficient_privilege then null; end;
  begin perform count(*) from public.sklad_movements; raise exception 'anon read sklad_movements';
  exception when insufficient_privilege then null; end;
  begin perform count(*) from public.sklad_stock; raise exception 'anon read sklad_stock';
  exception when insufficient_privilege then null; end;
  begin perform public.owner_sklad_product((select id from public.shops where slug = 'potraviny-centrum'), v_p); raise exception 'anon card';
  exception when insufficient_privilege then null; end;
end $$;
reset role;

-- owner B: nothing of shop A; owners themselves read only through the functions
set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000b';
do $$
declare
  v_a uuid := (select id from public.shops where slug = 'potraviny-centrum');
  v_p uuid := (select v::uuid from t67 where k = 'p');
begin
  begin perform public.owner_sklad_product(v_a, v_p); raise exception 'B read A''s card';
  exception when insufficient_privilege then null; end;
  begin perform public.owner_sklad_move(v_a, gen_random_uuid(), v_p, 'sale', 1); raise exception 'B moved A''s stock';
  exception when insufficient_privilege then null; end;
  begin perform public.owner_sklad_confirm(v_a); raise exception 'B confirmed A';
  exception when insufficient_privilege then null; end;
  assert public.owner_sklad_find(v_a, '8580000102315') is null, 'B found A''s product';
  begin perform count(*) from public.sklad_items; raise exception 'owners read the table';
  exception when insufficient_privilege then null; end;
end $$;
reset role;

-- every other writer is refused while Sklad is the source; movements are append-only
set role service_role;
do $$
declare
  v_p uuid := (select v::uuid from t67 where k = 'p');
begin
  begin update public.inventory set quantity = 99 where shop_item_id = v_p; raise exception 'a file wrote the stock';
  exception when object_not_in_prerequisite_state then if sqlerrm <> 'sklad_active' then raise; end if; end;
  begin update public.sklad_movements set qty = 99 where shop_item_id = v_p; raise exception 'a movement was changed';
  exception when object_not_in_prerequisite_state then if sqlerrm <> 'sklad_append_only' then raise; end if; end;
  begin delete from public.sklad_movements where shop_item_id = v_p; raise exception 'a movement was deleted';
  exception when object_not_in_prerequisite_state then if sqlerrm <> 'sklad_append_only' then raise; end if; end;
  begin delete from public.shop_items where id = v_p; raise exception 'a Sklad product was deleted';
  exception when object_not_in_prerequisite_state then if sqlerrm <> 'sklad_item' then raise; end if; end;
  -- 25 hours without a movement or a confirmation → stale (no availability on the shop page)
  update public.sync_sources set latest_file_time = now() - interval '25 hours'
  where shop_id = (select id from public.shops where slug = 'potraviny-centrum');
  assert (select freshness_state from public.public_stock where item_id = v_p) = 'stale';
  assert (select availability from public.public_stock where item_id = v_p) is null;
end $$;
reset role;

-- "Stav je správny" makes it current again; a product without a sale price is not public; the plan limit
set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000a';
do $$
declare
  v_a uuid := (select id from public.shops where slug = 'potraviny-centrum');
  v_p uuid := (select v::uuid from t67 where k = 'p');
  vj jsonb;
  n integer := 0;
begin
  assert (public.owner_sklad_overview(v_a) ->> 'needs_check')::boolean is false, 'moved today';
  perform public.owner_sklad_confirm(v_a);
  assert (select freshness_state from public.public_stock where item_id = v_p) = 'current';
  assert (public.owner_sklad_overview(v_a) ->> 'confirmed_at') is not null;
  perform public.owner_sklad_save_product(v_a, v_p, '{"sale_price":""}');
  assert not exists (select 1 from public.public_stock where item_id = v_p), 'no price → not public';
  assert ((public.owner_sklad_products(v_a, null, 'no_price')) -> 'counts' ->> 'no_price')::int >= 1;
  perform public.owner_sklad_save_product(v_a, v_p, '{"sale_price":"24.90"}');
  assert (select quantity from public.public_stock where item_id = v_p) = 16;
  -- search: accent-insensitive name, code, EAN
  vj := public.owner_sklad_products(v_a, 'fasadna');
  assert jsonb_array_length(vj -> 'rows') = 1, vj::text;
  assert public.owner_sklad_find(v_a, '8580000102315') = v_p;
  -- the plan limit: free 50 products, then plan_limit (no more)
  loop
    begin
      perform public.owner_sklad_save_product(v_a, null, jsonb_build_object('name', 'Test ' || n));
    exception when raise_exception then
      if sqlerrm <> 'plan_limit' then raise; end if;
      exit;
    end;
    n := n + 1;
    if n > 60 then raise exception 'no plan limit'; end if;
  end loop;
  assert (public.owner_stock_source(v_a) ->> 'sklad_products')::int = 50, 'stopped at 50';
end $$;
reset role;

-- the reminder: due after the reminder time when today had no movement and no confirmation, claimed once
set role service_role;
do $$
declare
  v_a uuid := (select id from public.shops where slug = 'potraviny-centrum');
begin
  update public.sklad_settings set reminder_time = '00:00', confirmed_at = now() - interval '2 days', reminded_on = null where shop_id = v_a;
  assert not exists (select 1 from public.sklad_reminders_due() d where d.shop_id = v_a), 'moved today: no reminder';
end $$;
reset role;

-- back to files: allowed, nothing of Sklad is deleted; uploads work again
set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000a';
do $$
declare
  v_a uuid := (select id from public.shops where slug = 'potraviny-centrum');
begin
  perform public.owner_set_stock_source(v_a, 'file');
  assert (public.owner_stock_source(v_a) ->> 'active') = 'file';
  perform public.upload_check_in(v_a);
  assert (public.owner_stock_source(v_a) ->> 'sklad_products')::int = 50, 'Sklad kept';
end $$;
reset role;

set role service_role;
do $$
declare
  v_a uuid := (select id from public.shops where slug = 'potraviny-centrum');
begin
  delete from public.sklad_items where shop_id = v_a;
  delete from public.shop_items si where si.shop_id = v_a and not exists (select 1 from t67_inv t where t.shop_item_id = si.id);
  delete from public.sklad_locations where shop_id = v_a;
  delete from public.sklad_settings where shop_id = v_a;
  delete from public.shop_stock_source where shop_id = v_a;
  delete from public.inventory inv using public.shop_items si where si.id = inv.shop_item_id and si.shop_id = v_a;
  insert into public.inventory select * from t67_inv;
  update public.sync_sources set latest_file_time = (select v::timestamptz from t67 where k = 'fresh') where shop_id = v_a;
  insert into public.subscriptions
  select * from jsonb_populate_record(null::public.subscriptions, (select v::jsonb from t67 where k = 'sub'))
  where (select v from t67 where k = 'sub') is not null;
  assert public.shop_has_plan(v_a) = (select v::boolean from t67 where k = 'had_plan');
  assert (select count(*) from public.shop_items where shop_id = v_a) = (select v::int from t67 where k = 'items');
end $$;
reset role;
drop table t67;
drop table t67_inv;

\echo '--- update 68: Sklad Predaj — one sale by its id, lines added up, no price refused, QR waits for Zaplatené, cancel, IBAN, owners only'
create temporary table t68 (k text primary key, v text);
grant all on t68 to public;
create temporary table t68_inv as
  select inv.* from public.inventory inv join public.shop_items si on si.id = inv.shop_item_id
  join public.shops s on s.id = si.shop_id where s.slug = 'potraviny-centrum';
grant all on t68_inv to public;

set role service_role;
do $$
declare
  v_a uuid := (select id from public.shops where slug = 'potraviny-centrum');
begin
  insert into t68 values ('fresh', (select latest_file_time from public.sync_sources where shop_id = v_a)::text);
  assert public.sklad_iban('SK96 1100 0000 0029 1859 9669') = 'SK9611000000002918599669';
  assert public.sklad_iban('sk9611000000002918599669') = 'SK9611000000002918599669';
  assert public.sklad_iban('SK9611000000002918599668') is null, 'wrong check digits';
  assert public.sklad_iban('nie je iban') is null;
end $$;
reset role;

set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000a';
do $$
declare
  v_a uuid := (select id from public.shops where slug = 'potraviny-centrum');
  v_p uuid;
  v_np uuid;
  v_s1 uuid := gen_random_uuid();
  vj jsonb;
begin
  perform public.owner_set_stock_source(v_a, 'sklad');
  v_p := public.owner_sklad_save_product(v_a, null, '{"name":"Štetec plochý 50 mm","ean":"8580000300124","sale_price":"3.20"}');
  v_np := public.owner_sklad_save_product(v_a, null, '{"name":"Bez ceny","ean":"8580000300131"}');
  perform public.owner_sklad_move(v_a, gen_random_uuid(), v_p, 'receipt', 10);
  insert into t68 values ('p', v_p::text), ('np', v_np::text), ('s1', v_s1::text);
  -- cash: the same product twice is added up; taken off at once; the public side follows
  vj := public.owner_sklad_sell(v_a, v_s1, jsonb_build_array(jsonb_build_object('item_id', v_p, 'qty', 2),
                                                             jsonb_build_object('item_id', v_p, 'qty', 1)), 'cash');
  assert vj ->> 'status' = 'done' and (vj ->> 'total')::numeric = 9.60 and (vj ->> 'pieces')::numeric = 3
     and jsonb_array_length(vj -> 'lines') = 1 and vj ->> 'vs' ~ '^[0-9]{10}$' and not (vj ->> 'duplicate')::boolean, vj::text;
  insert into t68 values ('vs1', vj ->> 'vs');
  assert (public.owner_sklad_product(v_a, v_p) ->> 'total')::numeric = 7;
  assert (select quantity from public.public_stock where item_id = v_p) = 7, 'shop page follows the sale';
  -- the same sale again (a double tap): nothing more taken off
  vj := public.owner_sklad_sell(v_a, v_s1, jsonb_build_array(jsonb_build_object('item_id', v_p, 'qty', 3)), 'cash');
  assert (vj ->> 'duplicate')::boolean and (public.owner_sklad_product(v_a, v_p) ->> 'total')::numeric = 7, vj::text;
  assert (public.owner_sklad_movements(v_a, v_p, 'sale') ->> 'total')::int = 1;
  -- refusals
  begin perform public.owner_sklad_sell(v_a, gen_random_uuid(), jsonb_build_array(jsonb_build_object('item_id', v_np, 'qty', 1)), 'card');
    raise exception 'sold without a price';
  exception when object_not_in_prerequisite_state then if sqlerrm <> 'no_price' then raise; end if; end;
  begin perform public.owner_sklad_sell(v_a, gen_random_uuid(), '[]', 'cash'); raise exception 'empty basket';
  exception when invalid_parameter_value then if sqlerrm <> 'empty' then raise; end if; end;
  begin perform public.owner_sklad_sell(v_a, gen_random_uuid(), jsonb_build_array(jsonb_build_object('item_id', v_p, 'qty', 0)), 'cash');
    raise exception 'zero pieces';
  exception when invalid_parameter_value then if sqlerrm <> 'qty' then raise; end if; end;
  begin perform public.owner_sklad_sell(v_a, gen_random_uuid(), jsonb_build_array(jsonb_build_object('item_id', gen_random_uuid(), 'qty', 1)), 'cash');
    raise exception 'unknown product';
  exception when no_data_found then if sqlerrm <> 'not_found' then raise; end if; end;
  begin perform public.owner_sklad_sell(v_a, gen_random_uuid(), jsonb_build_array(jsonb_build_object('item_id', v_p, 'qty', 1)), 'qr');
    raise exception 'QR without an IBAN';
  exception when object_not_in_prerequisite_state then if sqlerrm <> 'no_iban' then raise; end if; end;
  -- the IBAN: checked, kept clean
  begin perform public.owner_sklad_save_payment(v_a, 'SK9611000000002918599668', null, null); raise exception 'bad IBAN saved';
  exception when invalid_parameter_value then if sqlerrm <> 'iban' then raise; end if; end;
  perform public.owner_sklad_save_payment(v_a, 'SK96 1100 0000 0029 1859 9669', 'tatrskbx', 'Potraviny Centrum');
  vj := public.owner_sklad_payment(v_a);
  assert vj ->> 'iban' = 'SK9611000000002918599669' and vj ->> 'bic' = 'TATRSKBX' and vj ->> 'payee' = 'Potraviny Centrum', vj::text;
  assert (public.owner_sklad_sale_info(v_a) ->> 'qr_ready')::boolean;
end $$;
reset role;

-- QR: waits (nothing taken off), the terminal shows it, "Zaplatené" takes it off once; cancel only while waiting
set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000a';
do $$
declare
  v_a uuid := (select id from public.shops where slug = 'potraviny-centrum');
  v_p uuid := (select v::uuid from t68 where k = 'p');
  v_s2 uuid := gen_random_uuid();
  v_s3 uuid := gen_random_uuid();
  vj jsonb;
begin
  vj := public.owner_sklad_sell(v_a, v_s2, jsonb_build_array(jsonb_build_object('item_id', v_p, 'qty', 2)), 'qr');
  assert vj ->> 'status' = 'pending' and vj ->> 'iban' = 'SK9611000000002918599669' and vj ->> 'payee' = 'Potraviny Centrum'
     and vj ->> 'vs' <> (select v from t68 where k = 'vs1')
     and right(vj ->> 'vs', 4)::int = right((select v from t68 where k = 'vs1'), 4)::int + 1, vj::text;
  assert (public.owner_sklad_product(v_a, v_p) ->> 'total')::numeric = 7, 'a waiting QR sale takes nothing off';
  vj := public.owner_sklad_terminal(v_a);
  assert vj ->> 'state' = 'waiting' and (vj ->> 'id')::uuid = v_s2 and (vj ->> 'total')::numeric = 6.40, vj::text;
  vj := public.owner_sklad_sale_paid(v_a, v_s2);
  assert vj ->> 'status' = 'done' and not (vj ->> 'duplicate')::boolean, vj::text;
  assert (public.owner_sklad_product(v_a, v_p) ->> 'total')::numeric = 5;
  vj := public.owner_sklad_sale_paid(v_a, v_s2);
  assert (vj ->> 'duplicate')::boolean and (public.owner_sklad_product(v_a, v_p) ->> 'total')::numeric = 5, vj::text;
  assert public.owner_sklad_terminal(v_a) ->> 'state' = 'paid';
  begin perform public.owner_sklad_sale_cancel(v_a, v_s2); raise exception 'a finished sale cancelled';
  exception when object_not_in_prerequisite_state then if sqlerrm <> 'done' then raise; end if; end;
  -- a second QR sale cancelled: nothing taken off, "Zaplatené" refused afterwards
  perform public.owner_sklad_sell(v_a, v_s3, jsonb_build_array(jsonb_build_object('item_id', v_p, 'qty', 1)), 'qr');
  vj := public.owner_sklad_sale_cancel(v_a, v_s3);
  assert vj ->> 'status' = 'cancelled', vj::text;
  begin perform public.owner_sklad_sale_paid(v_a, v_s3); raise exception 'a cancelled sale paid';
  exception when object_not_in_prerequisite_state then if sqlerrm <> 'cancelled' then raise; end if; end;
  assert (public.owner_sklad_product(v_a, v_p) ->> 'total')::numeric = 5;
  insert into t68 values ('s4', public.owner_sklad_sell(v_a, gen_random_uuid(),
    jsonb_build_array(jsonb_build_object('item_id', v_p, 'qty', 1)), 'qr') ->> 'id');
  vj := public.owner_sklad_sale_info(v_a);
  assert (vj -> 'today' ->> 'sales')::int = 2 and (vj -> 'today' ->> 'total')::numeric = 16.00
     and jsonb_array_length(vj -> 'pending') = 1, vj::text;
end $$;
reset role;

-- a QR sale left waiting for 24 hours is cancelled
set role service_role;
update public.sklad_sales set created_at = now() - interval '25 hours' where id = (select v::uuid from t68 where k = 's4');
reset role;
set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000a';
do $$
declare
  v_a uuid := (select id from public.shops where slug = 'potraviny-centrum');
begin
  assert public.owner_sklad_sale(v_a, (select v::uuid from t68 where k = 's4')) ->> 'status' = 'cancelled';
  assert public.owner_sklad_terminal(v_a) ->> 'state' in ('paid', 'standby');
end $$;
reset role;

-- owner B and visitors: nothing
set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000b';
do $$
declare
  v_a uuid := (select id from public.shops where slug = 'potraviny-centrum');
  v_p uuid := (select v::uuid from t68 where k = 'p');
begin
  begin perform public.owner_sklad_sell(v_a, gen_random_uuid(), jsonb_build_array(jsonb_build_object('item_id', v_p, 'qty', 1)), 'cash');
    raise exception 'B sold A''s goods';
  exception when insufficient_privilege then null; end;
  begin perform public.owner_sklad_terminal(v_a); raise exception 'B saw A''s terminal';
  exception when insufficient_privilege then null; end;
  begin perform public.owner_sklad_payment(v_a); raise exception 'B read A''s IBAN';
  exception when insufficient_privilege then null; end;
  begin perform count(*) from public.sklad_sales; raise exception 'owners read the sales table';
  exception when insufficient_privilege then null; end;
end $$;
reset role;
set role anon;
do $$
begin
  begin perform count(*) from public.sklad_sales; raise exception 'anon read sales';
  exception when insufficient_privilege then null; end;
  begin perform public.owner_sklad_terminal((select id from public.shops where slug = 'potraviny-centrum')); raise exception 'anon terminal';
  exception when insufficient_privilege then null; end;
end $$;
reset role;

set role service_role;
do $$
declare
  v_a uuid := (select id from public.shops where slug = 'potraviny-centrum');
begin
  delete from public.sklad_sales where shop_id = v_a;
  delete from public.sklad_items where shop_id = v_a;
  delete from public.shop_items si where si.shop_id = v_a and not exists (select 1 from t68_inv t where t.shop_item_id = si.id);
  delete from public.sklad_locations where shop_id = v_a;
  delete from public.sklad_settings where shop_id = v_a;
  delete from public.shop_stock_source where shop_id = v_a;
  delete from public.inventory inv using public.shop_items si where si.id = inv.shop_item_id and si.shop_id = v_a;
  insert into public.inventory select * from t68_inv;
  update public.sync_sources set latest_file_time = (select v::timestamptz from t68 where k = 'fresh') where shop_id = v_a;
end $$;
reset role;
drop table t68;
drop table t68_inv;

\echo '--- update 69: Sklad Príjemky — draft, numbered, new products made on confirm, once by line ids, costs, supplier, AI matching, owners only'
create temporary table t69 (k text primary key, v text);
grant all on t69 to public;
create temporary table t69_inv as
  select inv.* from public.inventory inv join public.shop_items si on si.id = inv.shop_item_id
  join public.shops s on s.id = si.shop_id where s.slug = 'potraviny-centrum';
grant all on t69_inv to public;
set role service_role;
insert into t69 values ('fresh', (select latest_file_time::text from public.sync_sources s join public.shops sh on sh.id = s.shop_id where sh.slug = 'potraviny-centrum'));
reset role;

set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000a';
do $$
declare
  v_a uuid := (select id from public.shops where slug = 'potraviny-centrum');
  v_p uuid;
  v_back uuid;
  v_r uuid := gen_random_uuid();
  vj jsonb;
begin
  perform public.owner_set_stock_source(v_a, 'sklad');
  v_p := public.owner_sklad_save_product(v_a, null, '{"name":"Farba fasádna biela 5 l","ean":"8580000102315","sale_price":"24.90"}');
  v_back := (select (l ->> 'id')::uuid from jsonb_array_elements(public.owner_sklad_overview(v_a) -> 'locations') l where (l ->> 'receipt_default')::boolean);
  insert into t69 values ('p', v_p::text), ('r', v_r::text), ('back', v_back::text);
  -- a draft: numbered, the receipt location by default, totals without VAT
  vj := public.owner_sklad_receipt_save(v_a, v_r, jsonb_build_object('supplier', 'Dodávateľ s.r.o.', 'invoice_no', 'FA2026-0187',
          'delivered_on', '2026-10-28', 'lines', jsonb_build_array(
            jsonb_build_object('item_id', v_p, 'qty', 12, 'unit_cost', '15.80', 'src', 'Fasád.farba biela 5L'),
            jsonb_build_object('item_id', null, 'name', 'Lazúra na drevo teak 0,75 l', 'ean', '8580000208734', 'qty', 6, 'unit_cost', '7.40', 'sale_price', '12.90'))));
  assert vj ->> 'status' = 'draft' and vj ->> 'number' ~ '^P-[0-9]{4}-001$' and (vj ->> 'location_id')::uuid = v_back
     and (vj ->> 'total')::numeric = 234.00 and (vj ->> 'pieces')::numeric = 18, vj::text;
  assert (public.owner_sklad_product(v_a, v_p) ->> 'total')::numeric = 0, 'a draft stocks nothing';
  -- saved again: the same number, the lines replaced
  vj := public.owner_sklad_receipt_save(v_a, v_r, jsonb_build_object('lines', vj -> 'lines'));
  assert vj ->> 'number' ~ '-001$' and jsonb_array_length(vj -> 'lines') = 2, vj::text;
  -- refusals
  begin perform public.owner_sklad_receipt_save(v_a, gen_random_uuid(), '{"lines":[{"item_id":null,"qty":1}]}'); raise exception 'new product without a name';
  exception when invalid_parameter_value then if sqlerrm <> 'name' then raise; end if; end;
  begin perform public.owner_sklad_receipt_save(v_a, gen_random_uuid(), '{"lines":[{"item_id":null,"name":"x","qty":0}]}'); raise exception 'zero';
  exception when invalid_parameter_value then if sqlerrm <> 'qty' then raise; end if; end;
  begin perform public.owner_sklad_receipt_confirm(v_a, (public.owner_sklad_receipt_save(v_a, gen_random_uuid(), '{}') ->> 'id')::uuid);
    raise exception 'empty receipt confirmed';
  exception when invalid_parameter_value then if sqlerrm <> 'empty' then raise; end if; end;
  -- confirm: the new product made, both stocked once, costs and supplier kept
  vj := public.owner_sklad_receipt_confirm(v_a, v_r);
  assert vj ->> 'status' = 'done' and not (vj ->> 'duplicate')::boolean and (vj -> 'lines' -> 1 ->> 'item_id') is not null, vj::text;
  insert into t69 values ('new', vj -> 'lines' -> 1 ->> 'item_id');
  vj := public.owner_sklad_product(v_a, v_p);
  assert (vj ->> 'total')::numeric = 12 and (vj ->> 'last_cost')::numeric = 15.80 and vj ->> 'supplier' = 'Dodávateľ s.r.o.', vj::text;
  vj := public.owner_sklad_product(v_a, (select v::uuid from t69 where k = 'new'));
  assert vj ->> 'name' = 'Lazúra na drevo teak 0,75 l' and vj ->> 'ean' = '8580000208734' and (vj ->> 'sale_price')::numeric = 12.90
     and (vj ->> 'total')::numeric = 6 and (vj ->> 'avg_cost')::numeric = 7.40 and (vj ->> 'public')::boolean, vj::text;
  assert (select quantity from public.public_stock where item_id = v_p) = 12, 'the shop page follows';
  -- a second "Potvrdiť": nothing counted twice; a confirmed receipt never changes
  vj := public.owner_sklad_receipt_confirm(v_a, v_r);
  assert (vj ->> 'duplicate')::boolean and (public.owner_sklad_product(v_a, v_p) ->> 'total')::numeric = 12, vj::text;
  assert (public.owner_sklad_movements(v_a, v_p, 'receipt') ->> 'total')::int = 1;
  assert (public.owner_sklad_movements(v_a, v_p, 'receipt') -> 'rows' -> 0 ->> 'ref') like 'P-%-001 · FA2026-0187';
  begin perform public.owner_sklad_receipt_save(v_a, v_r, '{"supplier":"iný"}'); raise exception 'done receipt changed';
  exception when object_not_in_prerequisite_state then if sqlerrm <> 'done' then raise; end if; end;
  begin perform public.owner_sklad_receipt_discard(v_a, v_r); raise exception 'done receipt discarded';
  exception when object_not_in_prerequisite_state then if sqlerrm <> 'done' then raise; end if; end;
  -- a second draft numbered 002, discarded: kept, not listed, never confirmable
  vj := public.owner_sklad_receipt_save(v_a, gen_random_uuid(), jsonb_build_object('lines', jsonb_build_array(jsonb_build_object('item_id', v_p, 'qty', 1))));
  assert vj ->> 'number' ~ '-002$' or vj ->> 'number' ~ '-00[2-9]$', vj::text;
  perform public.owner_sklad_receipt_discard(v_a, (vj ->> 'id')::uuid);
  begin perform public.owner_sklad_receipt_confirm(v_a, (vj ->> 'id')::uuid); raise exception 'discarded confirmed';
  exception when object_not_in_prerequisite_state then if sqlerrm <> 'discarded' then raise; end if; end;
  vj := public.owner_sklad_receipts(v_a);
  assert not exists (select 1 from jsonb_array_elements(vj -> 'rows') r where r ->> 'status' = 'discarded')
     and vj -> 'suppliers' ? 'Dodávateľ s.r.o.', vj::text;
  -- the AI's lines paired in SQL: EAN, name, a new product
  vj := public.owner_sklad_match(v_a, jsonb_build_array(
          jsonb_build_object('text', 'Fasad.farba 5L', 'ean', '8580000102315'),
          jsonb_build_object('text', 'Lazura na drevo teak 0,75 l'),
          jsonb_build_object('text', 'Úplne iný tovar XYZ 123')));
  assert vj -> 0 ->> 'kind' = 'ean' and (vj -> 0 ->> 'item_id')::uuid = v_p
     and vj -> 1 ->> 'kind' in ('name', 'unsure') and vj -> 2 ->> 'kind' = 'new', vj::text;
  -- the AI's daily readings
  assert public.sklad_ai_hit(v_a);
end $$;
reset role;

