  assert (vj ->> 'names')::int = 3 and (vj ->> 'paired')::int = 2 and vj -> 'missing' = '["Tiramisu"]'::jsonb, vj::text;
  assert public.owner_food_settings(v_a) -> 'menu_check' ->> 'document' = 'jedalny-listok.pdf';
