drop table t74;

\echo '--- update 75: Objednávky jedla F4 — couriers: the owner adds and invites them, an SMS code without an account (an unknown number looks the same), one key per courier, the door shows only the courier''s own deliveries, payment marks only as allowed, cash held and settled, auto-assignment, switched off = signed out'
create temporary table t75 (k text primary key, v text);
grant all on t75 to public;

set role service_role;
do $$
declare
  v_a uuid := (select id from public.shops where slug = 'potraviny-centrum');
  v_tz text := (select coalesce(timezone, 'UTC') from public.shops where id = v_a);
  v_open jsonb;
begin
  insert into t75 values ('had_plan', public.shop_has_plan(v_a)::text),
    ('sub', (select to_jsonb(s) from public.subscriptions s where s.shop_id = v_a)::text),
    ('day', ((now() at time zone v_tz)::date)::text);
  insert into public.subscriptions (shop_id, status, plan, current_period_end, stripe_subscription_id)
  values (v_a, 'active', 'pro', now() + interval '30 days', 'sub_test_75')
  on conflict (shop_id) do update set status = 'active', current_period_end = now() + interval '30 days';
  insert into public.shop_special_hours (shop_id, date, closed, ranges)
  values (v_a, (now() at time zone v_tz)::date, false, '[["00:00","23:59"]]')
  on conflict (shop_id, date) do update set closed = false, ranges = excluded.ranges;
  v_open := public.assistant_open(v_a, 'sk', repeat('8', 32));
  insert into t75 values ('conv', v_open ->> 'id'), ('token', v_open ->> 'token'),
    ('pizza', (select si.id::text from public.sklad_items i join public.shop_items si on si.id = i.shop_item_id
               where i.shop_id = v_a and si.name = 'Margherita 32 cm'));
  assert (select v from t75 where k = 'pizza') is not null, 'update 73''s Sklad product is there';
end $$;
reset role;

-- the owner: ordering with delivery on, two couriers (numbers cleaned by the shop's country), the rules of the list
set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000a';
do $$
declare
  v_a uuid := (select id from public.shops where slug = 'potraviny-centrum');
  vj jsonb;
  v_michal uuid;
begin
  perform public.owner_food_save_settings(v_a, '{"enabled": true, "delivery_on": true, "pickup_on": true, "pay_cash": true, "pay_qr": true, "pay_card": true, "assign_mode": "manual"}');
  vj := public.owner_food_courier_save(v_a, null, '  Michal  ', '0915 123 220', null);
  v_michal := (vj ->> 'id')::uuid;
  assert (vj ->> 'active')::boolean and vj ->> 'name' = 'Michal', vj::text;
  assert (select c ->> 'phone' from jsonb_array_elements(public.owner_food_couriers(v_a) -> 'couriers') c
          where c ->> 'id' = v_michal::text) = '+421915123220', 'E.164 by the shop''s country';
  vj := public.owner_food_courier_save(v_a, null, 'Rasťo', '+421944000071', null);
  insert into t75 values ('michal', v_michal::text), ('rasto', vj ->> 'id');
  begin perform public.owner_food_courier_save(v_a, null, 'Iný', '0915123220', null); raise exception 'the same number twice';
  exception when unique_violation then null; end;
  begin perform public.owner_food_courier_save(v_a, null, 'Iný', 'abc', null); raise exception 'a number that is not one';
  exception when invalid_parameter_value then assert sqlerrm = 'phone'; end;
  begin perform public.owner_food_courier_save(v_a, null, ' ', '0915000001', null); raise exception 'a courier without a name';
  exception when invalid_parameter_value then assert sqlerrm = 'name'; end;
  -- saving without the active flag keeps it as it is
  perform public.owner_food_courier_save(v_a, v_michal, 'Michal', '0915 123 220', null);
  assert (select (c ->> 'active')::boolean from jsonb_array_elements(public.owner_food_couriers(v_a) -> 'couriers') c
          where c ->> 'id' = v_michal::text);
  vj := public.owner_food_couriers(v_a);
  assert jsonb_array_length(vj -> 'couriers') = 2 and vj ->> 'assign_mode' = 'manual'
     and (vj ->> 'courier_can_qr')::boolean and not (vj ->> 'courier_has_card')::boolean, vj::text;
  -- the invite: the address of the shop's courier login, no key in it; the owner quota; not twice in 2 minutes
  vj := public.owner_food_courier_invite(v_a, v_michal, 'https://cacaduu.com', 'sk');
  assert vj ->> 'body' like '%https://cacaduu.com/sk/kurier/prihlasenie/potraviny-centrum' and vj ->> 'recipient' = '+421915123220', vj::text;
  insert into t75 values ('invite', vj ->> 'id');
  begin perform public.owner_food_courier_invite(v_a, v_michal, 'https://cacaduu.com', 'sk'); raise exception 'invited twice at once';
  exception when program_limit_exceeded then assert sqlerrm = 'too_many'; end;
  begin perform public.owner_food_courier_invite(v_a, (vj ->> 'id')::uuid, 'javascript:alert(1)', 'sk'); raise exception 'any site';
  exception when invalid_parameter_value then assert sqlerrm = 'site'; end;
end $$;
reset role;

-- another owner cannot see or change A's couriers
set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000b';
do $$
declare
  v_a uuid := (select id from public.shops where slug = 'potraviny-centrum');
begin
  begin perform public.owner_food_couriers(v_a); raise exception 'owner B listed A''s couriers';
  exception when insufficient_privilege then null; end;
  begin perform public.owner_food_courier_save(v_a, null, 'Cudzí', '0915000002', null); raise exception 'owner B added a courier';
  exception when insufficient_privilege then null; end;
end $$;
reset role;

-- the login code: a courier's number gets a code, an unknown number the same answer and nothing to send
set role service_role;
do $$
declare
  v_real jsonb;
  v_fake jsonb;
  v_msg uuid;
begin
  assert (select kind from public.shop_outgoing_messages where id = (select v::uuid from t75 where k = 'invite')) = 'owner';
  v_fake := public.food_courier_code_start('potraviny-centrum', '0915 999 999', repeat('6', 32));
  assert not (v_fake ->> 'send')::boolean and v_fake ->> 'code' is null and v_fake ? 'id', v_fake::text;
  v_real := public.food_courier_code_start('potraviny-centrum', '0915 123 220', repeat('6', 32));
  assert (v_real ->> 'send')::boolean and v_real ->> 'code' ~ '^[0-9]{6}$', v_real::text;
  v_msg := public.food_courier_code_claim((v_real ->> 'id')::uuid, 'Potraviny: kód ' || (v_real ->> 'code'));
  assert (select kind = 'phone_code' and body = 'Potraviny: kód ••••••' from public.shop_outgoing_messages where id = v_msg);
  assert public.booking_sms_settle(v_msg, 'test', 'test', null, null), 'courier codes are settled now';
  begin perform public.food_courier_code_claim((v_fake ->> 'id')::uuid, 'x'); raise exception 'the unknown number''s code was sent';
  exception when no_data_found then null; end;
  insert into t75 values ('code_id', v_real ->> 'id'), ('code', v_real ->> 'code'), ('fake_id', v_fake ->> 'id');
end $$;
reset role;

set role anon;
do $$
declare
  vj jsonb;
begin
  vj := public.food_courier_login((select v::uuid from t75 where k = 'fake_id'), '123456');
  assert not (vj ->> 'ok')::boolean and vj ->> 'reason' = 'wrong_code', vj::text;
  vj := public.food_courier_login((select v::uuid from t75 where k = 'code_id'), '000000');
  assert vj ->> 'reason' = 'wrong_code' and (vj ->> 'attempts_left')::int = 4, vj::text;
  vj := public.food_courier_login((select v::uuid from t75 where k = 'code_id'), (select v from t75 where k = 'code'));
  assert (vj ->> 'ok')::boolean and vj ->> 'key' ~ '^ckr_[0-9a-f]{64}$' and vj ->> 'name' = 'Michal', vj::text;
  insert into t75 values ('key', vj ->> 'key');
  -- a code works once
  vj := public.food_courier_login((select v::uuid from t75 where k = 'code_id'), (select v from t75 where k = 'code'));
  assert not (vj ->> 'ok')::boolean, vj::text;
  -- the door: who, nothing to deliver yet; a made-up key is refused
  vj := public.food_courier_call((select v from t75 where k = 'key'), 'whoami', '{}');
  assert vj -> 'courier' ->> 'name' = 'Michal' and vj -> 'shop' ->> 'slug' = 'potraviny-centrum'
     and (vj -> 'perms' ->> 'cash')::boolean and not (vj -> 'perms' ->> 'card')::boolean and (vj ->> 'open')::int = 0, vj::text;
  begin perform public.food_courier_call('ckr_' || repeat('0', 64), 'whoami', '{}'); raise exception 'a made-up key';
  exception when invalid_authorization_specification then null; end;
  begin perform public.food_courier_call((select v from t75 where k = 'key'), 'owner_food_orders', '{}'); raise exception 'any function';
  exception when invalid_parameter_value then assert sqlerrm = 'fn'; end;
end $$;
reset role;
-- the key's hash only, never the key
do $$
begin
  assert not exists (select 1 from public.food_courier_sessions where token_hash = (select v from t75 where k = 'key'));
  assert exists (select 1 from public.food_courier_sessions where token_hash = public.food_courier_hash((select v from t75 where k = 'key')));
end $$;

-- two orders; the owner gives the first to Michal (a retry of the same step changes nothing)
set role service_role;
do $$
declare
  v_conv uuid := (select v::uuid from t75 where k = 'conv');
  v_token text := (select v from t75 where k = 'token');
  v_code jsonb;
  vj jsonb;
  i int;
begin
  for i in 1..2 loop
    v_code := public.sms_code_start('potraviny-centrum', 'order', '0907 111 27' || i, 'Eva K.', repeat('5', 32), v_conv, v_token);
    vj := public.food_order_create((v_code ->> 'id')::uuid, v_code ->> 'code', gen_random_uuid(),
            jsonb_build_array(jsonb_build_object('item_id', (select v from t75 where k = 'pizza'), 'qty', 2)),
            'delivery', 'cash', 'Hlavná 8, Michalovce', 'Vchod z dvora', null, null, v_conv, v_token, 'sk');
    assert (vj ->> 'ok')::boolean, vj::text;
    insert into t75 values ('order' || i, vj -> 'order' ->> 'id');
  end loop;
end $$;
reset role;
set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000a';
do $$
declare
  v_a uuid := (select id from public.shops where slug = 'potraviny-centrum');
  v_step uuid := gen_random_uuid();
  vj jsonb;
begin
  assert public.owner_food_order(v_a, (select v::uuid from t75 where k = 'order1')) ->> 'courier_id' is null, 'manual: nobody yet';
  vj := public.owner_food_assign(v_a, (select v::uuid from t75 where k = 'order1'), (select v::uuid from t75 where k = 'michal'), v_step);
  assert vj ->> 'courier_name' = 'Michal' and not (vj ->> 'duplicate')::boolean, vj::text;
  vj := public.owner_food_assign(v_a, (select v::uuid from t75 where k = 'order1'), null, v_step);
  assert (vj ->> 'duplicate')::boolean and vj ->> 'courier_name' = 'Michal', 'the same step once';
  assert exists (select 1 from jsonb_array_elements(public.owner_food_order(v_a, (select v::uuid from t75 where k = 'order1')) -> 'events') e
                 where e ->> 'kind' = 'assigned' and e ->> 'actor' = 'owner');
end $$;
reset role;

-- the courier: only the own delivery (with what delivering needs), the steps and the payment rules
set role anon;
do $$
declare
  v_key text := (select v from t75 where k = 'key');
  v_o1 uuid := (select v::uuid from t75 where k = 'order1');
  v_o2 uuid := (select v::uuid from t75 where k = 'order2');
  v_pay uuid := gen_random_uuid();
  vj jsonb;
begin
  vj := public.food_courier_call(v_key, 'deliveries', '{}');
  assert jsonb_array_length(vj -> 'open') = 1 and vj -> 'open' -> 0 ->> 'id' = v_o1::text
     and vj -> 'open' -> 0 ->> 'address' = 'Hlavná 8, Michalovce' and vj -> 'open' -> 0 ->> 'phone' like '+421%'
     and not (vj -> 'open' -> 0) ? 'contact_id' and not (vj -> 'open' -> 0) ? 'iban', vj::text;
  begin perform public.food_courier_call(v_key, 'delivery', jsonb_build_object('order_id', v_o2)); raise exception 'someone else''s order';
  exception when no_data_found then null; end;
  vj := public.food_courier_call(v_key, 'delivery', jsonb_build_object('order_id', v_o1));
  assert vj ->> 'vs' is not null and not vj ? 'events' and not vj ? 'conversation_id', vj::text;
  vj := public.food_courier_call(v_key, 'step', jsonb_build_object('order_id', v_o1, 'step_id', gen_random_uuid(), 'to', 'on_the_way'));
  assert vj ->> 'status' = 'on_the_way', vj::text;
  begin perform public.food_courier_call(v_key, 'step', jsonb_build_object('order_id', v_o1, 'step_id', gen_random_uuid(), 'to', 'delivered'));
    raise exception 'delivered before paid';
  exception when raise_exception then assert sqlerrm = 'not_paid'; end;
  begin perform public.food_courier_call(v_key, 'step', jsonb_build_object('order_id', v_o1, 'step_id', gen_random_uuid(), 'pay_method', 'card'));
    raise exception 'a card without the shop''s yes';
  exception when invalid_parameter_value then assert sqlerrm = 'pay_method'; end;
  begin perform public.food_courier_call(v_key, 'step', jsonb_build_object('order_id', v_o1, 'step_id', gen_random_uuid(), 'to', 'cancelled'));
    raise exception 'a courier cancelled';
  exception when raise_exception then assert sqlerrm = 'step'; end;
  vj := public.food_courier_call(v_key, 'problem', jsonb_build_object('order_id', v_o1, 'step_id', gen_random_uuid(), 'reason', 'Nikto neotvára'));
  assert vj ->> 'problem' = 'Nikto neotvára', vj::text;
  begin perform public.food_courier_call(v_key, 'step', jsonb_build_object('order_id', v_o1, 'step_id', v_pay, 'pay_method', 'cash',
                                                                            'cash_given_cents', 100, 'to', 'delivered'));
    raise exception 'less cash than the total';
  exception when invalid_parameter_value then assert sqlerrm = 'cash'; end;
  vj := public.food_courier_call(v_key, 'step', jsonb_build_object('order_id', v_o1, 'step_id', v_pay, 'pay_method', 'cash',
                                                                    'cash_given_cents', 2000, 'to', 'delivered'));
  assert vj ->> 'status' = 'delivered' and (vj ->> 'paid')::boolean and (vj ->> 'change_cents')::int = 2000 - (vj ->> 'total_cents')::int, vj::text;
  insert into t75 values ('total1', vj ->> 'total_cents');
  -- the same step again (a weak signal) changes nothing
  vj := public.food_courier_call(v_key, 'step', jsonb_build_object('order_id', v_o1, 'step_id', v_pay, 'pay_method', 'cash',
                                                                    'cash_given_cents', 2000, 'to', 'delivered'));
  assert vj ->> 'status' = 'delivered';
  vj := public.food_courier_call(v_key, 'whoami', '{}');
  assert (vj ->> 'cash_cents')::int = (select v::int from t75 where k = 'total1') and (vj ->> 'delivered_today')::int = 1, vj::text;
end $$;
reset role;
do $$
declare
  v_o1 uuid := (select v::uuid from t75 where k = 'order1');
begin
  assert (select count(*) from public.food_order_events where order_id = v_o1 and kind = 'paid' and actor = 'courier') = 1;
  assert (select paid_by_courier from public.food_orders where id = v_o1) = (select v::uuid from t75 where k = 'michal');
  assert (select stock_taken_at is not null from public.food_orders where id = v_o1)
       = (public.stock_source_of((select id from public.shops where slug = 'potraviny-centrum')) = 'sklad'), 'Doručené took the stock (once)';
  assert public.food_order_json(v_o1) ->> 'problem' is null, 'a later status step closes the problem';
end $$;

-- the owner settles the cash; auto-assignment gives a new delivery to the signed-in courier
set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000a';
do $$
declare
  v_a uuid := (select id from public.shops where slug = 'potraviny-centrum');
begin
  assert public.owner_food_courier_settle(v_a, (select v::uuid from t75 where k = 'michal')) = (select v::int from t75 where k = 'total1');
  assert (public.owner_food_couriers(v_a) -> 'couriers' -> 0 ->> 'cash_cents')::int = 0;
  perform public.owner_food_save_settings(v_a, '{"assign_mode": "auto"}');
end $$;
reset role;
set role service_role;
do $$
declare
  v_conv uuid := (select v::uuid from t75 where k = 'conv');
  v_token text := (select v from t75 where k = 'token');
  v_code jsonb;
  vj jsonb;
begin
  v_code := public.sms_code_start('potraviny-centrum', 'order', '0907 111 279', 'Tomáš B.', repeat('4', 32), v_conv, v_token);
  vj := public.food_order_create((v_code ->> 'id')::uuid, v_code ->> 'code', gen_random_uuid(),
          jsonb_build_array(jsonb_build_object('item_id', (select v from t75 where k = 'pizza'), 'qty', 2)),
          'delivery', 'cash', 'Okružná 14, Michalovce', null, null, null, v_conv, v_token, 'sk');
  insert into t75 values ('order3', vj -> 'order' ->> 'id');
end $$;
reset role;
do $$
declare
  v_o3 uuid := (select v::uuid from t75 where k = 'order3');
begin
  -- Rasťo never signed in, so Michal gets it (at the order's commit, after its own first event)
  assert (select courier_id from public.food_orders where id = v_o3) = (select v::uuid from t75 where k = 'michal');
  assert (select e.actor from public.food_order_events e where e.order_id = v_o3 and e.kind = 'assigned') = 'system';
  assert (select min(e.id) from public.food_order_events e where e.order_id = v_o3)
       < (select e.id from public.food_order_events e where e.order_id = v_o3 and e.kind = 'assigned');
end $$;

-- switching the courier off signs every phone out at once
set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000a';
do $$
declare
  v_a uuid := (select id from public.shops where slug = 'potraviny-centrum');
  vj jsonb;
begin
  vj := public.owner_food_courier_save(v_a, (select v::uuid from t75 where k = 'michal'), 'Michal', '0915 123 220', false);
  assert (vj ->> 'sessions_ended')::int = 1 and not (vj ->> 'active')::boolean, vj::text;
  begin perform public.owner_food_assign(v_a, (select v::uuid from t75 where k = 'order2'), (select v::uuid from t75 where k = 'michal'), gen_random_uuid());
    raise exception 'assigned to a courier who is off';
  exception when invalid_parameter_value then assert sqlerrm = 'courier'; end;
end $$;
reset role;
set role anon;
do $$
begin
  begin perform public.food_courier_call((select v from t75 where k = 'key'), 'whoami', '{}'); raise exception 'still signed in';
  exception when invalid_authorization_specification then null; end;
end $$;
reset role;

-- tidy up: the test orders, couriers, the subscription and the day's hours as before
set role service_role;
do $$
declare
  v_a uuid := (select id from public.shops where slug = 'potraviny-centrum');
begin
  update public.food_settings set enabled = false, assign_mode = 'manual' where shop_id = v_a;
  delete from public.food_couriers where shop_id = v_a;
  delete from public.shop_special_hours where shop_id = v_a and date = (select v::date from t75 where k = 'day');
  delete from public.subscriptions where shop_id = v_a;
  insert into public.subscriptions
  select * from jsonb_populate_record(null::public.subscriptions, (select v::jsonb from t75 where k = 'sub'))
  where (select v from t75 where k = 'sub') is not null;
  assert public.shop_has_plan(v_a) = (select v::boolean from t75 where k = 'had_plan');
end $$;
reset role;
drop table t75;

\echo '--- update 76: CRM → Správy (recipient search, the log), Opraviť gramatiku (limit per shop, AI spend), the website''s AI pomocník (one door, Potvrdiť only, actor web, one daily limit with Telegram)'
create temporary table t76 (k text primary key, v text);
grant all on t76 to public;

set role service_role;
do $$
declare
  v_a uuid := (select id from public.shops where slug = 'potraviny-centrum');
  v_b uuid := (select id from public.shops where slug = 'drogeria-kostolne');
  v_c uuid;
begin
  insert into t76 values ('had_plan', public.shop_has_plan(v_a)::text),
    ('sub', (select to_jsonb(s) from public.subscriptions s where s.shop_id = v_a)::text),
    ('d', (current_date + 40)::text),
    ('tg', (select to_jsonb(t) from public.telegram_settings t where t.id)::text);
  insert into public.subscriptions (shop_id, status, plan, current_period_end, stripe_subscription_id)
  values (v_a, 'active', 'pro', now() + interval '30 days', 'sub_test_76')
  on conflict (shop_id) do update set status = 'active', current_period_end = now() + interval '30 days',
    stripe_subscription_id = coalesce(public.subscriptions.stripe_subscription_id, 'sub_test_76');
  insert into public.shop_contacts (shop_id, name, phone, email, source)
  values (v_a, 'Ján Novák', '+421905111222', 'jan76@example.invalid', 'owner') returning id into v_c;
  insert into t76 values ('jan', v_c::text);
  insert into public.shop_contacts (shop_id, name, phone, source) values (v_a, 'Eva Malá', '+421905333444', 'owner');
  insert into public.shop_contacts (shop_id, name, source) values (v_b, 'Ján Iný', 'owner');
  -- the log: an owner's SMS and a booking code (never shown) to Ján
  insert into public.shop_outgoing_messages (shop_id, contact_id, channel, recipient, body, status, kind)
  values (v_a, v_c, 'sms', '+421905111222', E'Dobrý deň Ján,\nvaša objednávka je pripravená.', 'test', 'owner'),
         (v_a, v_c, 'sms', '+421905111222', 'Kód ••••••', 'test', 'booking_code');
  update public.owner_ai_settings set grammar_daily_limit = 2 where id;
  update public.telegram_settings set ai_enabled = true, ai_daily_limit = 50 where id;
end $$;
reset role;

-- the recipient bar: partial words, accents ignored, digits of the phone — only the shop's own contacts
set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000a';
do $$
declare
  v_a uuid := (select id from public.shops where slug = 'potraviny-centrum');
  v_b uuid := (select id from public.shops where slug = 'drogeria-kostolne');
  v_n integer;
  vj jsonb;
begin
  assert (select count(*) from public.owner_contact_search(v_a, 'jan nov')) = 1, 'two partial words';
  assert (select name from public.owner_contact_search(v_a, 'novak')) = 'Ján Novák', 'accents ignored';
  assert (select count(*) from public.owner_contact_search(v_a, '0905 111')) = 1, 'the phone''s digits';
  assert not exists (select 1 from public.owner_contact_search(v_a, 'ján') where name = 'Ján Iný'), 'another shop''s contact';
  assert (select count(*) from public.owner_contact_search(v_b, 'ján')) = 0, 'not a member of that shop';
  assert (select count(*) from public.owner_contact_search(v_a, '   ')) = 0, 'nothing typed';
  -- the log: the owner's message, never the codes; filters; another shop's log is empty
  select count(*) into v_n from public.owner_messages_log(v_a, null, null, null, 200) where recipient = '+421905111222';
  assert v_n = 1, 'only the owner''s message, never a code: ' || v_n;
  assert (select first_line from public.owner_messages_log(v_a, null, null, null, 200) where recipient = '+421905111222') = 'Dobrý deň Ján,', 'its first line';
  assert (select contact_name from public.owner_messages_log(v_a, 'sms', 'test', 'novák pripravená')) = 'Ján Novák', 'filters';
  assert not exists (select 1 from public.owner_messages_log(v_a, 'email', null, null, 200) where recipient = '+421905111222'), 'channel filter';
  assert (select count(*) from public.owner_messages_log(v_b)) = 0, 'another shop';
  -- Opraviť gramatiku: 2 a day per shop (the admin's setting), the tokens counted
  assert public.owner_grammar_hit(v_a) = 1;
  assert public.owner_grammar_hit(v_a) = 0;
  begin perform public.owner_grammar_hit(v_a); raise exception 'no grammar limit';
  exception when program_limit_exceeded then if sqlerrm <> 'grammar_limit' then raise; end if; end;
  begin perform public.owner_grammar_hit(v_b); raise exception 'another owner''s shop';
  exception when insufficient_privilege then null; end;
  perform public.owner_ai_spend(v_a, 'grammar', 120, 30);
  begin perform public.owner_ai_spend(v_b, 'grammar', 1, 1); raise exception 'spend on another shop';
  exception when insufficient_privilege then null; end;
  begin perform count(*) from public.owner_ai_usage; raise exception 'owner read the usage table';
  exception when insufficient_privilege then null; end;
  begin perform public.admin_owner_ai(); raise exception 'not the admin';
  exception when insufficient_privilege then null; end;
  -- the AI pomocník: reads through the one door with the owner's own web grant
  assert public.assistant_ai_hit('potraviny-centrum') >= 0;
  vj := public.assistant_web_call('get_shop_details', '{"shop": "potraviny-centrum"}');
  assert vj ->> 'shop' = 'potraviny-centrum', vj::text;
  begin perform public.assistant_web_call('get_shop_details', '{"shop": "drogeria-kostolne"}'); raise exception 'another owner''s shop';
  exception when insufficient_privilege then null; end;
  begin perform public.assistant_ai_hit('drogeria-kostolne'); raise exception 'AI for another owner''s shop';
  exception when insufficient_privilege then null; end;
  begin perform count(*) from public.assistant_pending; raise exception 'owner read the pending table';
  exception when insufficient_privilege then null; end;
end $$;
reset role;

set role service_role;
do $$
begin
  assert (select calls from public.owner_ai_usage u join public.shops s on s.id = u.shop_id
          where s.slug = 'potraviny-centrum' and u.kind = 'grammar' and u.user_id = '00000000-0000-0000-0000-00000000000a'
          order by u.day desc limit 1) = 2, 'two fixes counted';
  assert (select input_tokens + output_tokens from public.owner_ai_usage u join public.shops s on s.id = u.shop_id
          where s.slug = 'potraviny-centrum' and u.kind = 'grammar' order by u.day desc limit 1) = 150, 'the tokens';
  assert exists (select 1 from public.owner_mcp_tokens t join public.assistant_web_links l on l.grant_id = t.id
                 where l.user_id = '00000000-0000-0000-0000-00000000000a' and t.kind = 'web' and t.revoked_at is null
                   and t.scopes = array['shop.read', 'shop.write']), 'a web grant';
end $$;
reset role;
-- (as the database owner: the token only in the Vault)
do $$ begin
  assert exists (select 1 from vault.secrets s join public.assistant_web_links l on l.vault_id = s.id
                 where l.user_id = '00000000-0000-0000-0000-00000000000a' and s.secret ~ '^cwa_[0-9a-f]{64}$'), 'the web token only in the Vault';
end $$;

-- every write waits for Potvrdiť: the same owner, 10 minutes, once; the activity log says web
set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000a';
do $$
declare
  v_a uuid := (select id from public.shops where slug = 'potraviny-centrum');
  v_d date := (select v::date from t76 where k = 'd');
  v_p uuid;
  vj jsonb;
begin
  begin perform public.assistant_web_call('set_opening_hours', jsonb_build_object('shop', 'potraviny-centrum', 'special',
          jsonb_build_array(jsonb_build_object('from', v_d, 'closed', true)))); raise exception 'write without Potvrdiť';
  exception when insufficient_privilege then if sqlerrm <> 'needs_confirmation' then raise; end if; end;
  begin perform public.assistant_pending_new('get_shop_details', '{}', '{}'); raise exception 'pending read tool';
  exception when invalid_parameter_value then if sqlerrm <> 'unknown_tool' then raise; end if; end;
  begin perform public.assistant_pending_new('preview_message', '{}', '{}'); raise exception 'pending message';
  exception when invalid_parameter_value then if sqlerrm <> 'unknown_tool' then raise; end if; end;
  v_p := public.assistant_pending_new('set_opening_hours', jsonb_build_object('shop', 'potraviny-centrum', 'special',
           jsonb_build_array(jsonb_build_object('from', v_d, 'closed', true))), '{"lines": ["closed"]}');
  insert into t76 values ('p', v_p::text);
  assert not exists (select 1 from public.shop_special_hours where shop_id = v_a and date = v_d), 'nothing before Potvrdiť';
end $$;
reset role;
set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000b';
do $$ begin
  begin perform public.assistant_confirm((select v::uuid from t76 where k = 'p')); raise exception 'another owner confirmed';
  exception when no_data_found then null; end;
  assert public.assistant_cancel((select v::uuid from t76 where k = 'p')) is null, 'another owner cancelled';
  begin perform public.assistant_ai_hit('drogeria-kostolne'); raise exception 'AI without the plan';
  exception when raise_exception then if sqlerrm <> 'no_plan' then raise; end if; end;
end $$;
reset role;
set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000a';
do $$
declare
  v_a uuid := (select id from public.shops where slug = 'potraviny-centrum');
  v_d date := (select v::date from t76 where k = 'd');
  v_p uuid := (select v::uuid from t76 where k = 'p');
  vj jsonb;
begin
  vj := public.assistant_confirm(v_p);
  assert vj ->> 'tool' = 'set_opening_hours' and vj -> 'summary' = '{"lines": ["closed"]}'::jsonb, vj::text;
  assert exists (select 1 from public.shop_special_hours where shop_id = v_a and date = v_d and closed), 'closed that day';
  assert exists (select 1 from public.shop_activity where shop_id = v_a and action = 'hours_changed' and details ->> 'source' = 'web'),
    'the activity log says web';
  begin perform public.assistant_confirm(v_p); raise exception 'confirmed twice';
  exception when invalid_parameter_value then if sqlerrm <> 'used' then raise; end if; end;
  v_p := public.assistant_pending_new('set_opening_hours', '{"shop": "potraviny-centrum", "special": []}', '{}');
  insert into t76 values ('p2', v_p::text);
  assert public.assistant_cancel(v_p);
  begin perform public.assistant_confirm(v_p); raise exception 'confirmed after Zrušiť';
  exception when invalid_parameter_value then if sqlerrm <> 'used' then raise; end if; end;
  insert into t76 values ('p3', public.assistant_pending_new('set_opening_hours', '{"shop": "potraviny-centrum", "special": []}', '{}')::text);
end $$;
reset role;
set role service_role;
update public.assistant_pending set expires_at = now() - interval '1 second' where id = (select v::uuid from t76 where k = 'p3');
-- one daily limit for the website and Telegram: the owner's messages today + 1 = the last one
update public.telegram_settings set ai_daily_limit = public.owner_ai_messages_today('00000000-0000-0000-0000-00000000000a') + 1 where id;
reset role;
set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000a';
do $$ begin
  begin perform public.assistant_confirm((select v::uuid from t76 where k = 'p3')); raise exception 'expired confirmation';
  exception when invalid_parameter_value then if sqlerrm <> 'expired' then raise; end if; end;
  assert public.assistant_ai_hit('potraviny-centrum') = 0, 'the last message today';
  begin perform public.assistant_ai_hit('potraviny-centrum'); raise exception 'no AI limit';
  exception when program_limit_exceeded then if sqlerrm <> 'ai_limit' then raise; end if; end;
end $$;
reset role;
set role service_role;
update public.telegram_settings set ai_enabled = false, ai_daily_limit = 50 where id;
update public.owner_ai_settings set grammar_daily_limit = 0 where id;
reset role;
set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000a';
do $$ begin
  begin perform public.assistant_ai_hit('potraviny-centrum'); raise exception 'AI switched off';
  exception when raise_exception then if sqlerrm <> 'ai_off' then raise; end if; end;
  begin perform public.owner_grammar_hit((select id from public.shops where slug = 'potraviny-centrum')); raise exception 'grammar switched off';
  exception when raise_exception then if sqlerrm <> 'grammar_off' then raise; end if; end;
end $$;
reset role;

-- the admin: the grammar limit and the use of the owners' AI tools
set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-0000000000ad';
do $$
declare
  vj jsonb;
begin
  perform public.admin_save_owner_ai(30);
  vj := public.admin_owner_ai();
  assert (vj ->> 'grammar_daily_limit')::int = 30 and (vj -> 'today' -> 'grammar' ->> 'calls')::int >= 2, vj::text;
  begin perform public.admin_save_owner_ai(5000); raise exception 'limit out of range';
  exception when invalid_parameter_value then null; end;
end $$;
reset role;

-- tidy up
set role service_role;
do $$
declare
  v_a uuid := (select id from public.shops where slug = 'potraviny-centrum');
  v_b uuid := (select id from public.shops where slug = 'drogeria-kostolne');
  v_tg jsonb := (select v::jsonb from t76 where k = 'tg');
begin
  delete from public.shop_outgoing_messages where shop_id = v_a and recipient = '+421905111222';
  delete from public.shop_contacts where (shop_id = v_a and name in ('Ján Novák', 'Eva Malá')) or (shop_id = v_b and name = 'Ján Iný');
  delete from public.shop_special_hours where shop_id = v_a and date = (select v::date from t76 where k = 'd');
  delete from public.assistant_pending where user_id = '00000000-0000-0000-0000-00000000000a';
  update public.telegram_settings set ai_enabled = (v_tg ->> 'ai_enabled')::boolean, ai_daily_limit = (v_tg ->> 'ai_daily_limit')::int where id;
  delete from public.subscriptions where shop_id = v_a;
  insert into public.subscriptions
  select * from jsonb_populate_record(null::public.subscriptions, (select v::jsonb from t76 where k = 'sub'))
  where (select v from t76 where k = 'sub') is not null;
  assert public.shop_has_plan(v_a) = (select v::boolean from t76 where k = 'had_plan');
end $$;
reset role;
drop table t76;

\echo '--- update 77: the blog editor''s AI (members with the plan, the daily limit per shop, AI spend), the owner''s own text of a Facebook post (the sync keeps it, deleted still hides), the post page''s formatted flag'
create temporary table t77 (k text primary key, v text);
grant all on t77 to public;

set role service_role;
do $$
declare
  v_a uuid := (select id from public.shops where slug = 'potraviny-centrum');
  v_r jsonb;
  v_id uuid;
begin
  insert into t77 values ('had_plan', public.shop_has_plan(v_a)::text),
    ('sub', (select to_jsonb(s) from public.subscriptions s where s.shop_id = v_a)::text),
    ('limit', (select blog_daily_limit::text from public.owner_ai_settings where id));
  insert into public.subscriptions (shop_id, status, plan, current_period_end, stripe_subscription_id)
  values (v_a, 'active', 'pro', now() + interval '30 days', 'sub_test_77')
  on conflict (shop_id) do update set status = 'active', current_period_end = now() + interval '30 days',
    stripe_subscription_id = coalesce(public.subscriptions.stripe_subscription_id, 'sub_test_77');
  update public.owner_ai_settings set blog_daily_limit = 2 where id;
  assert (select blog_daily_limit from public.owner_ai_settings where id) = 2;
  -- an imported Facebook post (live) and a post written in Cacaduu
  v_r := public.blog_import_post(v_a, '123456789_7701', 'Nový tovar', E'Nový tovar - farby\n- štetce', now() - interval '1 day',
                                 now() - interval '1 day', null, '[]', '[]');
  assert v_r ->> 'result' = 'new', v_r::text;
  insert into t77 values ('fb', v_r ->> 'post_id');
  insert into public.blog_posts (shop_id, slug, title, body, source, status, publish_at)
  values (v_a, 'clanok-77', 'Článok 77', E'## Podnadpis\n- jeden', 'cacaduu', 'published', now() - interval '1 hour')
  returning id into v_id;
  insert into t77 values ('own', v_id::text);
end $$;
reset role;

set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000a';
do $$
declare
  v_a uuid := (select id from public.shops where slug = 'potraviny-centrum');
  v_fb uuid := (select v::uuid from t77 where k = 'fb');
  v_own uuid := (select v::uuid from t77 where k = 'own');
  vj jsonb;
begin
  -- the AI's door: what it may use, then the daily limit per shop
  vj := public.owner_blog_ai_hit(v_fb);
  assert (vj ->> 'left')::int = 1 and vj ->> 'source' = 'facebook' and vj -> 'shop' ->> 'name' is not null
         and jsonb_typeof(vj -> 'photos') = 'array', vj::text;
  assert (public.owner_blog_ai_hit(v_own) ->> 'left')::int = 0;
  begin perform public.owner_blog_ai_hit(v_own); raise exception 'no blog AI limit';
  exception when program_limit_exceeded then assert sqlerrm = 'blog_ai_limit'; end;
  perform public.owner_ai_spend(v_a, 'blog', 1200, 800);
  -- the owner's own text of the imported post (after "Použiť"); a Cacaduu post keeps owner_blog_save
  perform public.owner_blog_own_text(v_fb, 'Nový tovar v obchode', E'## Čo je nové\n- **farby**\n- štetce');
  assert (select body_by_owner and title_by_owner and body = E'## Čo je nové\n- **farby**\n- štetce' from public.blog_posts where id = v_fb);
  begin perform public.owner_blog_own_text(v_own, 'x', 'y'); raise exception 'own text on a Cacaduu post';
  exception when invalid_parameter_value then assert sqlerrm = 'not_imported'; end;
  begin perform public.owner_blog_own_text(v_fb, 'x', '  '); raise exception 'an empty own text';
  exception when invalid_parameter_value then assert sqlerrm = 'body'; end;
end $$;
reset role;

-- another owner: neither the door nor the own text
set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000b';
do $$
begin
  begin perform public.owner_blog_ai_hit((select v::uuid from t77 where k = 'fb')); raise exception 'another owner''s post';
  exception when insufficient_privilege then null; end;
  begin perform public.owner_blog_own_text((select v::uuid from t77 where k = 'fb'), 'x', 'y'); raise exception 'another owner''s post';
  exception when insufficient_privilege then null; end;
end $$;
reset role;

-- the sync keeps the owner's text (Facebook's edits of the text are not taken; the links still follow); deleted on
-- Facebook still hides it; the post page says whether the marks count
set role service_role;
do $$
declare
  v_a uuid := (select id from public.shops where slug = 'potraviny-centrum');
  v_fb uuid := (select v::uuid from t77 where k = 'fb');
  v_slug text := (select slug from public.blog_posts where id = (select v::uuid from t77 where k = 'fb'));
  v_r jsonb;
begin
  assert (select sum(input_tokens) from public.owner_ai_usage where shop_id = v_a and kind = 'blog') >= 1200, 'the AI spend';
  assert (public.shop_blog_post('potraviny-centrum', v_slug) ->> 'formatted')::boolean, 'the owner''s text: marks count';
  assert (public.shop_blog_post('potraviny-centrum', 'clanok-77') ->> 'formatted')::boolean, 'written in Cacaduu';
  v_r := public.blog_import_post(v_a, '123456789_7701', 'Nový tovar', 'Facebook changed the text', now() - interval '1 day',
                                 now(), null, '[]', '[]');
  assert v_r ->> 'result' = 'same', v_r::text;
  v_r := public.blog_import_post(v_a, '123456789_7701', 'Nový tovar', 'Facebook changed the text', now() - interval '1 day',
                                 now(), null, '[{"kind":"link","url":"https://example.com/novinka","title":"Novinka"}]', '[]');
  assert v_r ->> 'result' = 'updated', v_r::text;
  assert (select body = E'## Čo je nové\n- **farby**\n- štetce' and title = 'Nový tovar v obchode' and jsonb_array_length(links) = 1
          from public.blog_posts where id = v_fb), 'the owner''s text and title stay, the links follow Facebook';
  -- an imported post without the owner's text: Facebook's text is shown as written (no marks)
  v_r := public.blog_import_post(v_a, '123456789_7702', 'Iný', E'- nie zoznam', now() - interval '1 day', now(), null, '[]', '[]');
  assert not (public.shop_blog_post('potraviny-centrum', (select slug from public.blog_posts where id = (v_r ->> 'post_id')::uuid))
              ->> 'formatted')::boolean;
  insert into t77 values ('fb2', v_r ->> 'post_id');
  assert public.blog_posts_deleted_on_facebook(v_a, array['123456789_7701']) = 1;
  assert (select status from public.blog_posts where id = v_fb) = 'hidden', 'deleted on Facebook still hides it';
  -- no plan: the editor's AI is refused
  delete from public.subscriptions where shop_id = v_a;
end $$;
reset role;

set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000a';
do $$
begin
  if not public.shop_has_plan((select id from public.shops where slug = 'potraviny-centrum')) then
    begin perform public.owner_blog_ai_hit((select v::uuid from t77 where k = 'own')); raise exception 'AI without the plan';
    exception when raise_exception then assert sqlerrm = 'no_plan'; end;
  end if;
end $$;
reset role;

-- the admin: the blog limit next to the grammar limit
set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-0000000000ad';
do $$
declare
  vj jsonb;
begin
  perform public.admin_save_blog_ai(20);
  vj := public.admin_owner_ai();
  assert (vj ->> 'blog_daily_limit')::int = 20 and (vj -> 'today' -> 'blog' ->> 'calls')::int >= 2, vj::text;
  begin perform public.admin_save_blog_ai(-1); raise exception 'limit out of range';
  exception when invalid_parameter_value then null; end;
end $$;
reset role;

set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000a';
do $$
begin
  begin perform public.admin_save_blog_ai(5); raise exception 'an owner set the admin''s limit';
  exception when insufficient_privilege then null; end;
end $$;
reset role;

-- tidy up
set role service_role;
do $$
declare
  v_a uuid := (select id from public.shops where slug = 'potraviny-centrum');
begin
  delete from public.blog_posts where id in (select v::uuid from t77 where k in ('fb', 'fb2', 'own'));
  update public.owner_ai_settings set blog_daily_limit = (select v::int from t77 where k = 'limit') where id;
  delete from public.subscriptions where shop_id = v_a;
  insert into public.subscriptions
  select * from jsonb_populate_record(null::public.subscriptions, (select v::jsonb from t77 where k = 'sub'))
  where (select v from t77 where k = 'sub') is not null;
  assert public.shop_has_plan(v_a) = (select v::boolean from t77 where k = 'had_plan');
end $$;
reset role;
drop table t77;

\echo '--- update 78: product photos — one per product, only the product page reads it (no photo in any list, search, the API''s reads or llms.txt), owners only, a new one replaces the old, bulk rows decided in SQL (empty = nothing, code then EAN, https only), a product made again by code gets its photo back'
create temporary table t78 (k text primary key, v text);
grant all on t78 to public;

set role service_role;
do $$
declare
  v_a uuid := (select id from public.shops where slug = 'potraviny-centrum');
  v_item uuid := (select si.id from public.shop_items si where si.shop_id = v_a and si.source_code = 'P003');
  v_item2 uuid := (select si.id from public.shop_items si where si.shop_id = v_a and si.source_code = 'P001');
  v_r jsonb;
begin
  insert into t78 values ('item', v_item::text), ('item2', v_item2::text), ('shop', v_a::text);
  -- the first photo, then a new one: the old files come back to be deleted
  v_r := public.product_photo_set(v_item, v_a || '/' || v_item || '/zzphoto78a-1600.webp', v_a || '/' || v_item || '/zzphoto78a-800.webp', 1600, 1200, 'owner');
  assert v_r -> 'old' = '[]'::jsonb and v_r ->> 'slug' = 'potraviny-centrum', v_r::text;
  v_r := public.product_photo_set(v_item, v_a || '/' || v_item || '/zzphoto78b-1600.webp', v_a || '/' || v_item || '/zzphoto78b-800.webp', 1200, 900, 'owner');
  assert jsonb_array_length(v_r -> 'old') = 2 and (v_r -> 'old')::text like '%zzphoto78a-1600%', v_r::text;
  assert (select count(*) from public.product_photos where item_id = v_item) = 1, 'one photo per product';
  -- the files must be in the product's own shop folder
  begin
    perform public.product_photo_set(v_item, gen_random_uuid() || '/x/zzphoto78-1600.webp', gen_random_uuid() || '/x/zzphoto78-800.webp', 800, 600, 'owner');
    raise exception 'a photo in another shop''s folder';
  exception when invalid_parameter_value then assert sqlerrm = 'path'; end;
end $$;
reset role;

-- visitors: only the product page's read gives the photo; the table itself is closed
set role anon;
do $$
declare
  v_item uuid := (select v::uuid from t78 where k = 'item');
  vj jsonb := public.item_photo('potraviny-centrum', (select v::uuid from t78 where k = 'item'));
  v_text text;
begin
  assert vj ->> 'large' like '%zzphoto78b-1600.webp' and (vj ->> 'width')::int = 1200 and (vj ->> 'v') is not null, coalesce(vj::text, 'null');
  assert public.item_photo('drogeria-kostolne', v_item) is null, 'another shop''s address';
  assert public.item_photo('potraviny-centrum', (select v::uuid from t78 where k = 'item2')) is null, 'a product without a photo';
  begin perform 1 from public.product_photos; raise exception 'visitors read product_photos';
  exception when insufficient_privilege then null; end;
  -- every public list, search and the API's reads stay without a photo (the photo's file name is nowhere)
  v_text := concat_ws(' ',
    (select jsonb_agg(to_jsonb(p))::text from public.public_stock p where p.shop_slug = 'potraviny-centrum'),
    (select jsonb_agg(to_jsonb(r))::text from public.shop_stock('potraviny-centrum', null, 50, 0) r),
    (select jsonb_agg(to_jsonb(r))::text from public.shop_item_search('potraviny-centrum', 'mlieko', 20, 0) r),
    (select jsonb_agg(to_jsonb(r))::text from public.item_search('mlieko', null, null, 500, false, 50) r),
    (select jsonb_agg(to_jsonb(r))::text from public.search_stock('mlieko', null, null, 500, false) r),
    (select jsonb_agg(to_jsonb(r))::text from public.search_stock(null, 48.75, 21.92, 500, false) r),
    (select jsonb_agg(to_jsonb(s))::text from public.public_shops s),
    public.shop_llms_facts('potraviny-centrum')::text);
  assert v_text like '%Mlieko%', 'the reads above found the product';
  assert v_text not like '%zzphoto78%' and v_text not like '%product-photos%' and v_text not like '%photo%', 'a photo in a public read';
end $$;
reset role;

-- owners: the function's check, their own rows; another owner sees nothing
set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000a';
do $$
declare
  v_item uuid := (select v::uuid from t78 where k = 'item');
  v_a uuid := (select v::uuid from t78 where k = 'shop');
  vj jsonb := public.owner_product_photo_item((select v::uuid from t78 where k = 'item'));
  v_job uuid;
begin
  assert (vj ->> 'shop_id')::uuid = v_a and vj ->> 'slug' = 'potraviny-centrum' and vj ->> 'source_code' = 'P003', vj::text;
  assert (select count(*) from public.product_photos where item_id = v_item) = 1, 'the owner reads the photo';
  -- a bulk file: code, then EAN; empty = nothing; http = refused; unknown = not found
  v_job := public.owner_product_photo_job(v_a, 'fotky.csv', 'csv', jsonb_build_array(
    jsonb_build_object('code', 'P003', 'url', 'https://example.com/foto/mlieko.jpg'),
    jsonb_build_object('code', 'ZZ-NONE', 'url', 'https://example.com/foto/nic.jpg'),
    jsonb_build_object('code', 'P003', 'url', ''),
    jsonb_build_object('code', 'P003', 'url', 'http://example.com/foto/mlieko.jpg'),
    jsonb_build_object('ean', '8000070012345', 'url', 'https://example.com/foto/kava.jpg'),
    jsonb_build_object('code', '', 'ean', '', 'url', 'https://example.com/foto/x.jpg')));
  insert into t78 values ('job', v_job::text);
  assert (select string_agg(status, ',' order by n) from public.product_photo_job_rows where job_id = v_job)
         = 'pending,not_found,empty,bad_url,pending,not_found',
         (select string_agg(status, ',' order by n) from public.product_photo_job_rows where job_id = v_job);
  assert (select item_id from public.product_photo_job_rows where job_id = v_job and n = 5) = (select v::uuid from t78 where k = 'item2'), 'EAN';
  begin perform public.owner_product_photo_job(v_a, 'b.csv', 'csv', '[{"code":"P003","url":"https://example.com/b.jpg"}]'); raise exception 'two files at once';
  exception when lock_not_available then assert sqlerrm = 'job_running'; end;
  begin perform public.owner_product_photo_job(v_a, 'b.csv', 'csv', '[]'); raise exception 'an empty file';
  exception when invalid_parameter_value then assert sqlerrm = 'rows'; end;
end $$;
reset role;

set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000b';
do $$
begin
  begin perform public.owner_product_photo_item((select v::uuid from t78 where k = 'item')); raise exception 'another owner''s product';
  exception when insufficient_privilege then null; end;
  begin perform public.owner_product_photo_job((select v::uuid from t78 where k = 'shop'), 'x.csv', 'csv', '[{"code":"P003","url":"https://example.com/x.jpg"}]');
    raise exception 'another owner''s shop';
  exception when insufficient_privilege then null; end;
  assert (select count(*) from public.product_photos where item_id = (select v::uuid from t78 where k = 'item')) = 0, 'another owner reads the photo';
  assert (select count(*) from public.product_photo_jobs where id = (select v::uuid from t78 where k = 'job')) = 0, 'another owner reads the report';
end $$;
reset role;

-- the function's steps: claim → 1600 px part → claim again → done (replaces, old files back) → the next row fails → done
set role service_role;
do $$
declare
  v_job uuid := (select v::uuid from t78 where k = 'job');
  v_a uuid := (select v::uuid from t78 where k = 'shop');
  v_item uuid := (select v::uuid from t78 where k = 'item');
  v_c jsonb;
  v_r jsonb;
begin
  assert public.product_photo_due();
  -- the 5-minute job starts a chain only when the file stopped moving (rows just written: not stalled)
  assert not public.product_photo_due('2 minutes'), 'a moving file is not restarted';
  update public.product_photo_job_rows set updated_at = now() - interval '10 minutes' where job_id = v_job;
  assert public.product_photo_due('2 minutes'), 'a stalled file is restarted';
  v_c := public.product_photo_claim();
  assert (v_c ->> 'n')::int = 1 and v_c ->> 'url' = 'https://example.com/foto/mlieko.jpg' and v_c ->> 'part_path' is null, v_c::text;
  perform public.product_photo_part(v_job, 1, v_a || '/' || v_item || '/zzphoto78c-1600.webp', 1600, 1000);
  v_c := public.product_photo_claim();
  assert (v_c ->> 'n')::int = 1 and v_c ->> 'part_path' like '%zzphoto78c-1600.webp', v_c::text;
  v_r := public.product_photo_row_done(v_job, 1, 'done', null, v_a || '/' || v_item || '/zzphoto78c-1600.webp', v_a || '/' || v_item || '/zzphoto78c-800.webp', 1600, 1000);
  assert jsonb_array_length(v_r -> 'old') = 2 and not (v_r ->> 'finished')::boolean, v_r::text;
  assert (select source = 'bulk' and source_url = 'https://example.com/foto/mlieko.jpg' and path_small like '%zzphoto78c-800.webp'
          from public.product_photos where item_id = v_item), 'the bulk photo replaced the owner''s';
  v_c := public.product_photo_claim();
  assert (v_c ->> 'n')::int = 5, v_c::text;
  v_r := public.product_photo_row_done(v_job, 5, 'bad_image', 'not a picture');
  assert (v_r ->> 'finished')::boolean, v_r::text;
  assert public.product_photo_claim() is null and not public.product_photo_due();
  assert (select status = 'done' and finished_at is not null from public.product_photo_jobs where id = v_job);
  assert (select status from public.product_photo_job_rows where job_id = v_job and n = 1) = 'done';
  -- a row whose step never answered goes back (and fails after 3 tries)
  update public.product_photo_jobs set status = 'running', finished_at = null where id = v_job;
  update public.product_photo_job_rows set status = 'working', tries = 3, updated_at = now() - interval '10 minutes' where job_id = v_job and n = 5;
  assert public.product_photo_claim() is null;
  assert (select status = 'failed' and detail = 'timeout' from public.product_photo_job_rows where job_id = v_job and n = 5);
  assert (select status from public.product_photo_jobs where id = v_job) = 'done';
  -- the tidying runs (nothing of the bucket in this database)
  perform public.product_photo_tidy(10);
end $$;
reset role;

-- the same address again = unchanged (not downloaded again)
set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000a';
do $$
declare
  v_job uuid := public.owner_product_photo_job((select v::uuid from t78 where k = 'shop'), 'znova.xml', 'xml',
                  '[{"code":"P003","url":"https://example.com/foto/mlieko.jpg"}]');
begin
  assert (select status from public.product_photo_job_rows where job_id = v_job) = 'unchanged';
  assert (select status from public.product_photo_jobs where id = v_job) = 'done', 'nothing to download: done at once';
end $$;
reset role;

-- a product made again with the same code gets its photo back; "Odstrániť fotku"
set role service_role;
do $$
declare
  v_a uuid := (select v::uuid from t78 where k = 'shop');
  v_old uuid;
  v_new uuid;
  v_r jsonb;
begin
  insert into public.shop_items (shop_id, source_code, name) values (v_a, 'ZZ-78', 'Produkt 78') returning id into v_old;
  perform public.product_photo_set(v_old, v_a || '/' || v_old || '/zzphoto78d-1600.webp', v_a || '/' || v_old || '/zzphoto78d-800.webp', 800, 800, 'owner');
  delete from public.shop_items where id = v_old;
  insert into public.shop_items (shop_id, source_code, name) values (v_a, 'ZZ-78', 'Produkt 78') returning id into v_new;
  assert (select item_id from public.product_photos where path_large like '%zzphoto78d-1600.webp') = v_new, 'the photo came back by code';
  v_r := public.product_photo_remove(v_new);
  assert jsonb_array_length(v_r -> 'old') = 2 and not exists (select 1 from public.product_photos where item_id = v_new), v_r::text;
  assert public.product_photo_remove(v_new) -> 'old' = '[]'::jsonb, 'removing twice';
  delete from public.shop_items where id = v_new;
  -- tidy up
  delete from public.product_photos where shop_id = v_a;
  delete from public.product_photo_jobs where shop_id = v_a;
end $$;
reset role;
drop table t78;

\echo '--- update 79: the kind of shop — goods by default, chosen first for a new shop, changed only by members (logged, nothing deleted), the setup steps per kind (food: menu, orders, couriers optional, launch), only optional steps can be skipped'
create temporary table t79 (k text primary key, v text);
grant all on t79 to public;

-- every shop so far sells goods
do $$
begin
  assert not exists (select 1 from public.shops where kind <> 'goods'), 'an existing shop is not goods';
end $$;
-- a new owner without shops (owner A has the five shops an account may have by now)
insert into auth.users (id, email) values ('00000000-0000-0000-0000-000000000079', 'owner-79@example.invalid');

set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-000000000079';
do $$
declare
  v_new uuid;
  v_r jsonb;
begin
  -- a new shop: the kind chosen first; nothing else than goods / food
  v_new := public.owner_save_shop(jsonb_build_object('name', 'Bistro 79 test', 'city', 'Michalovce', 'country', 'SK',
                                                     'timezone', 'Europe/Bratislava', 'kind', 'food'));
  insert into t79 values ('new', v_new::text);
  assert (select kind from public.shops where id = v_new) = 'food', 'the new shop is food';
  assert (select kind from public.my_shops() where id = v_new) = 'food', 'my_shops returns the kind';
  begin
    perform public.owner_save_shop(jsonb_build_object('name', 'Služby 79', 'kind', 'services'));
    raise exception 'services offered';
  exception when invalid_parameter_value then assert sqlerrm = 'kind'; end;
  -- saving the details never changes the kind (only owner_set_shop_kind does)
  perform public.owner_save_shop(jsonb_build_object('id', v_new, 'name', 'Bistro 79 test', 'city', 'Michalovce', 'country', 'SK', 'kind', 'goods'));
  assert (select kind from public.shops where id = v_new) = 'food', 'owner_save_shop changed the kind';
  -- the food steps decided in SQL: no address, contact or hours yet, then saved
  v_r := public.owner_setup_steps(v_new);
  assert (select e -> 'missing' from jsonb_array_elements(v_r -> 'steps') e where e ->> 'key' = 'details') = '["address", "contact"]'::jsonb, v_r::text;
  assert (select e -> 'missing' from jsonb_array_elements(v_r -> 'steps') e where e ->> 'key' = 'hours') = '["hours"]'::jsonb, v_r::text;
  assert (select e -> 'missing' from jsonb_array_elements(v_r -> 'steps') e where e ->> 'key' = 'menu') = '["menu"]'::jsonb, v_r::text;
  assert (select e -> 'missing' from jsonb_array_elements(v_r -> 'steps') e where e ->> 'key' = 'orders') = '["plan", "iban"]'::jsonb, v_r::text;
  assert (select e -> 'missing' from jsonb_array_elements(v_r -> 'steps') e where e ->> 'key' = 'assistant') = '["plan", "welcome", "menu_pdf"]'::jsonb, v_r::text;
  perform public.owner_save_shop(jsonb_build_object('id', v_new, 'name', 'Bistro 79 test', 'address', 'Hlavná 1', 'city', 'Michalovce',
                                                    'country', 'SK', 'phone', '+421 900 000 079',
                                                    'opening_hours', '{"mon":[["11:00","15:00"]],"tue":[],"wed":[],"thu":[],"fri":[],"sat":[],"sun":[]}'::jsonb));
  v_r := public.owner_setup_steps(v_new);
  assert (select (e ->> 'done')::boolean from jsonb_array_elements(v_r -> 'steps') e where e ->> 'key' = 'details'), v_r::text;
  assert (select (e ->> 'done')::boolean from jsonb_array_elements(v_r -> 'steps') e where e ->> 'key' = 'hours'), v_r::text;
  assert (v_r ->> 'done')::int = 2 and (v_r ->> 'total')::int = 7, v_r::text;
  -- without a kind: goods
  v_new := public.owner_save_shop(jsonb_build_object('name', 'Predajňa 79 test'));
  assert (select kind from public.shops where id = v_new) = 'goods', 'a shop without a kind is goods';
end $$;
reset role;

set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000a';
do $$
declare
  v_a uuid := (select id from public.shops where slug = 'potraviny-centrum');
  v_r jsonb;
  v_keys text;
begin
  insert into t79 values ('shop', v_a::text);

  -- goods: the steps of a shop with stock
  v_r := public.owner_setup_steps(v_a);
  select string_agg(e ->> 'key', ',' order by n) into v_keys from jsonb_array_elements(v_r -> 'steps') with ordinality x(e, n);
  assert v_r ->> 'kind' = 'goods' and v_keys = 'details,hours,stock,languages,page,assistant', v_keys;
  assert (select (e ->> 'optional')::boolean from jsonb_array_elements(v_r -> 'steps') e where e ->> 'key' = 'assistant'), 'the goods assistant step is optional';
  assert (v_r ->> 'total')::int = 6, v_r::text;

  -- the change of kind: members, goods / food only, logged once, nothing deleted
  begin
    perform public.owner_set_shop_kind(v_a, 'services');
    raise exception 'services accepted';
  exception when invalid_parameter_value then assert sqlerrm = 'kind'; end;
  insert into t79 values ('items', (select count(*) from public.shop_items where shop_id = v_a)::text);
  assert public.owner_set_shop_kind(v_a, 'food') = 'food';
  assert public.owner_set_shop_kind(v_a, 'food') = 'food';
  assert (select count(*) from public.shop_activity where shop_id = v_a and action = 'shop_kind_changed') = 1, 'logged once';
  assert (select details from public.shop_activity where shop_id = v_a and action = 'shop_kind_changed') = '{"from": "goods", "to": "food"}'::jsonb;
  assert (select count(*) from public.shop_items where shop_id = v_a)::text = (select v from t79 where k = 'items'), 'a product was deleted';

  -- food: the steps of a restaurant; only the couriers can be skipped
  v_r := public.owner_setup_steps(v_a);
  select string_agg(e ->> 'key', ',' order by n) into v_keys from jsonb_array_elements(v_r -> 'steps') with ordinality x(e, n);
  assert v_r ->> 'kind' = 'food' and v_keys = 'details,hours,menu,orders,couriers,assistant,launch', v_keys;
  assert (select e -> 'missing' from jsonb_array_elements(v_r -> 'steps') e where e ->> 'key' = 'launch') = '["enabled"]'::jsonb, v_r::text;
  assert (select e -> 'missing' from jsonb_array_elements(v_r -> 'steps') e where e ->> 'key' = 'couriers') = '["couriers"]'::jsonb, v_r::text;
  assert not (v_r ->> 'finished')::boolean;
  begin
    perform public.owner_skip_setup_step(v_a, 'menu', true);
    raise exception 'a required step skipped';
  exception when invalid_parameter_value then assert sqlerrm = 'not_optional'; end;
  assert public.owner_skip_setup_step(v_a, 'couriers', true) = array['couriers'];
  assert public.owner_skip_setup_step(v_a, 'couriers', true) = array['couriers'], 'skipped once';
  v_r := public.owner_setup_steps(v_a);
  assert (select (e ->> 'skipped')::boolean from jsonb_array_elements(v_r -> 'steps') e where e ->> 'key' = 'couriers'), v_r::text;
  assert public.owner_skip_setup_step(v_a, 'couriers', false) = '{}'::text[], 'shown again';
  -- back to goods (the change is logged again)
  assert public.owner_set_shop_kind(v_a, 'goods') = 'goods';
  assert (select count(*) from public.shop_activity where shop_id = v_a and action = 'shop_kind_changed') = 2;
end $$;
reset role;

-- another owner: no change, no steps
set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000b';
do $$
declare
  v_a uuid := (select v::uuid from t79 where k = 'shop');
begin
  begin perform public.owner_set_shop_kind(v_a, 'food'); raise exception 'another owner changed the kind';
  exception when insufficient_privilege then null; end;
  begin perform public.owner_setup_steps(v_a); raise exception 'another owner read the steps';
  exception when insufficient_privilege then null; end;
  begin perform public.owner_skip_setup_step(v_a, 'assistant', true); raise exception 'another owner skipped a step';
  exception when insufficient_privilege then null; end;
  begin perform 1 from public.shop_setup; raise exception 'owners read shop_setup';
  exception when insufficient_privilege then null; end;
end $$;
reset role;

-- visitors: no change of kind
set role anon;
do $$
begin
  begin perform public.owner_set_shop_kind((select v::uuid from t79 where k = 'shop'), 'food'); raise exception 'anon changed the kind';
  exception when insufficient_privilege then null; end;
end $$;
reset role;

-- tidy: the test shops and their owner
delete from public.shops where id in (select shop_id from public.shop_members where user_id = '00000000-0000-0000-0000-000000000079');
delete from auth.users where id = '00000000-0000-0000-0000-000000000079';
drop table t79;

\echo '--- update 80: a restaurant''s menu — dishes with sizes, untracked = available until "Vypredané dnes" (ends at the shop''s midnight), not stock, food_quote with sizes and extras, hidden, categories, the import all or nothing, 10 imports a day, the public Menu only for restaurants, search, the owner MCP tools, owners only'
create temporary table t80 (k text primary key, v text);
grant all on t80 to public;

set role service_role;
do $$
declare
  v_a uuid := (select id from public.shops where slug = 'potraviny-centrum');
  v_tz text := (select coalesce(timezone, 'UTC') from public.shops where id = v_a);
begin
  insert into t80 values ('had_plan', public.shop_has_plan(v_a)::text),
    ('sub', (select to_jsonb(s) from public.subscriptions s where s.shop_id = v_a)::text),
    ('day', ((now() at time zone v_tz)::date)::text);
  insert into public.subscriptions (shop_id, status, plan, current_period_end, stripe_subscription_id)
  values (v_a, 'active', 'pro', now() + interval '30 days', 'sub_test_80')
  on conflict (shop_id) do update set status = 'active', current_period_end = now() + interval '30 days';
  insert into public.shop_special_hours (shop_id, date, closed, ranges)
  values (v_a, (now() at time zone v_tz)::date, false, '[["00:00","23:59"]]')
  on conflict (shop_id, date) do update set closed = false, ranges = excluded.ranges;
end $$;
reset role;

-- the owner: a restaurant with categories, a dish with two sizes, an untracked soup, a tracked drink, an extra
set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000a';
do $$
declare
  v_a uuid := (select id from public.shops where slug = 'potraviny-centrum');
  v_pizza_cat uuid; v_soup_cat uuid; v_drink_cat uuid;
  v_pizza uuid; v_soup uuid; v_drink uuid; v_cheese uuid;
  vj jsonb;
begin
  perform public.owner_set_shop_kind(v_a, 'food');
  perform public.owner_food_save_settings(v_a, '{"enabled": true, "pickup_on": true}');
  v_pizza_cat := public.owner_menu_save_category(v_a, null, 'Pizza 80');
  v_soup_cat := public.owner_menu_save_category(v_a, null, 'Polievky 80');
  v_drink_cat := public.owner_menu_save_category(v_a, null, 'Nápoje 80');
  begin perform public.owner_menu_save_category(v_a, null, ' pizza 80 '); raise exception 'the same name twice';
  exception when unique_violation then if sqlerrm <> 'name_taken' then raise; end if; end;
  begin perform public.owner_menu_save_category(v_a, null, ''); raise exception 'an empty name';
  exception when invalid_parameter_value then if sqlerrm <> 'name' then raise; end if; end;

  -- a dish with sizes: each size its own Sklad product with its own price; the dish itself has no price
  v_pizza := public.owner_menu_save_item(v_a, null, jsonb_build_object(
    'name', 'Pizza Diavola 80', 'description', 'Paradajkový základ, saláma, feferóny', 'category_id', v_pizza_cat,
    'price', '9,99', 'allergens', '[1, 7, "1"]'::jsonb, 'tags', '["spicy"]'::jsonb,
    'variants', '[{"label": "32 cm", "price": "7,50"}, {"label": "45 cm", "price": "11.90"}]'::jsonb));
  set local role service_role;
  assert (select sale_price from public.sklad_items where shop_item_id = v_pizza) is null, 'a dish with sizes has a price';
  assert (select array_agg(si.name || '=' || i.sale_price order by i.menu_position)
          from public.sklad_items i join public.shop_items si on si.id = i.shop_item_id where i.menu_parent = v_pizza)
         = array['Pizza Diavola 80 32 cm=7.50', 'Pizza Diavola 80 45 cm=11.90'], 'the sizes';
  assert (select allergens = '{1,7}' and menu_tags = '{spicy}' and not track_stock from public.sklad_items where shop_item_id = v_pizza);
  assert (select category from public.shop_items where id = v_pizza) = 'Pizza 80', 'the category name on the product';
  set local role authenticated;
  begin perform public.owner_menu_save_item(v_a, null, '{"name": "Zlé", "allergens": [15]}'); raise exception 'allergen 15';
  exception when invalid_parameter_value then if sqlerrm <> 'allergens' then raise; end if; end;
  begin perform public.owner_menu_save_item(v_a, null, '{"name": "Zlé", "tags": ["vegan"]}'); raise exception 'an unknown tag';
  exception when invalid_parameter_value then if sqlerrm <> 'tags' then raise; end if; end;
  begin perform public.owner_menu_save_item(v_a, null, '{"name": "Zlé", "price": "osem"}'); raise exception 'a bad price';
  exception when invalid_parameter_value then if sqlerrm <> 'price' then raise; end if; end;
  begin perform public.owner_menu_save_item(v_a, null, jsonb_build_object('name', 'Zlé', 'category_id', gen_random_uuid())); raise exception 'another category';
  exception when invalid_parameter_value then if sqlerrm <> 'category' then raise; end if; end;

  v_soup := public.owner_menu_save_item(v_a, null, jsonb_build_object('name', 'Kapustnica 80', 'category_id', v_soup_cat,
                                                                       'price', '3.20', 'allergens', '[9]'::jsonb, 'tags', '[]'::jsonb));
  v_drink := public.owner_menu_save_item(v_a, null, jsonb_build_object('name', 'Kofola 80 0,33 l', 'category_id', v_drink_cat,
                                                                        'price', '1.50', 'track_stock', true));
  v_cheese := public.owner_sklad_save_product(v_a, null, '{"name": "Syr navyše 80", "sale_price": "0.90"}');
  perform public.owner_sklad_move(v_a, gen_random_uuid(), v_cheese, 'receipt', 5);
  set local role service_role;
  insert into t80 values ('pizza', v_pizza::text), ('soup', v_soup::text), ('drink', v_drink::text), ('cheese', v_cheese::text),
    ('pizza_cat', v_pizza_cat::text), ('soup_cat', v_soup_cat::text), ('drink_cat', v_drink_cat::text),
    ('p32', (select shop_item_id::text from public.sklad_items where menu_parent = v_pizza and variant_label = '32 cm')),
    ('p45', (select shop_item_id::text from public.sklad_items where menu_parent = v_pizza and variant_label = '45 cm'));
  set local role authenticated;

  -- the editor's read: the categories in order, the dish with its sizes, no stock needed
  vj := public.owner_menu(v_a);
  assert vj ->> 'kind' = 'food' and vj ->> 'today' = (select v from t80 where k = 'day'), vj::text;
  assert (select string_agg(c ->> 'name', ',' order by n) from jsonb_array_elements(vj -> 'categories') with ordinality x(c, n))
         like 'Pizza 80,Polievky 80,Nápoje 80%', vj::text;
  assert (select jsonb_array_length(i -> 'variants') from jsonb_array_elements(vj -> 'items') i where (i ->> 'id')::uuid = v_pizza) = 2;
  -- the order of the categories (drag / arrows)
  perform public.owner_menu_order_categories(v_a, array[v_drink_cat, v_pizza_cat, v_soup_cat]);
  set local role service_role;
  assert (select position from public.menu_categories where id = v_drink_cat) = 0
     and (select position from public.menu_categories where id = v_soup_cat) = 2;
  set local role authenticated;
  -- a renamed category: its dishes (and their sizes) follow
  perform public.owner_menu_save_category(v_a, v_pizza_cat, 'Pizze 80');
  set local role service_role;
  assert (select category from public.shop_items where id = v_pizza) = 'Pizze 80'
     and (select category from public.shop_items where id = (select v::uuid from t80 where k = 'p32')) = 'Pizze 80';
  set local role authenticated;
  begin perform public.owner_menu_delete_category(v_a, v_soup_cat); raise exception 'a category with dishes deleted';
  exception when raise_exception then if sqlerrm <> 'not_empty' then raise; end if; end;
  -- the setup step: the restaurant has a menu now
  assert (select (e ->> 'done')::boolean from jsonb_array_elements(public.owner_setup_steps(v_a) -> 'steps') e where e ->> 'key' = 'menu');
  set local role service_role;
  assert (select count(*) from public.shop_activity where shop_id = v_a and action = 'menu_item_saved') >= 3
     and (select count(*) from public.shop_activity where shop_id = v_a and action = 'menu_category_saved') >= 4;
end $$;
reset role;

-- not stock: an untracked dish is never in the shop's inventory (no freshness, no "Vypredané"); a tracked drink is
do $$
begin
  assert not exists (select 1 from public.inventory where shop_item_id = (select v::uuid from t80 where k = 'soup')), 'the soup is stock';
  assert not exists (select 1 from public.inventory where shop_item_id = (select v::uuid from t80 where k = 'p32')), 'a size is stock';
  assert exists (select 1 from public.inventory where shop_item_id = (select v::uuid from t80 where k = 'drink') and quantity = 0),
         'the tracked drink is not stock';
end $$;

-- the price rule (anon, as the assistant): sizes and extras from Sklad; untracked = available without stock
set role anon;
do $$
declare
  v_p32 text := (select v from t80 where k = 'p32');
  v_p45 text := (select v from t80 where k = 'p45');
  v_pizza text := (select v from t80 where k = 'pizza');
  v_soup text := (select v from t80 where k = 'soup');
  v_drink text := (select v from t80 where k = 'drink');
  v_cheese text := (select v from t80 where k = 'cheese');
  vj jsonb;
begin
  vj := public.food_quote('potraviny-centrum', jsonb_build_array(
          jsonb_build_object('item_id', v_p32, 'qty', 1, 'extras', jsonb_build_array(v_cheese), 'price', 0.01),
          jsonb_build_object('item_id', v_p45, 'qty', 2),
          jsonb_build_object('item_id', v_soup, 'qty', 1)), 'pickup');
  assert (vj ->> 'orderable')::boolean and (vj ->> 'subtotal_cents')::int = 750 + 90 + 2 * 1190 + 320, vj::text;
  assert vj -> 'lines' -> 0 ->> 'name' = 'Pizza Diavola 80 32 cm' and (vj -> 'lines' -> 0 ->> 'unit_cents')::int = 840, vj::text;
  -- the dish itself has no price (its sizes are ordered); the tracked drink has no stock
  vj := public.food_quote('potraviny-centrum', jsonb_build_array(jsonb_build_object('item_id', v_pizza, 'qty', 1)), 'pickup');
  assert vj -> 'refused' -> 0 ->> 'reason' = 'not_found', vj::text;
  vj := public.food_quote('potraviny-centrum', jsonb_build_array(jsonb_build_object('item_id', v_drink, 'qty', 1)), 'pickup');
  assert vj -> 'refused' -> 0 ->> 'reason' = 'sold_out', vj::text;
  -- the assistant's menu: sizes named "<dish> <size>", in the owner's category order (drinks first now)
  vj := public.food_menu('potraviny-centrum', 'diavola');
  assert (select array_agg(i ->> 'name' order by n) from jsonb_array_elements(vj -> 'items') with ordinality x(i, n))
         = array['Pizza Diavola 80 32 cm', 'Pizza Diavola 80 45 cm'], vj::text;
  assert (select (i -> 'allergens') = '[1, 7]'::jsonb from jsonb_array_elements(vj -> 'items') i limit 1), vj::text;

  -- the public Menu: the categories with dishes, sizes and prices, allergens, tags; untracked without a stock state
  vj := public.shop_menu('potraviny-centrum');
  assert (select string_agg(c ->> 'name', ',' order by n) from jsonb_array_elements(vj -> 'categories') with ordinality x(c, n))
         = 'Nápoje 80,Pizze 80,Polievky 80', vj::text;
  assert (select (i ->> 'price_cents') is null and (i -> 'variants' -> 1 ->> 'price_cents')::int = 1190
                 and i -> 'variants' -> 0 ->> 'label' = '32 cm' and i -> 'tags' = '["spicy"]'::jsonb
                 and not (i ->> 'sold_out')::boolean and not (i ->> 'tracked')::boolean
          from jsonb_array_elements(vj -> 'items') i where i ->> 'id' = v_pizza), vj::text;
  assert (select (i ->> 'price_cents')::int = 150 and (i ->> 'tracked')::boolean and (i ->> 'sold_out')::boolean
          from jsonb_array_elements(vj -> 'items') i where i ->> 'id' = v_drink), vj::text;
  assert not exists (select 1 from jsonb_array_elements(vj -> 'items') i where i ->> 'id' = v_cheese), 'a Sklad product that is not on the menu';
  -- only a restaurant has a Menu
  assert public.shop_menu('drogeria-kostolne') is null, 'a shop with goods has a menu';
  -- the forgiving search: a typo finds the dish (a size counts for its dish), words of the category too
  assert (select item_id::text from public.shop_menu_search('potraviny-centrum', 'diavla') limit 1) = v_pizza, 'typo';
  assert (select item_id::text from public.shop_menu_search('potraviny-centrum', 'kapustnica') limit 1) = v_soup;
  assert not exists (select 1 from public.shop_menu_search('drogeria-kostolne', 'diavola'));
  -- visitors never write
  begin perform public.owner_menu_set_sold_out((select id from public.shops where slug = 'potraviny-centrum'), v_soup::uuid, true);
    raise exception 'anon set sold out';
  exception when insufficient_privilege then null; end;
  begin perform public.owner_menu((select id from public.shops where slug = 'potraviny-centrum')); raise exception 'anon read the editor';
  exception when insufficient_privilege then null; end;
  begin perform 1 from public.menu_categories; raise exception 'anon read menu_categories';
  exception when insufficient_privilege then null; end;
end $$;
reset role;

-- "Vypredané dnes": one tap, the dish and all its sizes (or one size), until the shop's midnight
set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000a';
do $$
declare
  v_a uuid := (select id from public.shops where slug = 'potraviny-centrum');
  v_pizza uuid := (select v::uuid from t80 where k = 'pizza');
  v_soup uuid := (select v::uuid from t80 where k = 'soup');
  v_p32 uuid := (select v::uuid from t80 where k = 'p32');
  v_p45 uuid := (select v::uuid from t80 where k = 'p45');
  vj jsonb;
begin
  vj := public.owner_menu_set_sold_out(v_a, v_soup, true);
  assert (vj ->> 'sold_out_today')::boolean and vj ->> 'name' = 'Kapustnica 80', vj::text;
  set local role service_role;
  assert (select sold_out_on from public.sklad_items where shop_item_id = v_soup) = (select v::date from t80 where k = 'day');
  set local role authenticated;
  vj := public.food_quote('potraviny-centrum', jsonb_build_array(jsonb_build_object('item_id', v_soup, 'qty', 1)), 'pickup');
  assert vj -> 'refused' -> 0 ->> 'reason' = 'sold_out', vj::text;
  -- the whole dish: both sizes
  perform public.owner_menu_set_sold_out(v_a, v_pizza, true);
  vj := public.food_quote('potraviny-centrum', jsonb_build_array(jsonb_build_object('item_id', v_p45, 'qty', 1)), 'pickup');
  assert vj -> 'refused' -> 0 ->> 'reason' = 'sold_out', vj::text;
  assert (select (i ->> 'sold_out')::boolean from jsonb_array_elements(public.shop_menu('potraviny-centrum') -> 'items') i
          where (i ->> 'id')::uuid = v_pizza);
  perform public.owner_menu_set_sold_out(v_a, v_pizza, false);
  -- one size only: the dish stays (one size is left)
  perform public.owner_menu_set_sold_out(v_a, v_p32, true);
  vj := public.food_quote('potraviny-centrum', jsonb_build_array(jsonb_build_object('item_id', v_p45, 'qty', 1)), 'pickup');
  assert (vj ->> 'orderable')::boolean, vj::text;
  assert (select not (i ->> 'sold_out')::boolean and (i -> 'variants' -> 0 ->> 'sold_out')::boolean
          from jsonb_array_elements(public.shop_menu('potraviny-centrum') -> 'items') i where (i ->> 'id')::uuid = v_pizza);
  perform public.owner_menu_set_sold_out(v_a, v_p32, false);
  set local role service_role;
  assert (select count(*) from public.shop_activity where shop_id = v_a and action = 'menu_sold_out') = 5;
end $$;
reset role;

-- the shop's midnight: yesterday's "Vypredané dnes" no longer counts (nothing has to reset it)
set role service_role;
do $$
declare
  v_a uuid := (select id from public.shops where slug = 'potraviny-centrum');
  v_soup uuid := (select v::uuid from t80 where k = 'soup');
  vj jsonb;
begin
  update public.sklad_items set sold_out_on = (select v::date from t80 where k = 'day') - 1 where shop_item_id = v_soup;
  vj := public.food_quote('potraviny-centrum', jsonb_build_array(jsonb_build_object('item_id', v_soup, 'qty', 1)), 'pickup');
  assert (vj ->> 'orderable')::boolean, vj::text;
  assert (select not (i ->> 'sold_out')::boolean from jsonb_array_elements(public.shop_menu('potraviny-centrum') -> 'items') i
          where (i ->> 'id')::uuid = v_soup);
end $$;
reset role;

-- editing: an inline price, hidden, a size removed (hidden, never deleted), duplicated right after the original
set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000a';
do $$
declare
  v_a uuid := (select id from public.shops where slug = 'potraviny-centrum');
  v_pizza uuid := (select v::uuid from t80 where k = 'pizza');
  v_soup uuid := (select v::uuid from t80 where k = 'soup');
  v_p32 uuid := (select v::uuid from t80 where k = 'p32');
  v_p45 uuid := (select v::uuid from t80 where k = 'p45');
  v_copy uuid;
  vj jsonb;
begin
  -- only the given fields change
  perform public.owner_menu_save_item(v_a, v_soup, '{"price": "3,50"}');
  set local role service_role;
  assert (select sale_price = 3.50 and allergens = '{9}' from public.sklad_items where shop_item_id = v_soup);
  assert (select category = 'Polievky 80' from public.shop_items where id = v_soup);
  set local role authenticated;
  -- hidden: not on the Menu and not orderable; shown again
  perform public.owner_menu_save_item(v_a, v_soup, '{"hidden": true}');
  assert not exists (select 1 from jsonb_array_elements(public.shop_menu('potraviny-centrum') -> 'items') i where (i ->> 'id')::uuid = v_soup);
  vj := public.food_quote('potraviny-centrum', jsonb_build_array(jsonb_build_object('item_id', v_soup, 'qty', 1)), 'pickup');
  assert vj -> 'refused' -> 0 ->> 'reason' = 'not_found', vj::text;
  perform public.owner_menu_save_item(v_a, v_soup, '{"hidden": false}');
  -- a renamed dish: its sizes follow; a size left out is hidden (its Sklad product stays)
  perform public.owner_menu_save_item(v_a, v_pizza, jsonb_build_object('name', 'Pizza Diavola 80',
    'variants', jsonb_build_array(jsonb_build_object('id', v_p45, 'label', '45 cm', 'price', '12.40'))));
  set local role service_role;
  assert (select menu_hidden from public.sklad_items where shop_item_id = v_p32) and exists (select 1 from public.shop_items where id = v_p32);
  assert (select sale_price from public.sklad_items where shop_item_id = v_p45) = 12.40;
  set local role authenticated;
  assert (select jsonb_array_length(i -> 'variants') from jsonb_array_elements(public.shop_menu('potraviny-centrum') -> 'items') i
          where (i ->> 'id')::uuid = v_pizza) = 1;
  vj := public.food_quote('potraviny-centrum', jsonb_build_array(jsonb_build_object('item_id', v_p32, 'qty', 1)), 'pickup');
  assert vj -> 'refused' -> 0 ->> 'reason' = 'not_found', 'a hidden size is orderable';
  -- another shop's size is refused
  begin perform public.owner_menu_save_item(v_a, v_soup, jsonb_build_object('variants', jsonb_build_array(
          jsonb_build_object('id', v_p45, 'label', 'x', 'price', '1')))); raise exception 'a size of another dish';
  exception when invalid_parameter_value then if sqlerrm <> 'variants' then raise; end if; end;
  -- duplicated: the same sizes and allergens, right after the original
  v_copy := public.owner_menu_duplicate_item(v_a, v_pizza);
  set local role service_role;
  assert (select name from public.shop_items where id = v_copy) = 'Pizza Diavola 80 (2)';
  assert (select count(*) from public.sklad_items where menu_parent = v_copy and not menu_hidden) = 1;
  assert (select allergens = '{1,7}' and menu_position = (select menu_position + 1 from public.sklad_items where shop_item_id = v_pizza)
          from public.sklad_items where shop_item_id = v_copy);
  set local role authenticated;
  perform public.owner_menu_save_item(v_a, v_copy, '{"hidden": true}');
end $$;
reset role;

-- the import from a PDF or a photo: 10 a day per shop; "Uložiť do menu" all or nothing (nothing stored before it)
set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000a';
do $$
declare
  v_a uuid := (select id from public.shops where slug = 'potraviny-centrum');
  v_items integer;
  v_cats integer;
  vj jsonb;
  n integer;
begin
  for n in 1..10 loop
    assert public.owner_menu_import_hit(v_a) = 10 - n;
  end loop;
  begin perform public.owner_menu_import_hit(v_a); raise exception 'an 11th import';
  exception when program_limit_exceeded then if sqlerrm <> 'import_limit' then raise; end if; end;
  perform public.owner_ai_spend(v_a, 'menu', 1200, 300);
  set local role service_role;
  assert (select input_tokens = 1200 and output_tokens = 300 and calls = 10 from public.owner_ai_usage
          where shop_id = v_a and kind = 'menu' and day = (select v::date from t80 where k = 'day'));

  select count(*) into v_items from public.sklad_items where shop_id = v_a;
  select count(*) into v_cats from public.menu_categories where shop_id = v_a;
  set local role authenticated;
  -- a wrong row (a price that is not a price): nothing of the file is stored
  begin
    perform public.owner_menu_import_save(v_a, '[
      {"category": "Hlavné jedlá 80", "name": "Vyprážaný syr 80", "price": "8.90", "allergens": [1, 3, 7]},
      {"category": "Hlavné jedlá 80", "name": "Rezeň 80", "price": "deväť"}]');
    raise exception 'a bad row saved';
  exception when invalid_parameter_value then if sqlerrm <> 'price' then raise; end if; end;
  set local role service_role;
  assert (select count(*) from public.sklad_items where shop_id = v_a) = v_items, 'a product of a refused import';
  assert (select count(*) from public.menu_categories where shop_id = v_a) = v_cats, 'a category of a refused import';
  set local role authenticated;
  -- the owner's confirmed rows: a category found by its name (any case) or made once; sizes
  vj := public.owner_menu_import_save(v_a, '[
    {"category": "Hlavné jedlá 80", "name": "Vyprážaný syr 80", "description": "s hranolkami", "price": "8.90", "allergens": [1, 3, 7], "tags": ["veg"]},
    {"category": "hlavné jedlá 80", "name": "Rezeň 80", "price": "9.40"},
    {"category": "Polievky 80", "name": "Gulášová 80", "variants": [{"label": "0,33 l", "price": "3.10"}, {"label": "0,5 l", "price": "4.20"}]}]');
  assert (vj ->> 'dishes')::int = 3 and (vj ->> 'categories')::int = 1, vj::text;
  set local role service_role;
  assert (select count(*) from public.menu_categories where shop_id = v_a) = v_cats + 1;
  assert (select i.menu_tags = '{veg}' and i.allergens = '{1,3,7}' and i.sale_price = 8.90 and si.description = 's hranolkami'
          from public.sklad_items i join public.shop_items si on si.id = i.shop_item_id where si.shop_id = v_a and si.name = 'Vyprážaný syr 80');
  assert (select count(*) from public.sklad_items i join public.shop_items si on si.id = i.menu_parent
          where si.name = 'Gulášová 80' and si.shop_id = v_a) = 2;
  assert (select details from public.shop_activity where shop_id = v_a and action = 'menu_imported') = '{"dishes": 3, "categories": 1}'::jsonb;
  set local role authenticated;
  begin perform public.owner_menu_import_save(v_a, '[]'); raise exception 'an empty import';
  exception when invalid_parameter_value then if sqlerrm <> 'rows' then raise; end if; end;
end $$;
reset role;

-- another owner: nothing of A's menu
set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000b';
do $$
declare
  v_a uuid := (select id from public.shops where slug = 'potraviny-centrum');
  v_soup uuid := (select v::uuid from t80 where k = 'soup');
begin
  begin perform public.owner_menu(v_a); raise exception 'owner B read A''s menu';
  exception when insufficient_privilege then null; end;
  begin perform public.owner_menu_save_item(v_a, v_soup, '{"price": "0.10"}'); raise exception 'owner B changed a price';
  exception when insufficient_privilege then null; end;
  begin perform public.owner_menu_set_sold_out(v_a, v_soup, true); raise exception 'owner B set sold out';
  exception when insufficient_privilege then null; end;
  begin perform public.owner_menu_save_category(v_a, null, 'B'); raise exception 'owner B made a category';
  exception when insufficient_privilege then null; end;
  begin perform public.owner_menu_import_hit(v_a); raise exception 'owner B imported';
  exception when insufficient_privilege then null; end;
  begin perform public.owner_menu_import_save(v_a, '[{"name": "B"}]'); raise exception 'owner B saved an import';
  exception when insufficient_privilege then null; end;
  begin perform public.owner_menu_duplicate_item(v_a, v_soup); raise exception 'owner B duplicated';
  exception when insufficient_privilege then null; end;
  begin perform 1 from public.menu_categories; raise exception 'owners read menu_categories';
  exception when insufficient_privilege then null; end;
end $$;
reset role;

-- the owner's AI tools (a Telegram link = an owner-MCP grant, update 66): list_menu freely; set_menu_sold_out only after
-- Potvrdiť + confirm
set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000a';
do $$
begin
  insert into t80 values ('tg_code', public.owner_telegram_link_start() ->> 'code');
end $$;
reset role;
set role service_role;
do $$
begin
  assert (public.telegram_claim((select v from t80 where k = 'tg_code'), 9080, 9080, 'private', 'bistro', 'sk') ->> 'ok')::boolean;
end $$;
reset role;
set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000a';
do $$
begin
  perform public.owner_telegram_consent(array[(select id from public.shops where slug = 'potraviny-centrum')], array['shop.read', 'shop.write']);
end $$;
reset role;
set role service_role;
do $$
declare
  v_soup uuid := (select v::uuid from t80 where k = 'soup');
  v_pending uuid;
  vj jsonb;
begin
  vj := public.telegram_call(9080, 'list_menu', '{}');
  assert exists (select 1 from jsonb_array_elements(vj -> 'result' -> 'items') i
                 where (i ->> 'item_id')::uuid = v_soup and (i ->> 'price')::numeric = 3.50 and not (i ->> 'sold_out_today')::boolean), vj::text;
  assert position('cost' in vj::text) = 0 and position('supplier' in vj::text) = 0, 'no costs or suppliers';
  begin perform public.telegram_call(9080, 'set_menu_sold_out', jsonb_build_object('item_id', v_soup, 'sold_out', true));
    raise exception 'a change without Potvrdiť';
  exception when insufficient_privilege then if sqlerrm <> 'needs_confirmation' then raise; end if; end;
  v_pending := public.telegram_pending_new(9080, 'set_menu_sold_out', jsonb_build_object('item_id', v_soup, 'sold_out', true), '{}');
  vj := public.telegram_confirm(9080, v_pending);
  assert not (vj -> 'out' -> 'result' ->> 'changed')::boolean and not (vj -> 'out' -> 'result' -> 'before' ->> 'sold_out_today')::boolean, vj::text;
  assert (select sold_out_on from public.sklad_items where shop_item_id = v_soup) is distinct from (select v::date from t80 where k = 'day');
  v_pending := public.telegram_pending_new(9080, 'set_menu_sold_out',
                 jsonb_build_object('item_id', v_soup, 'sold_out', true, 'confirm', true), '{}');
  vj := public.telegram_confirm(9080, v_pending);
  assert (vj -> 'out' -> 'result' ->> 'changed')::boolean and (vj -> 'out' -> 'result' -> 'item' ->> 'sold_out_today')::boolean, vj::text;
  begin perform public.telegram_call(9080, 'set_menu_sold_out', jsonb_build_object('item_id', gen_random_uuid(), 'confirm', true));
    raise exception 'an unknown dish';
  exception when insufficient_privilege then null; when no_data_found then null; end;
  -- every other tool still goes through update 74's door
  vj := public.telegram_call(9080, 'list_food_orders', '{"filter": "new"}');
  assert jsonb_typeof(vj -> 'result' -> 'orders') = 'array', vj::text;
end $$;
reset role;

-- tidy up: back to goods, ordering off, the day's hours, the subscription and the import counter as before
set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000a';
do $$
begin
  perform public.owner_set_shop_kind((select id from public.shops where slug = 'potraviny-centrum'), 'goods');
end $$;
reset role;
set role service_role;
do $$
declare
  v_a uuid := (select id from public.shops where slug = 'potraviny-centrum');
begin
  assert public.telegram_unlink_by_bot(9080);
  update public.food_settings set enabled = false where shop_id = v_a;
  delete from public.shop_special_hours where shop_id = v_a and date = (select v::date from t80 where k = 'day');
  delete from public.subscriptions where shop_id = v_a;
  insert into public.subscriptions
  select * from jsonb_populate_record(null::public.subscriptions, (select v::jsonb from t80 where k = 'sub'))
  where (select v from t80 where k = 'sub') is not null;
  assert public.shop_has_plan(v_a) = (select v::boolean from t80 where k = 'had_plan');
end $$;
reset role;
delete from public.owner_ai_usage where kind = 'menu';
drop table t80;

\echo '--- update 81: the order feed — the parts a shop uses (switched off = not used, nothing deleted), the times with the delay for the assistant, finish in one step (payment first, stock once), reopen the same day (stock back once, payment kept, stock again once), the delay reset job, the owner MCP and Telegram tools, owners only'
create temporary table t81 (k text primary key, v text);
grant all on t81 to public;

-- an order placed as the shop assistant places it (the SMS code + food_order_create)
create function pg_temp.t81_order(p_kind text, p_pay text, p_n integer, p_qty integer default 1)
returns uuid
language plpgsql
as $$
declare
  v_code jsonb;
  vj jsonb;
begin
  v_code := public.sms_code_start('potraviny-centrum', 'order', '0907 811 ' || lpad(p_n::text, 3, '0'), 'Zákazník ' || p_n,
                                  md5('t81-' || p_n), (select v::uuid from t81 where k = 'conv'), (select v from t81 where k = 'token'));
  vj := public.food_order_create((v_code ->> 'id')::uuid, v_code ->> 'code', gen_random_uuid(),
          jsonb_build_array(jsonb_build_object('item_id', (select v from t81 where k = 'pizza'), 'qty', p_qty)),
          p_kind, p_pay, case when p_kind = 'delivery' then 'Hlavná 8, Michalovce' end, null, null, null,
          (select v::uuid from t81 where k = 'conv'), (select v from t81 where k = 'token'), 'sk');
  if not (vj ->> 'ok')::boolean then raise exception 'order %: %', p_n, vj; end if;
  return (vj -> 'order' ->> 'id')::uuid;
end;
$$;
grant execute on function pg_temp.t81_order(text, text, integer, integer) to public;

set role service_role;
do $$
declare
  v_a uuid := (select id from public.shops where slug = 'potraviny-centrum');
  v_tz text := (select coalesce(timezone, 'UTC') from public.shops where id = v_a);
  v_open jsonb;
  v_pizza uuid;
  s public.food_settings;
begin
  insert into t81 values ('had_plan', public.shop_has_plan(v_a)::text),
    ('sub', (select to_jsonb(x) from public.subscriptions x where x.shop_id = v_a)::text),
    ('day', ((now() at time zone v_tz)::date)::text);
  insert into public.subscriptions (shop_id, status, plan, current_period_end, stripe_subscription_id)
  values (v_a, 'active', 'pro', now() + interval '30 days', 'sub_test_81')
  on conflict (shop_id) do update set status = 'active', current_period_end = now() + interval '30 days';
  insert into public.shop_special_hours (shop_id, date, closed, ranges)
  values (v_a, (now() at time zone v_tz)::date, false, '[["00:00","23:59"]]')
  on conflict (shop_id, date) do update set closed = false, ranges = excluded.ranges;
  v_open := public.assistant_open(v_a, 'sk', repeat('3', 32));
  v_pizza := (select si.id from public.sklad_items i join public.shop_items si on si.id = i.shop_item_id
              where i.shop_id = v_a and si.name = 'Margherita 32 cm');
  assert v_pizza is not null, 'update 73''s Sklad product is there';
  assert public.stock_source_of(v_a) = 'sklad', 'the test shop sells from Sklad';
  -- enough pizzas for this block
  insert into public.sklad_movements (id, shop_id, shop_item_id, location_id, kind, qty, ref, client_at)
  values (gen_random_uuid(), v_a, v_pizza, public.sklad_default_location(v_a, false), 'receipt', 40, 'Test 81', now());
  perform public.sklad_apply(v_a, array[v_pizza]);
  insert into t81 values ('conv', v_open ->> 'id'), ('token', v_open ->> 'token'), ('pizza', v_pizza::text);
  -- the new settings and their defaults (the courier app not chosen yet: on while the shop has an active courier)
  s := public.food_setup(v_a);
  assert s.delay_minutes = 0 and s.delay_reset = 'close' and s.warn_long_delay and s.payments_on and s.qr_terminal
     and s.feed_order = 'newest' and s.courier_app is null, to_jsonb(s)::text;
  assert not exists (select 1 from public.food_couriers where shop_id = v_a and active)
     and not (public.food_parts(v_a) ->> 'courier_app')::boolean, 'no courier → no courier app';
  assert (select is_nullable = 'YES' from information_schema.columns
          where table_schema = 'public' and table_name = 'food_orders' and column_name = 'pay_method'), 'an order may have no pay method';
  -- the reset job and the rules are not for visitors or owners to call
  assert not has_function_privilege('anon', 'public.food_delay_tick()', 'execute')
     and not has_function_privilege('authenticated', 'public.food_delay_tick()', 'execute')
     and not has_function_privilege('authenticated', 'public.food_order_finish(uuid, uuid, text, uuid, text, integer)', 'execute')
     and not has_function_privilege('authenticated', 'public.food_order_reopen(uuid, uuid, text, uuid)', 'execute')
     and not has_function_privilege('anon', 'public.owner_food_order_finish(uuid, uuid, uuid, text, integer)', 'execute')
     and not has_function_privilege('anon', 'public.owner_food_feed(uuid, boolean)', 'execute'), 'only the owner_* wrappers';
end $$;
reset role;

do $$
begin
  assert exists (select 1 from cron.job where jobname = 'ppi-food-delay-reset' and schedule = '*/5 * * * *'
                 and command = 'select public.food_delay_tick()'), 'the delay reset job, SQL only, every 5 minutes';
end $$;

-- the owner: the settings (only the fields given change), the parts, the times with the delay
set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000a';
do $$
declare
  v_a uuid := (select id from public.shops where slug = 'potraviny-centrum');
  vj jsonb;
  st jsonb;
begin
  vj := public.owner_food_save_settings(v_a, '{"enabled": true, "pickup_on": true, "delivery_on": true, "pay_cash": true, "pay_qr": true, "pay_card": true, "prep_minutes": 20, "delivery_minutes": 45, "assign_mode": "manual", "deduct_on_delivery": true}');
  if not exists (select 1 from public.owner_food_settings(v_a) x, jsonb_array_elements(x -> 'zones') z where z ->> 'kind' = 'town' and z ->> 'value' = 'Michalovce') then
    insert into t81 values ('zone', public.owner_food_save_zone(v_a, null, 'Michalovce 81', 'town', 'Michalovce', 150, 1200)::text);
  end if;
  assert vj -> 'parts' = '{"delivery": true, "courier_app": false, "payments": true, "register": true, "qr_terminal": true, "on": 4}'::jsonb, vj::text;
  -- only the fields given change
  vj := public.owner_food_save_settings(v_a, '{"feed_order": "oldest", "warn_long_delay": false}');
  assert vj ->> 'feed_order' = 'oldest' and not (vj ->> 'warn_long_delay')::boolean and (vj ->> 'prep_minutes')::int = 20
     and (vj ->> 'delivery_on')::boolean and (vj ->> 'payments_on')::boolean and vj ->> 'delay_reset' = 'close', vj::text;
  vj := public.owner_food_save_settings(v_a, '{"feed_order": "newest", "warn_long_delay": true}');
  begin perform public.owner_food_save_settings(v_a, '{"delay_reset": "sometimes"}'); raise exception 'any reset';
  exception when invalid_parameter_value then assert sqlerrm = 'delay_reset'; end;
  begin perform public.owner_food_save_settings(v_a, '{"feed_order": "random"}'); raise exception 'any order';
  exception when invalid_parameter_value then assert sqlerrm = 'feed_order'; end;
  begin perform public.owner_food_save_settings(v_a, '{"delay_minutes": 121}'); raise exception 'a delay over two hours';
  exception when invalid_parameter_value then assert sqlerrm = 'settings'; end;
  begin perform public.owner_food_save_settings(v_a, '{"payments_on": "yes"}'); raise exception 'a switch that is not one';
  exception when invalid_parameter_value then assert sqlerrm = 'payments_on'; end;
  -- the times: pickup prep + delay, delivery the estimate + delay, the same in food_state and food_quote
  st := public.food_state('potraviny-centrum');
  assert (st ->> 'ready_pickup_min')::int = 20 and (st ->> 'ready_delivery_min')::int = 45 and not (st ->> 'long_delay')::boolean
     and (st ->> 'payments')::boolean and (st -> 'pay' ->> 'cash')::boolean, st::text;
  vj := public.owner_food_set_delay(v_a, 30);
  assert (vj ->> 'delay_minutes')::int = 30 and (vj ->> 'ready_pickup_min')::int = 50 and (vj ->> 'ready_delivery_min')::int = 75
     and (vj ->> 'long_delay')::boolean, vj::text;
  st := public.food_state('potraviny-centrum');
  assert (st ->> 'ready_pickup_min')::int = 50 and (st ->> 'ready_delivery_min')::int = 75 and (st ->> 'long_delay')::boolean
     and (st ->> 'delay_minutes')::int = 30, st::text;
  assert (public.food_quote('potraviny-centrum', jsonb_build_array(jsonb_build_object('item_id', (select v from t81 where k = 'pizza'))), 'pickup')
          ->> 'ready_minutes')::int = 50, 'the quote has the same time';
  set local role service_role;
  assert exists (select 1 from public.shop_activity where shop_id = v_a and action = 'food_delay'
                 and details = '{"from": 0, "to": 30}'::jsonb and actor = '00000000-0000-0000-0000-00000000000a'), 'food_delay logged';
  set local role authenticated;
  -- the long-delay warning only with its switch, only from 30 minutes
  perform public.owner_food_save_settings(v_a, '{"warn_long_delay": false}');
  assert not (public.food_state('potraviny-centrum') ->> 'long_delay')::boolean;
  perform public.owner_food_save_settings(v_a, '{"warn_long_delay": true}');
  vj := public.owner_food_set_delay(v_a, 20);
  assert not (vj ->> 'long_delay')::boolean and (vj ->> 'ready_pickup_min')::int = 40, vj::text;
  begin perform public.owner_food_set_delay(v_a, 121); raise exception 'a delay over two hours';
  exception when invalid_parameter_value then assert sqlerrm = 'delay'; end;
  begin perform public.owner_food_set_delay(v_a, -5); raise exception 'a negative delay';
  exception when invalid_parameter_value then assert sqlerrm = 'delay'; end;
  -- the parts: the courier app needs delivery, the QR terminal needs payments; "Len feed" = 0 of 5, everything = 5
  vj := public.owner_food_save_settings(v_a, '{"delivery_on": false, "courier_app": false, "payments_on": false, "deduct_on_delivery": false, "qr_terminal": false}');
  assert (vj -> 'parts' ->> 'on')::int = 0, vj::text;
  vj := public.owner_food_save_settings(v_a, '{"courier_app": true, "qr_terminal": true}');
  assert not (vj -> 'parts' ->> 'courier_app')::boolean and not (vj -> 'parts' ->> 'qr_terminal')::boolean
     and (vj ->> 'courier_app')::boolean and (vj ->> 'qr_terminal')::boolean, 'switched on but not used without delivery / payments';
  vj := public.owner_food_save_settings(v_a, '{"delivery_on": true, "payments_on": true, "deduct_on_delivery": true}');
  assert (vj -> 'parts' ->> 'on')::int = 5, vj::text;
  assert (public.owner_food_tab(v_a) -> 'parts' ->> 'courier_app')::boolean, 'the Kuriéri tab reads the parts';
  vj := public.owner_food_save_settings(v_a, '{"courier_app": false}');
  assert not (public.owner_food_tab(v_a) -> 'parts' ->> 'courier_app')::boolean;
end $$;
reset role;

-- a visitor reads the same times; another owner cannot touch A's feed
set role anon;
do $$
declare
  st jsonb := public.food_state('potraviny-centrum');
begin
  assert (st ->> 'ready_pickup_min')::int = 40 and (st ->> 'ready_delivery_min')::int = 65 and st ? 'long_delay', st::text;
end $$;
reset role;
set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000b';
do $$
declare
  v_a uuid := (select id from public.shops where slug = 'potraviny-centrum');
begin
  begin perform public.owner_food_set_delay(v_a, 10); raise exception 'owner B set A''s delay';
  exception when insufficient_privilege then null; end;
  begin perform public.owner_food_feed(v_a); raise exception 'owner B read A''s feed';
  exception when insufficient_privilege then null; end;
  begin perform public.owner_food_order_finish(v_a, gen_random_uuid(), gen_random_uuid()); raise exception 'owner B finished an order';
  exception when insufficient_privilege then null; end;
  begin perform public.owner_food_order_reopen(v_a, gen_random_uuid(), gen_random_uuid()); raise exception 'owner B reopened an order';
  exception when insufficient_privilege then null; end;
end $$;
reset role;

-- orders: ready_by with the delay of that moment
set role service_role;
do $$
declare
  v_p1 uuid;
  v_d1 uuid;
  v_p2 uuid;
begin
  v_p1 := pg_temp.t81_order('pickup', 'cash', 1);
  v_d1 := pg_temp.t81_order('delivery', 'card', 2, 2);
  v_p2 := pg_temp.t81_order('pickup', 'cash', 3);
  insert into t81 values ('p1', v_p1::text), ('d1', v_d1::text), ('p2', v_p2::text);
  assert (select ready_by - created_at = interval '40 minutes' from public.food_orders where id = v_p1), 'pickup: prep 20 + delay 20';
  assert (select ready_by - created_at = interval '65 minutes' from public.food_orders where id = v_d1), 'delivery: 45 + delay 20';
  -- update 85: the customer never chooses; the method comes with the owner's or the courier's payment mark
  assert (select pay_method is null and paid_at is null from public.food_orders where id = v_p1);
end $$;
reset role;

-- the feed; "Vybavené" in one step (payment first), the stock once; "Vrátiť" the same day, the stock back once
set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000a';
do $$
declare
  v_a uuid := (select id from public.shops where slug = 'potraviny-centrum');
  v_pizza uuid := (select v::uuid from t81 where k = 'pizza');
  v_p1 uuid := (select v::uuid from t81 where k = 'p1');
  v_d1 uuid := (select v::uuid from t81 where k = 'd1');
  v_p2 uuid := (select v::uuid from t81 where k = 'p2');
  v_step uuid := gen_random_uuid();
  v_back uuid := gen_random_uuid();
  v_stock numeric;
  vj jsonb;
  ids uuid[];
begin
  vj := public.owner_food_feed(v_a);
  select array_agg((r ->> 'id')::uuid order by ord) into ids
  from jsonb_array_elements(vj -> 'active') with ordinality x(r, ord) where (r ->> 'id')::uuid in (v_p1, v_d1, v_p2);
  assert ids = array[v_p2, v_d1, v_p1], 'newest on top: ' || vj::text;
  assert not exists (select 1 from jsonb_array_elements(vj -> 'done') r where (r ->> 'id')::uuid in (v_p1, v_d1, v_p2));
  assert (vj -> 'times' ->> 'ready_pickup_min')::int = 40 and vj -> 'parts' ? 'payments' and vj ? 'older_count', vj::text;
  perform public.owner_food_save_settings(v_a, '{"feed_order": "oldest"}');
  select array_agg((r ->> 'id')::uuid order by ord) into ids
  from jsonb_array_elements(public.owner_food_feed(v_a) -> 'active') with ordinality x(r, ord) where (r ->> 'id')::uuid in (v_p1, v_d1, v_p2);
  assert ids = array[v_p1, v_d1, v_p2], 'oldest on top';
  perform public.owner_food_save_settings(v_a, '{"feed_order": "newest"}');

  v_stock := (public.owner_sklad_product(v_a, v_pizza) ->> 'total')::numeric;
  -- with payments: a payment mark first
  begin perform public.owner_food_order_finish(v_a, v_p1, gen_random_uuid()); raise exception 'finished unpaid';
  exception when raise_exception then assert sqlerrm = 'not_paid'; end;
  begin perform public.owner_food_order_finish(v_a, v_p1, gen_random_uuid(), 'cash', 100); raise exception 'less cash than the total';
  exception when invalid_parameter_value then assert sqlerrm = 'cash'; end;
  begin perform public.owner_food_order_finish(v_a, v_p1, null); raise exception 'no step id';
  exception when invalid_parameter_value then assert sqlerrm = 'step'; end;
  -- new → picked up at once (the steps in between skipped), paid in cash, the stock taken once
  vj := public.owner_food_order_finish(v_a, v_p1, v_step, 'cash', 2000);
  assert vj ->> 'status' = 'picked_up' and vj ->> 'finished' = 'picked_up' and vj ->> 'paid_at' is not null
     and (vj ->> 'stock_taken')::boolean and (vj ->> 'change_cents')::int = 2000 - (vj ->> 'total_cents')::int, vj::text;
  assert (public.owner_sklad_product(v_a, v_pizza) ->> 'total')::numeric = v_stock - 1, 'one pizza off';
  set local role service_role;
  assert (select count(*) from public.food_order_events where order_id = v_p1 and kind = 'status') = 2
     and exists (select 1 from public.food_order_events where order_id = v_p1 and kind = 'status' and from_status = 'new'
                 and to_status = 'picked_up' and step_id = v_step and detail = 'finish'), 'one step, new → picked up';
  set local role authenticated;
  -- the same step again (a retry) changes nothing
  vj := public.owner_food_order_finish(v_a, v_p1, v_step, 'cash', 2000);
  assert (vj ->> 'duplicate')::boolean and (public.owner_sklad_product(v_a, v_pizza) ->> 'total')::numeric = v_stock - 1, vj::text;
  begin perform public.owner_food_order_finish(v_a, v_p1, gen_random_uuid()); raise exception 'finished twice';
  exception when raise_exception then assert sqlerrm = 'step'; end;
  begin perform public.owner_food_order_finish(v_a, v_d1, v_step); raise exception 'one step id for two orders';
  exception when unique_violation then null; end;
  set local role service_role;
  assert exists (select 1 from public.shop_activity where shop_id = v_a and action = 'food_order_finished'
                 and details ->> 'order' = v_p1::text and details ->> 'to' = 'picked_up');
  set local role authenticated;
  -- the feed: grey at the bottom (finished today)
  vj := public.owner_food_feed(v_a);
  assert exists (select 1 from jsonb_array_elements(vj -> 'done') r where (r ->> 'id')::uuid = v_p1 and r ->> 'done_at' is not null)
     and not exists (select 1 from jsonb_array_elements(vj -> 'active') r where (r ->> 'id')::uuid = v_p1), vj::text;

  -- "Vrátiť": back to the state before, the stock back once (an Oprava), the payment mark kept
  vj := public.owner_food_order_reopen(v_a, v_p1, v_back);
  assert vj ->> 'status' = 'new' and vj ->> 'reopened' = 'new' and (vj ->> 'stock_returned')::boolean
     and vj ->> 'paid_at' is not null and vj ->> 'pay_method' = 'cash' and not (vj ->> 'stock_taken')::boolean, vj::text;
  assert (public.owner_sklad_product(v_a, v_pizza) ->> 'total')::numeric = v_stock, 'the pizza back';
  vj := public.owner_food_order_reopen(v_a, v_p1, v_back);
  assert (vj ->> 'duplicate')::boolean and (public.owner_sklad_product(v_a, v_pizza) ->> 'total')::numeric = v_stock, 'once';
  begin perform public.owner_food_order_reopen(v_a, v_p1, gen_random_uuid()); raise exception 'reopened an open order';
  exception when raise_exception then assert sqlerrm = 'step'; end;
  set local role service_role;
  assert exists (select 1 from public.shop_activity where shop_id = v_a and action = 'food_order_reopened'
                 and details ->> 'order' = v_p1::text and (details ->> 'stock_returned')::boolean);
  set local role authenticated;
  -- finished again (already paid: no mark needed): the stock taken again, once
  vj := public.owner_food_order_finish(v_a, v_p1, gen_random_uuid());
  assert vj ->> 'status' = 'picked_up' and (vj ->> 'stock_taken')::boolean, vj::text;
  assert (public.owner_sklad_product(v_a, v_pizza) ->> 'total')::numeric = v_stock - 1, 'taken again, once';

  -- a delivery without the courier app: → delivered, paid by card
  vj := public.owner_food_order_finish(v_a, v_d1, gen_random_uuid(), 'card');
  assert vj ->> 'status' = 'delivered' and vj ->> 'pay_method' = 'card', vj::text;
  assert (public.owner_sklad_product(v_a, v_pizza) ->> 'total')::numeric = v_stock - 3, 'two more pizzas off';
  -- a method that is off is refused
  perform public.owner_food_save_settings(v_a, '{"pay_card": false}');
  begin perform public.owner_food_order_finish(v_a, v_p2, gen_random_uuid(), 'card'); raise exception 'a method that is off';
  exception when invalid_parameter_value then assert sqlerrm = 'pay_method'; end;
  perform public.owner_food_save_settings(v_a, '{"pay_card": true}');
end $$;
reset role;

-- the movements: one sale per round, one opposite Oprava "Vrátené – objednávka č. n" — each once
set role service_role;
do $$
declare
  v_p1 uuid := (select v::uuid from t81 where k = 'p1');
  o public.food_orders;
  v_line uuid;
begin
  select * into o from public.food_orders where id = v_p1;
  select id into v_line from public.food_order_lines where order_id = v_p1;
  assert o.reopens = 1, 'one reopen';
  assert (select count(*) from public.sklad_movements where id in (md5(v_p1::text || ':' || v_line::text)::uuid,
                                                                      md5(v_p1::text || ':' || v_line::text || ':r1')::uuid)
          and kind = 'sale' and qty = -1) = 2, 'one sale per round';
  assert (select count(*) from public.sklad_movements where id = md5('back:' || md5(v_p1::text || ':' || v_line::text)::uuid::text)::uuid
          and kind = 'correction' and qty = 1 and reason = 'Vrátené – objednávka č. ' || o.number) = 1, 'one Oprava back';
  assert (select count(*) from public.sklad_movements m where m.kind = 'correction' and m.reason like 'Vrátené – objednávka č. %'
          and m.id in (select md5('back:' || x.id::text)::uuid from public.sklad_movements x
                       where x.id in (md5(v_p1::text || ':' || v_line::text)::uuid, md5(v_p1::text || ':' || v_line::text || ':r1')::uuid))) = 1,
    'the second round is not returned';
end $$;
-- a reopen only on the shop's same day: the finish moved to yesterday (the audit log is append-only; the test bypasses it)
reset role;
set session_replication_role = replica;
update public.food_order_events set created_at = created_at - interval '1 day'
where order_id = (select v::uuid from t81 where k = 'd1') and kind = 'status' and to_status = 'delivered';
set session_replication_role = default;
set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000a';
do $$
begin
  begin perform public.owner_food_order_reopen((select id from public.shops where slug = 'potraviny-centrum'), (select v::uuid from t81 where k = 'd1'), gen_random_uuid());
    raise exception 'reopened a day later';
  exception when raise_exception then assert sqlerrm = 'too_late'; end;
end $$;
reset role;

-- the courier app: a delivery goes "on the way" (a courier first) and counts as finished in the feed; without the app
-- no new assignment (the automatic one too); taking one away still works
update public.food_settings set courier_app = null where shop_id = (select id from public.shops where slug = 'potraviny-centrum');
set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000a';
do $$
declare
  v_a uuid := (select id from public.shops where slug = 'potraviny-centrum');
  vj jsonb;
begin
  -- not chosen yet: the first courier switches the app on (as the Kuriéri tab worked before this update)
  vj := public.owner_food_courier_save(v_a, null, 'Kuriér 81', '+421944000081', null);
  insert into t81 values ('courier', vj ->> 'id');
  assert (public.owner_food_tab(v_a) -> 'parts' ->> 'courier_app')::boolean, 'a courier → the app on';
  perform public.owner_food_save_settings(v_a, '{"courier_app": true}');
end $$;
reset role;
set role service_role;
do $$
begin
  insert into t81 values ('d2', pg_temp.t81_order('delivery', 'cash', 4, 2)::text);
end $$;
reset role;
set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000a';
do $$
declare
  v_a uuid := (select id from public.shops where slug = 'potraviny-centrum');
  v_d2 uuid := (select v::uuid from t81 where k = 'd2');
  v_c uuid := (select v::uuid from t81 where k = 'courier');
  vj jsonb;
begin
  begin perform public.owner_food_order_finish(v_a, v_d2, gen_random_uuid()); raise exception 'on the way without a courier';
  exception when raise_exception then assert sqlerrm = 'courier'; end;
  perform public.owner_food_assign(v_a, v_d2, v_c, gen_random_uuid());
  -- unpaid is fine: the courier takes the payment
  vj := public.owner_food_order_finish(v_a, v_d2, gen_random_uuid());
  assert vj ->> 'status' = 'on_the_way' and vj ->> 'finished' = 'on_the_way' and not (vj ->> 'stock_taken')::boolean, vj::text;
  vj := public.owner_food_feed(v_a);
  assert exists (select 1 from jsonb_array_elements(vj -> 'done') r where (r ->> 'id')::uuid = v_d2 and r ->> 'done_at' is not null), vj::text;
  begin perform public.owner_food_order_finish(v_a, v_d2, gen_random_uuid()); raise exception 'handed over twice';
  exception when raise_exception then assert sqlerrm = 'step'; end;
  -- back from on the way to new (the state before)
  vj := public.owner_food_order_reopen(v_a, v_d2, gen_random_uuid());
  assert vj ->> 'status' = 'new' and not (vj ->> 'stock_returned')::boolean, vj::text;
  assert exists (select 1 from jsonb_array_elements(public.owner_food_feed(v_a) -> 'active') r where (r ->> 'id')::uuid = v_d2);
  -- the courier app off: no new assignment; the courier stays
  perform public.owner_food_assign(v_a, v_d2, null, gen_random_uuid());
  perform public.owner_food_save_settings(v_a, '{"courier_app": false, "assign_mode": "auto"}');
  begin perform public.owner_food_assign(v_a, v_d2, v_c, gen_random_uuid()); raise exception 'assigned without the courier app';
  exception when raise_exception then assert sqlerrm = 'courier_app'; end;
  set local role service_role;
  assert exists (select 1 from public.food_couriers where id = v_c and active), 'the courier is kept';
  set local role authenticated;
  -- without the courier app a delivery is finished as delivered (paid)
  vj := public.owner_food_order_finish(v_a, v_d2, gen_random_uuid(), 'cash');
  assert vj ->> 'status' = 'delivered', vj::text;
end $$;
reset role;
-- the automatic assignment: a signed-in courier, the courier app off → none; on → assigned
set role service_role;
do $$
declare
  v_a uuid := (select id from public.shops where slug = 'potraviny-centrum');
  v_c uuid := (select v::uuid from t81 where k = 'courier');
begin
  insert into public.food_courier_sessions (courier_id, shop_id, token_hash, expires_at, last_seen_at)
  values (v_c, v_a, md5('t81-session'), now() + interval '1 day', now());
  insert into t81 values ('d3', pg_temp.t81_order('delivery', 'cash', 5, 2)::text);
end $$;
reset role;
do $$
begin
  assert (select courier_id is null from public.food_orders where id = (select v::uuid from t81 where k = 'd3')), 'no automatic assignment without the app';
end $$;
set role service_role;
do $$
begin
  update public.food_settings set courier_app = true where shop_id = (select id from public.shops where slug = 'potraviny-centrum');
  insert into t81 values ('d4', pg_temp.t81_order('delivery', 'cash', 6, 2)::text);
end $$;
reset role;
do $$
begin
  assert (select courier_id = (select v::uuid from t81 where k = 'courier') from public.food_orders where id = (select v::uuid from t81 where k = 'd4')),
    'assigned automatically with the app';
  update public.food_settings set courier_app = false, assign_mode = 'manual' where shop_id = (select id from public.shops where slug = 'potraviny-centrum');
end $$;

-- without "Platby v Cacaduu": no payment methods, no pay method on the order, no payment marks, finished unpaid
set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000a';
do $$
declare
  v_a uuid := (select id from public.shops where slug = 'potraviny-centrum');
  st jsonb;
begin
  perform public.owner_food_save_settings(v_a, '{"payments_on": false}');
  st := public.food_state('potraviny-centrum');
  assert not (st ->> 'payments')::boolean and st -> 'pay' = '{"qr": false, "cash": false, "card": false}'::jsonb, st::text;
  set local role service_role;
  assert (select pay_qr and pay_cash from public.food_settings where shop_id = v_a), 'the pay switches are kept';
  set local role authenticated;
end $$;
reset role;
set role service_role;
do $$
declare
  v_a uuid := (select id from public.shops where slug = 'potraviny-centrum');
begin
  assert public.food_courier_perms(v_a) = '{"qr": false, "cash": false, "card": false}'::jsonb, 'couriers mark no payment';
  insert into t81 values ('p3', pg_temp.t81_order('pickup', 'cash', 7)::text), ('p4', pg_temp.t81_order('pickup', null, 8)::text);
  assert (select pay_method is null from public.food_orders where id = (select v::uuid from t81 where k = 'p3')), 'no pay method, whatever was sent';
  assert (select pay_method is null from public.food_orders where id = (select v::uuid from t81 where k = 'p4'));
end $$;
reset role;
set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000a';
do $$
declare
  v_a uuid := (select id from public.shops where slug = 'potraviny-centrum');
  v_p3 uuid := (select v::uuid from t81 where k = 'p3');
  v_p4 uuid := (select v::uuid from t81 where k = 'p4');
  vj jsonb;
begin
  begin perform public.owner_food_order_finish(v_a, v_p3, gen_random_uuid(), 'cash'); raise exception 'a payment mark without payments';
  exception when invalid_parameter_value then assert sqlerrm = 'pay_method'; end;
  begin perform public.owner_food_order_status(v_a, v_p3, null, gen_random_uuid(), 'cash'); raise exception 'a payment step without payments';
  exception when invalid_parameter_value then assert sqlerrm = 'pay_method'; end;
  vj := public.owner_food_order_finish(v_a, v_p3, gen_random_uuid());
  assert vj ->> 'status' = 'picked_up' and vj ->> 'paid_at' is null and vj ->> 'pay_method' is null, vj::text;
  -- the board's own steps too: ready → picked up without a mark
  perform public.owner_food_order_status(v_a, v_p4, 'ready', gen_random_uuid());
  vj := public.owner_food_order_status(v_a, v_p4, 'picked_up', gen_random_uuid());
  assert vj ->> 'status' = 'picked_up' and vj ->> 'paid_at' is null, vj::text;
  -- payments back on: an unpaid order needs its mark again
  perform public.owner_food_save_settings(v_a, '{"payments_on": true}');
  vj := public.owner_food_order_reopen(v_a, v_p4, gen_random_uuid());
  assert vj ->> 'status' = 'ready', 'back to the state before (ready): ' || vj::text;
  begin perform public.owner_food_order_finish(v_a, v_p4, gen_random_uuid()); raise exception 'finished unpaid with payments on';
  exception when raise_exception then assert sqlerrm = 'not_paid'; end;
  vj := public.owner_food_order_finish(v_a, v_p4, gen_random_uuid(), 'cash');
  assert vj ->> 'status' = 'picked_up' and vj ->> 'pay_method' = 'cash', vj::text;
end $$;
reset role;

-- the delay goes back to 0 by itself: midnight (the day after it was set), close (the end of its open range), never
reset role;
do $$
declare
  v_a uuid := (select id from public.shops where slug = 'potraviny-centrum');
  v_tz text := (select coalesce(timezone, 'UTC') from public.shops where id = v_a);
  n integer;
begin
  update public.food_settings set delay_minutes = 20, delay_reset = 'never', delay_set_at = now() - interval '3 days' where shop_id = v_a;
  assert public.food_delay_due(v_a) is null;
  perform public.food_delay_tick();
  assert (select delay_minutes from public.food_settings where shop_id = v_a) = 20, 'never = kept';
  update public.food_settings set delay_reset = 'midnight', delay_set_at = now() where shop_id = v_a;
  assert public.food_delay_due(v_a) = (((now() at time zone v_tz)::date + 1)::timestamp at time zone v_tz), 'the shop''s next midnight';
  perform public.food_delay_tick();
  assert (select delay_minutes from public.food_settings where shop_id = v_a) = 20, 'not yet';
  -- today's range ends at 23:59 in the shop's time
  update public.food_settings set delay_reset = 'close' where shop_id = v_a;
  assert public.food_delay_due(v_a) = (((now() at time zone v_tz)::date + time '23:59')::timestamp at time zone v_tz), 'the end of today''s range';
  update public.food_settings set delay_reset = 'midnight', delay_set_at = now() - interval '1 day' where shop_id = v_a;
  n := public.food_delay_tick();
  assert n >= 1 and (select delay_minutes from public.food_settings where shop_id = v_a) = 0, 'reset at midnight';
  assert exists (select 1 from public.shop_activity where shop_id = v_a and action = 'food_delay' and details ->> 'by' = 'reset');
  update public.food_settings set delay_minutes = 45, delay_reset = 'close', delay_set_at = now() - interval '2 days' where shop_id = v_a;
  perform public.food_delay_tick();
  assert (select delay_minutes from public.food_settings where shop_id = v_a) = 0, 'reset at closing';
  update public.food_settings set delay_reset = 'close' where shop_id = v_a;
end $$;

-- the owner's AI tools (a Telegram link = an owner-MCP grant): set_food_delay, finish_food_order and reopen_food_order
-- only after Potvrdiť + confirm; without confirm only before → after
set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000a';
do $$
begin
  insert into t81 values ('tg_code', public.owner_telegram_link_start() ->> 'code');
end $$;
reset role;
set role service_role;
do $$
begin
  assert (public.telegram_claim((select v from t81 where k = 'tg_code'), 9081, 9081, 'private', 'bistro', 'sk') ->> 'ok')::boolean;
  insert into t81 values ('p5', pg_temp.t81_order('pickup', 'cash', 9)::text);
end $$;
reset role;
set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000a';
do $$
begin
  perform public.owner_telegram_consent(array[(select id from public.shops where slug = 'potraviny-centrum')], array['shop.read', 'shop.write']);
end $$;
reset role;
set role service_role;
do $$
declare
  v_a uuid := (select id from public.shops where slug = 'potraviny-centrum');
  v_p5 uuid := (select v::uuid from t81 where k = 'p5');
  v_pending uuid;
  vj jsonb;
begin
  assert public.mcp_tool_scope('set_food_delay') = 'shop.write' and public.mcp_tool_scope('finish_food_order') = 'shop.write'
     and public.mcp_tool_scope('reopen_food_order') = 'shop.write';
  begin perform public.telegram_call(9081, 'set_food_delay', '{"minutes": 10, "confirm": true}'); raise exception 'a write without Potvrdiť';
  exception when insufficient_privilege then assert sqlerrm = 'needs_confirmation'; end;
  -- without confirm: before → after, nothing changed
  v_pending := public.telegram_pending_new(9081, 'set_food_delay', '{"minutes": 30}', '{}');
  vj := public.telegram_confirm(9081, v_pending);
  assert not (vj -> 'out' -> 'result' ->> 'changed')::boolean and (vj -> 'out' -> 'result' -> 'after' ->> 'delay_minutes')::int = 30
     and (vj -> 'out' -> 'result' -> 'after' ->> 'pickup_in_min')::int = 50, vj::text;
  assert (select delay_minutes from public.food_settings where shop_id = v_a) = 0;
  v_pending := public.telegram_pending_new(9081, 'set_food_delay', '{"minutes": 10, "confirm": true}', '{}');
  vj := public.telegram_confirm(9081, v_pending);
  assert (vj -> 'out' -> 'result' ->> 'changed')::boolean and (vj -> 'out' -> 'result' -> 'times' ->> 'ready_pickup_min')::int = 30, vj::text;
  assert (select delay_minutes from public.food_settings where shop_id = v_a) = 10;
  assert exists (select 1 from public.shop_activity where shop_id = v_a and action = 'food_delay' and details ->> 'source' = 'telegram');
  v_pending := public.telegram_pending_new(9081, 'set_food_delay', '{"minutes": 200, "confirm": true}', '{}');
  begin perform public.telegram_confirm(9081, v_pending); raise exception 'a delay of 200 minutes';
  exception when invalid_parameter_value then null; end;
  -- finish (paid in cash) and reopen
  v_pending := public.telegram_pending_new(9081, 'finish_food_order', jsonb_build_object('order_id', v_p5), '{}');
  vj := public.telegram_confirm(9081, v_pending);
  assert not (vj -> 'out' -> 'result' ->> 'changed')::boolean and (vj -> 'out' -> 'result' ->> 'needs_payment_first')::boolean
     and vj -> 'out' -> 'result' -> 'after' ->> 'status' = 'picked_up', vj::text;
  v_pending := public.telegram_pending_new(9081, 'finish_food_order', jsonb_build_object('order_id', v_p5, 'paid_with', 'cash', 'confirm', true), '{}');
  vj := public.telegram_confirm(9081, v_pending);
  assert (vj -> 'out' -> 'result' ->> 'changed')::boolean and vj -> 'out' -> 'result' -> 'order' ->> 'status' = 'picked_up', vj::text;
  v_pending := public.telegram_pending_new(9081, 'reopen_food_order', jsonb_build_object('order_id', v_p5, 'confirm', true), '{}');
  vj := public.telegram_confirm(9081, v_pending);
  assert vj -> 'out' -> 'result' -> 'order' ->> 'status' = 'new', vj::text;
  -- every other tool still goes through the older doors
  vj := public.telegram_call(9081, 'list_food_orders', '{"filter": "new"}');
  assert exists (select 1 from jsonb_array_elements(vj -> 'result' -> 'orders') x where (x ->> 'id')::uuid = v_p5), vj::text;
  vj := public.telegram_call(9081, 'list_menu', '{}');
  assert vj -> 'result' ? 'items', vj::text;
end $$;
reset role;

\echo '--- update 82: list_food_orders also carries the kitchen''s times and the parts (the Meškanie button''s before → after), through the same door'
set role service_role;
do $$
declare
  v_a uuid := (select id from public.shops where slug = 'potraviny-centrum');
  vj jsonb;
  v_door text;
begin
  -- update 81's door is kept under its own name, callable only by the newest door
  assert to_regprocedure('public.owner_mcp_call_81(text, text, jsonb)') is not null;
  v_door := 'public.owner_mcp_call_81(text, text, jsonb)';
  assert not has_function_privilege('anon', v_door, 'execute') and not has_function_privilege('authenticated', v_door, 'execute');
  assert has_function_privilege('anon', 'public.owner_mcp_call(text, text, jsonb)', 'execute');
  update public.food_settings set delay_minutes = 20, prep_minutes = 25, delivery_minutes = 40 where shop_id = v_a;
  vj := public.telegram_call(9081, 'list_food_orders', '{"limit": 1}');
  assert (vj -> 'result' -> 'times' ->> 'delay_minutes')::int = 20 and (vj -> 'result' -> 'times' ->> 'ready_pickup_min')::int = 45
     and (vj -> 'result' -> 'times' ->> 'ready_delivery_min')::int = 60 and vj -> 'result' -> 'times' ? 'delay_reset', vj::text;
  assert vj -> 'result' -> 'parts' ? 'delivery' and vj -> 'result' -> 'parts' ? 'payments', vj::text;
  -- the orders and the open state are as before
  assert vj -> 'result' ? 'orders' and vj -> 'result' ? 'accepting' and vj ->> 'shop' = 'potraviny-centrum', vj::text;
  -- other tools: nothing added
  vj := public.telegram_call(9081, 'list_menu', '{}');
  assert not (vj -> 'result' ? 'times'), vj::text;
  -- the door still refuses what update 81's refused
  begin perform public.telegram_call(9081, 'set_food_delay', '{"minutes": 10, "confirm": true}'); raise exception 'a write without Potvrdiť';
  exception when insufficient_privilege then assert sqlerrm = 'needs_confirmation'; end;
  begin perform public.owner_mcp_call('not-a-token', 'list_food_orders', '{}'); raise exception 'a wrong token';
  exception when others then assert sqlerrm like 'invalid_token%', sqlerrm; end;
  update public.food_settings set delay_minutes = 0, prep_minutes = 20, delivery_minutes = 45 where shop_id = v_a;
end $$;
reset role;

-- tidy up: ordering off, the parts and the delay as by default, the courier, the day's hours, the subscription
set role service_role;
do $$
declare
  v_a uuid := (select id from public.shops where slug = 'potraviny-centrum');
begin
  assert public.telegram_unlink_by_bot(9081);
  update public.food_settings set enabled = false, delay_minutes = 0, delay_reset = 'close', payments_on = true, qr_terminal = true,
    courier_app = null, feed_order = 'newest', warn_long_delay = true, assign_mode = 'manual' where shop_id = v_a;
  delete from public.food_couriers where id = (select v::uuid from t81 where k = 'courier');
  delete from public.food_zones where id = (select v::uuid from t81 where k = 'zone');
  delete from public.shop_special_hours where shop_id = v_a and date = (select v::date from t81 where k = 'day');
  delete from public.subscriptions where shop_id = v_a;
  insert into public.subscriptions
  select * from jsonb_populate_record(null::public.subscriptions, (select v::jsonb from t81 where k = 'sub'))
  where (select v from t81 where k = 'sub') is not null;
  assert public.shop_has_plan(v_a) = (select v::boolean from t81 where k = 'had_plan');
end $$;
reset role;
drop function pg_temp.t81_order(text, text, integer, integer);
drop table t81;

\echo '--- update 83: the busiest shop of each SMS quota this month, counted as the quota counts (failed never), admins only'
create temporary table t83 (k text primary key, v text);
grant all on t83 to public;
set role service_role;
do $$
declare
  v_a uuid := (select id from public.shops where slug = 'potraviny-centrum');
begin
  insert into public.shop_outgoing_messages (shop_id, channel, recipient, body, status, kind, parts)
  values (v_a, 'sms', '+421905000083', 't83', 'test', 'owner', 2),
         (v_a, 'sms', '+421905000083', 't83', 'failed', 'owner', 7);
  insert into t83 values
    ('owner', (select max(public.sms_quota_used(s.id, 'owner')) from public.shops s)::text),
    ('a_owner', public.sms_quota_used(v_a, 'owner')::text);
end $$;
reset role;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000a';
set role authenticated;
do $$
begin
  begin perform public.admin_sms_busiest(); raise exception 'an owner read the busiest shop';
  exception when insufficient_privilege then null; end;
end $$;
reset role;
reset request.jwt.claim.sub;
set role anon;
do $$
begin
  begin perform public.admin_sms_busiest(); raise exception 'anon read the busiest shop';
  exception when insufficient_privilege then null; end;
end $$;
reset role;
set request.jwt.claim.sub = '00000000-0000-0000-0000-0000000000ad';
set role authenticated;
do $$
begin
  assert (select count(*) from public.admin_sms_busiest()) = (select count(*) from public.admin_sms_quotas()), 'one row per quota';
  assert (select v::integer >= 2 from t83 where k = 'a_owner'), 'the test SMS counts, the failed one does not change the max';
  assert (select used = (select v::integer from t83 where k = 'owner') and shop_slug is not null and monthly > 0
          from public.admin_sms_busiest() where quota = 'owner'), 'the busiest shop of the owner quota';
  assert (select bool_and(used >= 0 and (used = 0) = (shop_slug is null)) from public.admin_sms_busiest()), 'no shop when nothing was sent';
end $$;
reset role;
reset request.jwt.claim.sub;
set role service_role;
delete from public.shop_outgoing_messages where body = 't83' and recipient = '+421905000083';
reset role;
drop table t83;

\echo '--- update 84: the restaurant and the dish of a menu item (a size gives its dish), only while the Menu shows it'
create temporary table t84 (k text primary key, v uuid);
grant all on t84 to public;
set role service_role;
insert into t84
select 'pizza', id from public.shop_items where name = 'Pizza Diavola 80'
union all select 'p32', id from public.shop_items where name = 'Pizza Diavola 80 32 cm'
union all select 'p45', id from public.shop_items where name = 'Pizza Diavola 80 45 cm'
union all select 'cheese', id from public.shop_items where name = 'Syr navyše 80'
union all select 'goods', (select id from public.shop_items where shop_id = (select id from public.shops where slug = 'drogeria-kostolne') limit 1)
union all select 'shop', id from public.shops where slug = 'potraviny-centrum';
reset role;
set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000a';
do $$
begin
  perform public.owner_set_shop_kind((select v from t84 where k = 'shop'), 'food');
end $$;
reset role;
set role anon;
do $$
declare
  v_pizza uuid := (select v from t84 where k = 'pizza');
  vj jsonb;
begin
  assert (select count(*) from t84 where v is not null) = 6, 'the menu of update 80''s block';
  vj := public.shop_menu_dish_of(v_pizza);
  assert vj ->> 'slug' = 'potraviny-centrum' and (vj ->> 'dish')::uuid = v_pizza, vj::text;
  vj := public.shop_menu_dish_of((select v from t84 where k = 'p45'));
  assert vj ->> 'slug' = 'potraviny-centrum' and (vj ->> 'dish')::uuid = v_pizza, 'a size gives its dish: ' || coalesce(vj::text, 'null');
  -- update 80's block hid the 32 cm size (the dish was saved with 45 cm only): not on the Menu, no dish
  assert public.shop_menu_dish_of((select v from t84 where k = 'p32')) is null, 'a hidden size';
  -- the dish is one shop_menu() shows
  assert exists (select 1 from jsonb_array_elements(public.shop_menu('potraviny-centrum') -> 'items') i where (i ->> 'id')::uuid = v_pizza);
  assert public.shop_menu_dish_of((select v from t84 where k = 'cheese')) is null, 'an extra that is not on the menu';
  assert public.shop_menu_dish_of(gen_random_uuid()) is null, 'an unknown id';
  assert public.shop_menu_dish_of((select v from t84 where k = 'goods')) is null, 'a product of a shop with goods';
end $$;
reset role;
-- hidden: the dish (and so its sizes) is gone
set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000a';
do $$
begin
  perform public.owner_menu_save_item((select v from t84 where k = 'shop'), (select v from t84 where k = 'pizza'), '{"hidden": true}');
end $$;
reset role;
set role anon;
do $$
begin
  assert public.shop_menu_dish_of((select v from t84 where k = 'pizza')) is null, 'a hidden dish';
  assert public.shop_menu_dish_of((select v from t84 where k = 'p45')) is null, 'a size of a hidden dish';
end $$;
reset role;
set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000a';
do $$
begin
  perform public.owner_menu_save_item((select v from t84 where k = 'shop'), (select v from t84 where k = 'pizza'), '{"hidden": false}');
  -- back to goods: no restaurant, no dish
  perform public.owner_set_shop_kind((select v from t84 where k = 'shop'), 'goods');
end $$;
reset role;
set role anon;
do $$
begin
  assert public.shop_menu_dish_of((select v from t84 where k = 'pizza')) is null, 'a shop with goods has no dishes';
end $$;
reset role;
reset request.jwt.claim.sub;
drop table t84;

\echo '--- update 85: the order panel — no pay method from the customer (the mark still needed before the handover with Platby), the payment note after ordering (default, own, "-" = none, translated like the assistant''s texts), failed code SMS do not count toward the code limits'
create temporary table t85 (k text primary key, v text);
grant all on t85 to public;
set role service_role;
do $$
declare
  v_a uuid := (select id from public.shops where slug = 'potraviny-centrum');
  v_tz text := (select coalesce(timezone, 'UTC') from public.shops where id = v_a);
  v_open jsonb;
  v_pizza uuid;
begin
  insert into t85 values ('had_plan', public.shop_has_plan(v_a)::text),
    ('sub', (select to_jsonb(x) from public.subscriptions x where x.shop_id = v_a)::text),
    ('day', ((now() at time zone v_tz)::date)::text);
  insert into public.subscriptions (shop_id, status, plan, current_period_end, stripe_subscription_id)
  values (v_a, 'active', 'pro', now() + interval '30 days', 'sub_test_85')
  on conflict (shop_id) do update set status = 'active', current_period_end = now() + interval '30 days';
  insert into public.shop_special_hours (shop_id, date, closed, ranges)
  values (v_a, (now() at time zone v_tz)::date, false, '[["00:00","23:59"]]')
  on conflict (shop_id, date) do update set closed = false, ranges = excluded.ranges;
  v_open := public.assistant_open(v_a, 'sk', repeat('5', 32));
  v_pizza := (select si.id from public.sklad_items i join public.shop_items si on si.id = i.shop_item_id
              where i.shop_id = v_a and si.name = 'Margherita 32 cm');
  insert into public.sklad_movements (id, shop_id, shop_item_id, location_id, kind, qty, ref, client_at)
  values (gen_random_uuid(), v_a, v_pizza, public.sklad_default_location(v_a, false), 'receipt', 10, 'Test 85', now());
  perform public.sklad_apply(v_a, array[v_pizza]);
  insert into t85 values ('conv', v_open ->> 'id'), ('token', v_open ->> 'token'), ('pizza', v_pizza::text), ('shop', v_a::text);
  -- the code SMS rows of the block are not in the shop's monthly quota's way
  update public.food_settings set enabled = true, pickup_on = true, payments_on = true, pay_cash = true where shop_id = v_a;
end $$;
reset role;

-- orders: pay_method null whatever was sent and whatever "Platby v Cacaduu" says
set role service_role;
do $$
declare
  v_a uuid := (select v::uuid from t85 where k = 'shop');
  v_code jsonb;
  vj jsonb;
  v_o uuid;
  v_pay text;
begin
  foreach v_pay in array array['cash', 'card', null, 'nonsense'] loop
    v_code := public.sms_code_start('potraviny-centrum', 'order', '0907 885 ' || lpad((coalesce(length(v_pay), 0))::text, 3, '0'),
                                    'Zákazník 85', md5('t85-' || coalesce(v_pay, 'null')),
                                    (select v::uuid from t85 where k = 'conv'), (select v from t85 where k = 'token'));
    vj := public.food_order_create((v_code ->> 'id')::uuid, v_code ->> 'code', gen_random_uuid(),
            jsonb_build_array(jsonb_build_object('item_id', (select v from t85 where k = 'pizza'), 'qty', 1)),
            'pickup', v_pay, null, null, null, null,
            (select v::uuid from t85 where k = 'conv'), (select v from t85 where k = 'token'), 'sk');
    assert (vj ->> 'ok')::boolean, vj::text;
    v_o := (vj -> 'order' ->> 'id')::uuid;
    assert (select pay_method is null and paid_at is null from public.food_orders where id = v_o),
      'no pay method from the customer: ' || coalesce(v_pay, 'null');
  end loop;
  insert into t85 values ('order', v_o::text);
  -- with Platby on, picked up still needs the mark first (unchanged)
  perform public.food_order_step(v_o, 'ready', 'owner', null, gen_random_uuid());
  begin perform public.food_order_step(v_o, 'picked_up', 'owner', null, gen_random_uuid()); raise exception 'picked up unpaid';
  exception when raise_exception then assert sqlerrm = 'not_paid', sqlerrm; end;
  begin perform public.food_order_finish(v_o, gen_random_uuid(), 'owner', null, null, null); raise exception 'finished unpaid';
  exception when raise_exception then assert sqlerrm = 'not_paid', sqlerrm; end;
  -- the owner's mark gives the order its method
  vj := public.food_order_finish(v_o, gen_random_uuid(), 'owner', null, 'cash', null);
  assert vj ->> 'status' = 'picked_up' and vj ->> 'pay_method' = 'cash' and vj ->> 'paid_at' is not null, vj::text;
end $$;
reset role;

-- the payment note: null = the default line, own text (plain, ≤ 120), "-" = none; in food_state and translated
set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000a';
do $$
declare
  v_a uuid := (select v::uuid from t85 where k = 'shop');
  vj jsonb;
begin
  assert (public.owner_food_settings(v_a) ->> 'pay_note') is null, 'the default line';
  vj := public.owner_food_save_settings(v_a, jsonb_build_object('pay_note', '  Platba <b>kartou</b> nie je možná. Viac na www.example.com  '));
  assert vj ->> 'pay_note' = 'Platba kartou nie je možná. Viac na', vj ->> 'pay_note';
  vj := public.owner_food_save_settings(v_a, jsonb_build_object('pay_note', repeat('á', 200)));
  assert char_length(vj ->> 'pay_note') = 120, 'at most 120 characters';
  vj := public.owner_food_save_settings(v_a, '{"pay_note": " - "}');
  assert vj ->> 'pay_note' = '-', '"-" = no line';
  vj := public.owner_food_save_settings(v_a, '{"prep_minutes": 20}');
  assert vj ->> 'pay_note' = '-', 'only the fields given change';
  vj := public.owner_food_save_settings(v_a, '{"pay_note": ""}');
  assert vj ->> 'pay_note' is null, 'empty = the default line';
  vj := public.owner_food_save_settings(v_a, '{"pay_note": null}');
  assert vj ->> 'pay_note' is null;
  begin perform public.owner_food_save_settings(v_a, '{"pay_note": 5}'); raise exception 'a number as the note';
  exception when invalid_parameter_value then assert sqlerrm = 'pay_note'; end;
  vj := public.owner_food_save_settings(v_a, '{"pay_note": "Prosíme, platte radšej v hotovosti."}');
  assert exists (select 1 from public.shop_activity where shop_id = v_a and action = 'food_settings_saved'
                 and details -> 'fields' ? 'pay_note');
end $$;
reset role;
set role anon;
do $$
begin
  assert public.food_state('potraviny-centrum') ->> 'pay_note' = 'Prosíme, platte radšej v hotovosti.', public.food_state('potraviny-centrum')::text;
end $$;
reset role;
set role service_role;
do $$
declare
  v_a uuid := (select v::uuid from t85 where k = 'shop');
begin
  assert public.preset_translation_kind('food_pay_note') and public.page_text_group('food_pay_note') = 'assistant';
  assert exists (select 1 from public.translation_sources(v_a) s where s.kind = 'food_pay_note' and s.ref = v_a::text
                 and s.source = 'Prosíme, platte radšej v hotovosti.'), 'a source of the translation runs';
  -- kept in every pre-translated language and in the shop's own one (like the assistant's texts)
  assert public.shop_main_lang(v_a) = any (public.shop_target_langs(v_a, 'food_pay_note'));
  assert exists (select 1 from public.translation_work(2000, v_a) w where w.kind = 'food_pay_note' and w.source_lang = 'auto');
  insert into public.content_translations (shop_id, kind, ref, lang, text, status, source_hash)
  values (v_a, 'food_pay_note', v_a::text, 'en', 'Please pay in cash if you can.', 'ai', md5('Prosíme, platte radšej v hotovosti.'));
end $$;
reset role;
set role anon;
do $$
begin
  assert exists (select 1 from public.shop_translations('potraviny-centrum', 'en', array['food_pay_note']) t
                 where t.text = 'Please pay in cash if you can.'), 'the visitors read the translation';
end $$;
reset role;
-- "-" = no line, and nothing to translate any more (the old translation is never shown)
set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000a';
do $$ begin perform public.owner_food_save_settings((select v::uuid from t85 where k = 'shop'), '{"pay_note": "-"}'); end $$;
reset role;
set role anon;
do $$
begin
  assert not exists (select 1 from public.shop_translations('potraviny-centrum', 'en', array['food_pay_note'])), 'no line, no translation';
end $$;
reset role;

-- failed code SMS do not count: 3 failed + 1 → allowed; 3 sent + 1 → refused
set role service_role;
do $$
declare
  v_a uuid := (select v::uuid from t85 where k = 'shop');
  v_code jsonb;
  v_msg uuid;
  i integer;
  v_status text;
  v_phone text;
begin
  foreach v_status in array array['failed', 'sent'] loop
    v_phone := case v_status when 'failed' then '0907 885 801' else '0907 885 802' end;
    for i in 1..3 loop
      v_code := public.sms_code_start('potraviny-centrum', 'order', v_phone, 'Zákazník 85', md5('t85-sms-' || v_status || i),
                                      (select v::uuid from t85 where k = 'conv'), (select v from t85 where k = 'token'));
      v_msg := public.sms_code_claim((v_code ->> 'id')::uuid, 'Kód 123456');
      assert (select message_id from public.sms_codes where id = (v_code ->> 'id')::uuid) = v_msg, 'the code keeps its message';
      assert public.booking_sms_settle(v_msg, v_status, 'test', null, case when v_status = 'failed' then '401' end);
    end loop;
    if v_status = 'failed' then
      assert public.sms_codes_counted(public.booking_hash(public.crm_phone(v_phone, (select country from public.shops where slug = 'potraviny-centrum'))), null) = 0, 'failed ones do not count';
      assert public.sms_code_last_failed(public.booking_hash(public.crm_phone(v_phone, (select country from public.shops where slug = 'potraviny-centrum'))));
      v_code := public.sms_code_start('potraviny-centrum', 'order', v_phone, 'Zákazník 85', md5('t85-sms-4'),
                                      (select v::uuid from t85 where k = 'conv'), (select v from t85 where k = 'token'));
      assert v_code ? 'code', '3 failed + 1 → allowed';
      -- the new one waits (queued): it counts
      assert public.sms_codes_counted(public.booking_hash(public.crm_phone(v_phone, (select country from public.shops where slug = 'potraviny-centrum'))), null) = 1;
    else
      begin
        perform public.sms_code_start('potraviny-centrum', 'order', v_phone, 'Zákazník 85', md5('t85-sms-5'),
                                      (select v::uuid from t85 where k = 'conv'), (select v from t85 where k = 'token'));
        raise exception '3 sent + 1 allowed';
      exception when program_limit_exceeded then assert sqlerrm = 'too_many', sqlerrm; end;
    end if;
  end loop;
  -- 2 sent, then a failed one: the limit is not reached (2 count); the 3rd sent reaches it
  v_phone := '0907 885 803';
  for i in 1..2 loop
    v_code := public.sms_code_start('potraviny-centrum', 'order', v_phone, 'Zákazník 85', md5('t85-mix-' || i),
                                    (select v::uuid from t85 where k = 'conv'), (select v from t85 where k = 'token'));
    perform public.booking_sms_settle(public.sms_code_claim((v_code ->> 'id')::uuid, 'Kód 123456'), 'test', 'test', null, null);
  end loop;
  v_code := public.sms_code_start('potraviny-centrum', 'order', v_phone, 'Zákazník 85', md5('t85-mix-3'),
                                  (select v::uuid from t85 where k = 'conv'), (select v from t85 where k = 'token'));
  perform public.booking_sms_settle(public.sms_code_claim((v_code ->> 'id')::uuid, 'Kód 123456'), 'failed', 'test', null, '402');
  v_code := public.sms_code_start('potraviny-centrum', 'order', v_phone, 'Zákazník 85', md5('t85-mix-4'),
                                  (select v::uuid from t85 where k = 'conv'), (select v from t85 where k = 'token'));
  assert v_code ? 'code', 'the failed one did not count';
  -- the limit reached while the last attempt failed at the provider: sms_failed, not too_many
  perform public.booking_sms_settle(public.sms_code_claim((v_code ->> 'id')::uuid, 'Kód 123456'), 'test', 'test', null, null);
  -- (one transaction: every row has the same now(), so this one is made the latest)
  insert into public.sms_codes (shop_id, purpose, phone_hash, caller_hash, expires_at, message_id, created_at)
  select v_a, 'order', public.booking_hash(public.crm_phone(v_phone, (select country from public.shops where slug = 'potraviny-centrum'))), md5('t85-mix-x'), now() + interval '10 minutes', m.id,
         now() + interval '1 second'
  from public.shop_outgoing_messages m where m.shop_id = v_a and m.status = 'failed' order by m.created_at desc limit 1;
  begin
    perform public.sms_code_start('potraviny-centrum', 'order', v_phone, 'Zákazník 85', md5('t85-mix-5'),
                                  (select v::uuid from t85 where k = 'conv'), (select v from t85 where k = 'token'));
    raise exception 'a 4th counted code allowed';
  exception when program_limit_exceeded then assert sqlerrm = 'sms_failed', sqlerrm; end;
  -- the caller's limit (10 an hour) counts the same way
  assert public.sms_codes_counted(null, md5('t85-sms-failed1')) = 0 and public.sms_codes_counted(null, md5('t85-sms-sent1')) = 1;
  -- the courier login: the same rule (failed courier codes do not count)
  v_phone := '0907 885 804';
  for i in 1..3 loop
    insert into public.sms_codes (shop_id, purpose, phone_hash, caller_hash, expires_at, message_id)
    values (v_a, 'courier', public.booking_hash(public.crm_phone(v_phone, (select country from public.shops where slug = 'potraviny-centrum'))), md5('t85-cr-' || i), now() + interval '10 minutes',
            (select m.id from public.shop_outgoing_messages m where m.shop_id = v_a and m.status = 'failed' order by m.created_at desc limit 1));
  end loop;
  assert public.food_courier_code_start('potraviny-centrum', v_phone, md5('t85-cr-4')) ? 'id', '3 failed courier codes + 1 → allowed';
  assert not has_function_privilege('anon', 'public.sms_codes_counted(text, text)', 'execute')
     and not has_function_privilege('authenticated', 'public.sms_code_last_failed(text)', 'execute');
end $$;
reset role;

-- tidy up: the note, ordering off, the day's hours, the subscription
set role service_role;
do $$
declare
  v_a uuid := (select v::uuid from t85 where k = 'shop');
begin
  update public.food_settings set enabled = false, pay_note = null where shop_id = v_a;
  delete from public.content_translations where shop_id = v_a and kind = 'food_pay_note';
  delete from public.shop_special_hours where shop_id = v_a and date = (select v::date from t85 where k = 'day');
  delete from public.subscriptions where shop_id = v_a;
  insert into public.subscriptions
  select * from jsonb_populate_record(null::public.subscriptions, (select v::jsonb from t85 where k = 'sub'))
  where (select v from t85 where k = 'sub') is not null;
  assert public.shop_has_plan(v_a) = (select v::boolean from t85 where k = 'had_plan');
end $$;
reset role;
reset request.jwt.claim.sub;
drop table t85;

\echo '--- update 86: a restaurant''s stock — untracked dishes are not stock (a sale and a food order store no movement for them, manual movements and counts refused, "Sledovať zásobu" on starts at 0 once), a food shop''s stock never goes stale (public: current at any age; the owner: never_expires; no reminder), goods shops unchanged'
create temporary table t86 (k text primary key, v text);
grant all on t86 to public;

set role service_role;
do $$
declare
  v_a uuid := (select id from public.shops where slug = 'potraviny-centrum');
  v_tz text := (select coalesce(timezone, 'UTC') from public.shops where id = v_a);
begin
  insert into t86 values ('shop', v_a::text), ('had_plan', public.shop_has_plan(v_a)::text),
    ('sub', (select to_jsonb(x) from public.subscriptions x where x.shop_id = v_a)::text),
    ('day', ((now() at time zone v_tz)::date)::text),
    ('kind', (select kind from public.shops where id = v_a)),
    ('food', (select to_jsonb(f) from public.food_settings f where f.shop_id = v_a)::text);
  insert into public.subscriptions (shop_id, status, plan, current_period_end, stripe_subscription_id)
  values (v_a, 'active', 'pro', now() + interval '30 days', 'sub_test_86')
  on conflict (shop_id) do update set status = 'active', current_period_end = now() + interval '30 days';
  insert into public.shop_special_hours (shop_id, date, closed, ranges)
  values (v_a, (now() at time zone v_tz)::date, false, '[["00:00","23:59"]]')
  on conflict (shop_id, date) do update set closed = false, ranges = excluded.ranges;
  assert public.stock_source_of(v_a) = 'sklad', 'the test shop sells from Sklad';
  assert not has_function_privilege('authenticated', 'public.sklad_tracks_stock(uuid)', 'execute')
     and not has_function_privilege('anon', 'public.sklad_tracks_stock(uuid)', 'execute'), 'the rule is read inside the database';
end $$;
reset role;

-- the owner: a restaurant with an untracked soup, a tracked juice, and a dessert to switch on and off
set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000a';
do $$
declare
  v_a uuid := (select v::uuid from t86 where k = 'shop');
  v_soup uuid; v_juice uuid; v_cake uuid; v_count uuid;
  vj jsonb;
begin
  perform public.owner_set_shop_kind(v_a, 'food');
  perform public.owner_food_save_settings(v_a, '{"enabled": true, "pickup_on": true, "payments_on": true, "pay_cash": true, "deduct_on_delivery": true}');
  v_soup := public.owner_menu_save_item(v_a, null, '{"name": "Polievka 86", "price": "2.80"}');
  v_juice := public.owner_menu_save_item(v_a, null, '{"name": "Džús 86", "price": "1.90", "track_stock": true}');
  v_cake := public.owner_menu_save_item(v_a, null, '{"name": "Tiramisu 86", "price": "3.50"}');
  insert into t86 values ('soup', v_soup::text), ('juice', v_juice::text), ('cake', v_cake::text);
  perform public.owner_sklad_move(v_a, gen_random_uuid(), v_juice, 'receipt', 10);

  -- manual movements and counts of an untracked dish are refused; nothing stored
  begin perform public.owner_sklad_move(v_a, gen_random_uuid(), v_soup, 'writeoff', 1, null, null, null, 'Rozliate'); raise exception 'an Odpis of an untracked dish';
  exception when invalid_parameter_value then if sqlerrm <> 'untracked_dish' then raise; end if; end;
  begin perform public.owner_sklad_move(v_a, gen_random_uuid(), v_soup, 'receipt', 5); raise exception 'a Príjem of an untracked dish';
  exception when invalid_parameter_value then if sqlerrm <> 'untracked_dish' then raise; end if; end;
  begin perform public.owner_sklad_move(v_a, gen_random_uuid(), v_soup, 'correction', 2, null, null, null, 'Oprava'); raise exception 'an Oprava of an untracked dish';
  exception when invalid_parameter_value then if sqlerrm <> 'untracked_dish' then raise; end if; end;
  v_count := gen_random_uuid();
  perform public.owner_sklad_count_start(v_a, v_count, 'Inventúra 86', null, null, false);
  begin perform public.owner_sklad_count_set(v_a, v_count, v_soup, 'Pult', 3); raise exception 'counting an untracked dish';
  exception when invalid_parameter_value then if sqlerrm <> 'untracked_dish' then raise; end if; end;
  perform public.owner_sklad_count_cancel(v_a, v_count);

  -- the lists: tracked / sold out today, an untracked dish is never low or out
  vj := public.owner_sklad_products(v_a, 'Polievka 86');
  assert jsonb_array_length(vj -> 'rows') = 1 and not (vj -> 'rows' -> 0 ->> 'tracked')::boolean
     and not (vj -> 'rows' -> 0 ->> 'is_out')::boolean and not (vj -> 'rows' -> 0 ->> 'sold_out_today')::boolean, vj::text;
  perform public.owner_menu_set_sold_out(v_a, v_soup, true);
  assert (public.owner_sklad_products(v_a, 'Polievka 86') -> 'rows' -> 0 ->> 'sold_out_today')::boolean, 'Vypredané dnes';
  perform public.owner_menu_set_sold_out(v_a, v_soup, false);
  vj := public.owner_sklad_products(v_a, 'Džús 86');
  assert (vj -> 'rows' -> 0 ->> 'tracked')::boolean and (vj -> 'rows' -> 0 ->> 'total')::numeric = 10, vj::text;
  vj := public.owner_sklad_product(v_a, v_soup);
  assert not (vj ->> 'tracked')::boolean and (vj ->> 'menu_item')::boolean and (vj ->> 'never_expires')::boolean, vj::text;

  -- a sale: the sale and its lines are stored, the untracked soup gets no movement, the juice does
  vj := public.owner_sklad_sell(v_a, gen_random_uuid(), jsonb_build_array(jsonb_build_object('item_id', v_soup, 'qty', 2),
                                                                          jsonb_build_object('item_id', v_juice, 'qty', 1)), 'cash');
  insert into t86 values ('sale', vj ->> 'id');
end $$;
reset role;

set role service_role;
do $$
declare
  v_a uuid := (select v::uuid from t86 where k = 'shop');
  v_soup uuid := (select v::uuid from t86 where k = 'soup');
  v_juice uuid := (select v::uuid from t86 where k = 'juice');
  v_sale public.sklad_sales;
begin
  select * into v_sale from public.sklad_sales where id = (select v::uuid from t86 where k = 'sale');
  assert v_sale.id is not null and v_sale.status = 'done' and jsonb_array_length(v_sale.lines) = 2 and v_sale.total = 7.50, to_jsonb(v_sale)::text;
  assert not exists (select 1 from public.sklad_movements where shop_item_id = v_soup), 'no movement for the untracked soup';
  assert (select count(*) from public.sklad_movements where sale_id = v_sale.id and shop_item_id = v_juice and qty = -1) = 1;
  assert (select qty from public.sklad_stock_total where shop_item_id = v_juice) = 9;
  -- a direct insert is skipped too (the one guard)
  insert into public.sklad_movements (id, shop_id, shop_item_id, location_id, kind, qty, ref)
  values (gen_random_uuid(), v_a, v_soup, public.sklad_default_location(v_a, false), 'sale', -1, 'Test 86');
  assert not exists (select 1 from public.sklad_movements where shop_item_id = v_soup), 'the guard skipped it';
  -- an untracked dish is not stock: no inventory row; the juice is
  assert not exists (select 1 from public.inventory where shop_item_id = v_soup)
     and exists (select 1 from public.inventory where shop_item_id = v_juice and quantity = 9);
  assert not exists (select 1 from public.sklad_count_scope((select c from public.sklad_counts c where c.shop_id = v_a and c.name = 'Inventúra 86')) x
                     where x.shop_item_id = v_soup), 'no untracked dish in a count';
end $$;
reset role;

-- a food order with "Odpísať zo skladu": only the tracked line moves; a reopen returns only what was taken
set role service_role;
do $$
declare
  v_a uuid := (select v::uuid from t86 where k = 'shop');
  v_open jsonb := public.assistant_open((select v::uuid from t86 where k = 'shop'), 'sk', repeat('8', 32));
  v_code jsonb;
  vj jsonb;
begin
  v_code := public.sms_code_start('potraviny-centrum', 'order', '0907 886 001', 'Zákazník 86', md5('t86-1'),
                                  (v_open ->> 'id')::uuid, v_open ->> 'token');
  vj := public.food_order_create((v_code ->> 'id')::uuid, v_code ->> 'code', gen_random_uuid(),
          jsonb_build_array(jsonb_build_object('item_id', (select v from t86 where k = 'soup'), 'qty', 2),
                            jsonb_build_object('item_id', (select v from t86 where k = 'juice'), 'qty', 3)),
          'pickup', null, null, null, null, null, (v_open ->> 'id')::uuid, v_open ->> 'token', 'sk');
  assert (vj ->> 'ok')::boolean, vj::text;
  insert into t86 values ('order', vj -> 'order' ->> 'id');
end $$;
reset role;

set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000a';
do $$
declare
  v_a uuid := (select v::uuid from t86 where k = 'shop');
  v_order uuid := (select v::uuid from t86 where k = 'order');
  vj jsonb;
begin
  vj := public.owner_food_order_finish(v_a, v_order, gen_random_uuid(), 'cash', 10000);
  assert vj ->> 'status' = 'picked_up', vj::text;
  vj := public.owner_food_order_reopen(v_a, v_order, gen_random_uuid());
  assert (vj ->> 'stock_returned')::boolean, vj::text;
end $$;
reset role;

set role service_role;
do $$
declare
  v_soup uuid := (select v::uuid from t86 where k = 'soup');
  v_juice uuid := (select v::uuid from t86 where k = 'juice');
  v_order uuid := (select v::uuid from t86 where k = 'order');
begin
  assert not exists (select 1 from public.sklad_movements where shop_item_id = v_soup), 'the soup never moved';
  assert (select count(*) from public.sklad_movements where shop_item_id = v_juice and kind = 'sale' and qty = -3
          and id in (select md5(v_order::text || ':' || l.id::text)::uuid from public.food_order_lines l where l.order_id = v_order)) = 1,
         'the juice was taken once, by its md5(order : line) id';
  assert (select count(*) from public.sklad_movements where shop_item_id = v_juice and kind = 'correction' and qty = 3
          and reason like 'Vrátené – objednávka č.%') = 1, 'and returned once';
  assert (select qty from public.sklad_stock_total where shop_item_id = v_juice) = 9, 'back to 9';
end $$;
reset role;

-- "Sledovať zásobu" on: the dessert starts at 0 (an old negative cleared), once
set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000a';
do $$
declare
  v_a uuid := (select v::uuid from t86 where k = 'shop');
  v_cake uuid := (select v::uuid from t86 where k = 'cake');
begin
  perform public.owner_menu_save_item(v_a, v_cake, '{"track_stock": true}');
  perform public.owner_sklad_sell(v_a, gen_random_uuid(), jsonb_build_array(jsonb_build_object('item_id', v_cake, 'qty', 2)), 'cash');
  perform public.owner_menu_save_item(v_a, v_cake, '{"track_stock": false}');
  perform public.owner_sklad_sell(v_a, gen_random_uuid(), jsonb_build_array(jsonb_build_object('item_id', v_cake, 'qty', 1)), 'cash');
  set local role service_role;
  assert (select qty from public.sklad_stock_total where shop_item_id = v_cake) = -2, 'tracked: -2; untracked: no movement';
  assert not exists (select 1 from public.sklad_movements where shop_item_id = v_cake and kind = 'correction'), 'switched on at 0: no Oprava';
  set local role authenticated;
  perform public.owner_menu_save_item(v_a, v_cake, '{"track_stock": true}');
  perform public.owner_menu_save_item(v_a, v_cake, '{"track_stock": true}');
  set local role service_role;
  assert (select qty from public.sklad_stock_total where shop_item_id = v_cake) = 0, 'starts at 0';
  assert (select count(*) from public.sklad_movements where shop_item_id = v_cake and kind = 'correction'
          and reason = 'Začiatok sledovania zásoby' and qty = 2) = 1, 'one Oprava';
  assert exists (select 1 from public.inventory where shop_item_id = v_cake and quantity = 0), 'tracked: on the public side, sold out';
end $$;
reset role;

-- Jazyky a inventár → Tovar and Prehľad: "V menu", never_expires, no countdown
set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000a';
do $$
declare
  v_a uuid := (select v::uuid from t86 where k = 'shop');
  v_soup uuid := (select v::uuid from t86 where k = 'soup');
  vj jsonb;
  r record;
begin
  select * into r from public.owner_items(v_a, 'Polievka 86') x where x.item_id = v_soup;
  assert r.availability = 'in_menu', r::text;
  assert not exists (select 1 from public.owner_items(v_a, 'Polievka 86', 50, 0, 'sold_out') x where x.item_id = v_soup)
     and not exists (select 1 from public.owner_items(v_a, 'Polievka 86', 50, 0, 'in_stock') x where x.item_id = v_soup), 'neither in stock nor sold out';
  assert (select freshness_state from public.my_shops() where id = v_a) = 'never_expires';
  vj := public.owner_sklad_overview(v_a);
  assert (vj ->> 'never_expires')::boolean and not (vj ->> 'needs_check')::boolean and vj -> 'fresh_until' = 'null'::jsonb
     and vj ->> 'freshness_state' = 'never_expires', vj::text;
end $$;
reset role;

-- a food shop's stock never goes stale by time; a goods shop hides after 24 h; the kind decides at once
set role service_role;
do $$
declare
  v_a uuid := (select v::uuid from t86 where k = 'shop');
  v_juice uuid := (select v::uuid from t86 where k = 'juice');
begin
  update public.sync_sources set latest_file_time = now() - interval '3 days' where shop_id = v_a;
end $$;
reset role;
set role anon;
do $$
declare
  v_juice uuid := (select v::uuid from t86 where k = 'juice');
begin
  assert (select availability = 'in_stock_count' and quantity = 9 and freshness_state = 'current'
          from public.public_stock where item_id = v_juice), 'a food shop 3 days later: still shown with its quantity';
  assert (select freshness_state from public.public_shops where slug = 'potraviny-centrum') = 'current';
  assert exists (select 1 from public.shop_item_search('potraviny-centrum', 'Džús 86', 10, 0) x
                 where x.item_id = v_juice and x.is_available), 'the shop''s search too';
end $$;
reset role;
set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000a';
do $$ begin perform public.owner_set_shop_kind((select v::uuid from t86 where k = 'shop'), 'goods'); end $$;
reset role;
set role anon;
do $$
declare
  v_juice uuid := (select v::uuid from t86 where k = 'juice');
begin
  assert (select availability is null and quantity is null and freshness_state = 'stale'
          from public.public_stock where item_id = v_juice), 'food → goods: the 24 h rule at once';
  assert (select freshness_state from public.public_shops where slug = 'potraviny-centrum') = 'stale';
end $$;
reset role;
set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000a';
do $$
declare
  v_a uuid := (select v::uuid from t86 where k = 'shop');
begin
  assert (select freshness_state from public.my_shops() where id = v_a) = 'stale', 'goods: the owner sees stale again';
  assert (public.owner_sklad_overview(v_a) ->> 'fresh_until') is not null, 'goods: the countdown is back';
  perform public.owner_set_shop_kind(v_a, 'food');
end $$;
reset role;
set role anon;
do $$
begin
  assert (select availability = 'in_stock_count' from public.public_stock where item_id = (select v::uuid from t86 where k = 'juice')),
         'goods → food: shown again at once';
end $$;
reset role;

-- the daily reminder never picks a food shop (a goods shop with no movement today would get it)
do $$
declare
  v_a uuid := (select v::uuid from t86 where k = 'shop');
begin
  begin
    alter table public.sklad_movements disable trigger sklad_movements_frozen;
    update public.sklad_movements set created_at = created_at - interval '3 days' where shop_id = v_a;
    update public.sklad_settings set reminder_on = true, reminder_time = '00:00', confirmed_at = now() - interval '2 days',
                                     reminded_on = null where shop_id = v_a;
    update public.shops set kind = 'food' where id = v_a;
    assert not exists (select 1 from public.sklad_reminders_due() d where d.shop_id = v_a), 'a food shop: no reminder';
    update public.shops set kind = 'goods' where id = v_a;
    assert exists (select 1 from public.sklad_reminders_due() d where d.shop_id = v_a), 'a goods shop: the reminder as before';
    raise exception 'undo 86';
  exception when raise_exception then
    if sqlerrm <> 'undo 86' then raise; end if;
  end;
  assert exists (select 1 from public.sklad_movements where shop_id = v_a and created_at > now() - interval '1 hour'), 'undone';
end $$;

-- tidy up: the kind, food ordering, the day's hours, the subscription
set role service_role;
do $$
declare
  v_a uuid := (select v::uuid from t86 where k = 'shop');
begin
  update public.shops set kind = (select v from t86 where k = 'kind') where id = v_a;
  update public.food_settings f set enabled = coalesce((x ->> 'enabled')::boolean, false),
         deduct_on_delivery = coalesce((x ->> 'deduct_on_delivery')::boolean, false)
  from (select (select v::jsonb from t86 where k = 'food') x) y where f.shop_id = v_a;
  update public.sync_sources set latest_file_time = now() where shop_id = v_a;
  delete from public.shop_special_hours where shop_id = v_a and date = (select v::date from t86 where k = 'day');
  delete from public.subscriptions where shop_id = v_a;
  insert into public.subscriptions
  select * from jsonb_populate_record(null::public.subscriptions, (select v::jsonb from t86 where k = 'sub'))
  where (select v from t86 where k = 'sub') is not null;
  assert public.shop_has_plan(v_a) = (select v::boolean from t86 where k = 'had_plan');
end $$;
reset role;
reset request.jwt.claim.sub;
drop table t86;

\echo '--- update 87: Donáška without zones (fee 0, no minimum), the zone the customer picks (required with zones, the shop''s own, fitting the address: town / postcode / kilometres; never another zone''s fee), the customer''s labels and order of zones, the order keeps the zone''s label'
create temporary table t87 (k text primary key, v text);
grant all on t87 to public;
set role service_role;
do $$
declare
  v_a uuid := (select id from public.shops where slug = 'potraviny-centrum');
  v_tz text := (select coalesce(timezone, 'UTC') from public.shops where id = v_a);
  v_open jsonb;
  v_pizza uuid := (select si.id from public.sklad_items i join public.shop_items si on si.id = i.shop_item_id
                   where i.shop_id = v_a and si.name = 'Margherita 32 cm');
begin
  insert into t87 values ('shop', v_a::text), ('had_plan', public.shop_has_plan(v_a)::text),
    ('sub', (select to_jsonb(x) from public.subscriptions x where x.shop_id = v_a)::text),
    ('day', ((now() at time zone v_tz)::date)::text),
    ('food', (select to_jsonb(f) from public.food_settings f where f.shop_id = v_a)::text),
    ('zones', (select coalesce(jsonb_agg(to_jsonb(z)), '[]'::jsonb) from public.food_zones z where z.shop_id = v_a)::text);
  insert into public.subscriptions (shop_id, status, plan, current_period_end, stripe_subscription_id)
  values (v_a, 'active', 'pro', now() + interval '30 days', 'sub_test_87')
  on conflict (shop_id) do update set status = 'active', current_period_end = now() + interval '30 days';
  insert into public.shop_special_hours (shop_id, date, closed, ranges)
  values (v_a, (now() at time zone v_tz)::date, false, '[["00:00","23:59"]]')
  on conflict (shop_id, date) do update set closed = false, ranges = excluded.ranges;
  insert into public.sklad_movements (id, shop_id, shop_item_id, location_id, kind, qty, ref, client_at)
  values (gen_random_uuid(), v_a, v_pizza, public.sklad_default_location(v_a, false), 'receipt', 20, 'Test 87', now());
  perform public.sklad_apply(v_a, array[v_pizza]);
  update public.food_settings set enabled = true, paused = false, pickup_on = true, delivery_on = true, last_order_minutes = 0
  where shop_id = v_a;
  -- the test starts without zones (the old ones come back at the end)
  delete from public.food_zones where shop_id = v_a;
  v_open := public.assistant_open(v_a, 'sk', repeat('7', 32));
  insert into t87 values ('pizza', v_pizza::text), ('conv', v_open ->> 'id'), ('token', v_open ->> 'token');

  -- the pure rules (the same cases as foodRules_test: townOf / townFits / postcodeFits)
  assert public.food_town_of('Okružná 14, 071 01 Michalovce') = 'Michalovce';
  assert public.food_town_of('Hlavná 5, Veľké Kapušany 079 01') = 'Veľké Kapušany';
  assert public.food_town_of('Váci utca 5, 1051 Budapest') = 'Budapest';
  assert public.food_town_of('Košice') = 'Košice' and public.food_town_of('  ') is null and public.food_town_of('Ulica 5, 04001') is null;
  assert public.food_town_fits('Hlavná 5, Veľké Kapušany', 'velke kapusany');
  assert public.food_town_fits('Hlavná 5 Veľké Kapušany 079 01', 'Veľké Kapušany'), 'no comma: the address ends with the town';
  assert not public.food_town_fits('Kapušanská 5, Michalovce', 'Kapušany');
  assert not public.food_town_fits('Hlavná 5, Pavlovce', 'Michalovce');
  assert not public.food_town_fits('Hlavná 5, 07901 Kapušany', '07901'), 'a postcode is not a town';
  assert public.food_postcode_fits('Hlavná 5, 071 01 Michalovce', '07101') and public.food_postcode_fits('Hlavná 5, 07102 X', '071 01; 071 02');
  assert not public.food_postcode_fits('Hlavná 5, 04001 Košice', '071 01');
end $$;
reset role;

-- no zones: Donáška with its switch alone, fee 0, no minimum, no zone question; the switch off = refused; pickup as before
set role anon;
do $$
declare
  v_lines jsonb := jsonb_build_array(jsonb_build_object('item_id', (select v from t87 where k = 'pizza'), 'qty', 1));
  vj jsonb;
begin
  vj := public.food_state('potraviny-centrum');
  assert (vj ->> 'delivery')::boolean and (vj ->> 'zones_count')::int = 0 and jsonb_array_length(vj -> 'zone_list') = 0, vj::text;
  vj := public.food_quote('potraviny-centrum', v_lines, 'delivery', 'Hocikde 1, Ďaleko', null, null, null);
  assert (vj ->> 'orderable')::boolean and (vj ->> 'delivery_cents')::int = 0 and (vj ->> 'minimum_cents')::int = 0
     and vj -> 'zone' = 'null'::jsonb and (vj ->> 'zones_count')::int = 0, vj::text;
  -- a caller from before (no zone sent): the same
  vj := public.food_quote('potraviny-centrum', v_lines, 'delivery', 'Hocikde 1, Ďaleko');
  assert (vj ->> 'orderable')::boolean and (vj ->> 'delivery_cents')::int = 0, vj::text;
  vj := public.food_quote('potraviny-centrum', v_lines, 'delivery', null, null, null, null);
  assert vj ->> 'problem' = 'no_address', vj::text;
  vj := public.food_quote('potraviny-centrum', v_lines, 'pickup', null, null, null, null);
  assert (vj ->> 'orderable')::boolean and (vj ->> 'delivery_cents')::int = 0 and (vj ->> 'total_cents')::int = 790, vj::text;
end $$;
reset role;
set role service_role;
update public.food_settings set delivery_on = false where shop_id = (select v::uuid from t87 where k = 'shop');
reset role;
set role anon;
do $$
declare
  vj jsonb;
begin
  assert not (public.food_state('potraviny-centrum') ->> 'delivery')::boolean, 'the switch off: no Donáška';
  vj := public.food_quote('potraviny-centrum', jsonb_build_array(jsonb_build_object('item_id', (select v from t87 where k = 'pizza'), 'qty', 1)),
                          'delivery', 'Hocikde 1, Ďaleko', null, null, null);
  assert vj ->> 'problem' = 'kind_off', vj::text;
end $$;
reset role;
set role service_role;
update public.food_settings set delivery_on = true where shop_id = (select v::uuid from t87 where k = 'shop');
