\echo '--- update 89: crm settings saved key by key — the booking SMS switches (SMS a Telegram) never touch the alert e-mail (Rezervácie) and back; members only'
do $$
declare
  v_shop uuid;
begin
  insert into public.shops (slug, name, address, city, country, timezone, location, phone, opening_hours, is_active)
  select 'crm-keys', 'CRM Keys', address, city, country, timezone, location, phone, opening_hours, true
  from public.shops where slug = 'potraviny-centrum'
  returning id into v_shop;
  insert into public.shop_members (shop_id, user_id) values (v_shop, '00000000-0000-0000-0000-00000000000a');
  insert into public.subscriptions (shop_id, status, plan, current_period_end, stripe_subscription_id)
  values (v_shop, 'active', 'pro', now() + interval '20 days', 'sub_test_crm_keys');
end $$;
set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000a';
do $$
declare
  v_shop uuid := (select id from public.shops where slug = 'crm-keys');
  v_before timestamptz;
begin
  -- the alert e-mail alone (Rezervácie → Nastavenia): the defaults stay
  perform public.owner_save_crm_settings(v_shop, '{"alert_email": "Alerts@Example.invalid"}'::jsonb);
  assert (select alert_email = 'alerts@example.invalid' and not reminder_on and reminder_offset = 'day_before_18'
                 and notify_on_owner_change from public.crm_settings where shop_id = v_shop), 'e-mail alone';
  -- the SMS switches alone (SMS a Telegram): the e-mail stays
  perform public.owner_save_crm_settings(v_shop,
    '{"reminder_on": true, "reminder_offset": "2h", "notify_on_owner_change": false}'::jsonb);
  assert (select alert_email = 'alerts@example.invalid' and reminder_on and reminder_offset = '2h'
                 and not notify_on_owner_change from public.crm_settings where shop_id = v_shop), 'switches alone';
  -- the e-mail cleared alone: the switches stay
  perform public.owner_save_crm_settings(v_shop, '{"alert_email": ""}'::jsonb);
  assert (select alert_email is null and reminder_on and reminder_offset = '2h' and not notify_on_owner_change
          from public.crm_settings where shop_id = v_shop), 'e-mail cleared alone';
  -- unknown keys and an empty object change nothing (and log nothing)
  select updated_at into v_before from public.crm_settings where shop_id = v_shop;
  perform public.owner_save_crm_settings(v_shop, '{"something": 1}'::jsonb);
  assert (select updated_at = v_before from public.crm_settings where shop_id = v_shop), 'nothing given';
  -- the checks as before
  begin perform public.owner_save_crm_settings(v_shop, '{"reminder_offset": "3h"}'::jsonb); raise exception 'offset';
  exception when invalid_parameter_value then null; end;
  begin perform public.owner_save_crm_settings(v_shop, '{"alert_email": "nope"}'::jsonb); raise exception 'email';
  exception when invalid_parameter_value then null; end;
  begin perform public.owner_save_crm_settings(v_shop, '{"reminder_on": "yes"}'::jsonb); raise exception 'not a boolean';
  exception when invalid_parameter_value then null; end;
  assert (select count(*) from public.shop_activity where shop_id = v_shop and action = 'crm_settings_saved') = 3;
end $$;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000b';
do $$
begin
  perform public.owner_save_crm_settings((select id from public.shops where slug = 'crm-keys'), '{"reminder_on": true}'::jsonb);
  raise exception 'another owner saved';
exception when insufficient_privilege then null;
end $$;
reset role;
reset request.jwt.claim.sub;
set role anon;
do $$
begin
  perform public.owner_save_crm_settings((select id from public.shops where slug = 'crm-keys'), '{"reminder_on": true}'::jsonb);
  raise exception 'a visitor saved';
exception when insufficient_privilege then null;
end $$;
reset role;
delete from public.shops where slug = 'crm-keys';

create temporary table inbox_test (k text primary key, v uuid);
grant all on inbox_test to public;
\echo '--- update 90: the CRM inbox — masked phone, Čaká / Rezerv. filters, last message, drafts (save, get, clear, empty clears, own only), no grants'
do $$
declare
  v_shop uuid;
  v_other uuid;
  v_k uuid;
  v_c1 uuid;
  v_c2 uuid;
  v_c3 uuid;
  v_cx uuid;
begin
  assert public.crm_phone_masked('+421905123418', 'SK') = '+421 905 ··· 418', public.crm_phone_masked('+421905123418', 'SK');
  assert public.crm_phone_masked('+36301234567', 'HU') = '+36 301 ··· 567', public.crm_phone_masked('+36301234567', 'HU');
  assert public.crm_phone_masked('+421905123418', 'HU') = '+421 905 ··· 418', 'another country: the first three digits';
  assert public.crm_phone_masked(null, 'SK') is null and public.crm_phone_masked('12', 'SK') is null;

  insert into public.shops (slug, name, address, city, country, timezone, location, phone, opening_hours, is_active)
  select 'crm-inbox', 'CRM Inbox', address, city, 'SK', timezone, location, phone, opening_hours, true
  from public.shops where slug = 'potraviny-centrum'
  returning id into v_shop;
  insert into public.shop_members (shop_id, user_id) values (v_shop, '00000000-0000-0000-0000-00000000000a');
  insert into public.shops (slug, name, address, city, country, timezone, location, phone, opening_hours, is_active)
  select 'crm-inbox-b', 'CRM Inbox B', address, city, 'SK', timezone, location, phone, opening_hours, true
  from public.shops where slug = 'potraviny-centrum'
  returning id into v_other;
  insert into public.shop_members (shop_id, user_id) values (v_other, '00000000-0000-0000-0000-00000000000b');

  insert into public.shop_contacts (shop_id, name, phone, phone_verified_at, source)
  values (v_shop, 'Ján Novák', '+421905123418', now(), 'chat') returning id into v_k;
  -- 1: a callback waits; 2: unanswered but the shop already replied; 3: a booking made in it
  insert into public.assistant_conversations (shop_id, token_hash, message_count, contact_id, callback_at, unanswered, last_message_at)
  values (v_shop, 'x', 2, v_k, now() - interval '5 minutes', true, now() - interval '5 minutes') returning id into v_c1;
  insert into public.assistant_conversations (shop_id, token_hash, message_count, unanswered, last_message_at)
  values (v_shop, 'x', 3, true, now() - interval '1 hour') returning id into v_c2;
  insert into public.assistant_conversations (shop_id, token_hash, message_count, contact_id, last_message_at)
  values (v_shop, 'x', 2, v_k, now() - interval '2 hours') returning id into v_c3;
  insert into public.assistant_conversations (shop_id, token_hash, message_count) values (v_other, 'x', 2) returning id into v_cx;
  insert into public.assistant_messages (conversation_id, shop_id, role, body, body_owner, lang)
  values (v_c1, v_shop, 'shopper', 'Viete namiešať RAL 7016?', null, 'sk'),
         (v_c1, v_shop, 'assistant', 'To   neviem   potvrdiť.', null, 'sk'),
         (v_c2, v_shop, 'shopper', 'Van fehér festék?', 'Máte bielu farbu?', 'hu'),
         (v_c2, v_shop, 'owner', 'Áno, máme.', null, 'sk');
  insert into public.shop_bookings (shop_id, contact_id, conversation_id, starts_at, ends_at, status, service_name, name, phone,
                                    consent_at, consent_version, token_hash, confirmed_at)
  values (v_shop, v_k, v_c3, now() + interval '2 days', now() + interval '2 days 30 minutes', 'confirmed', 'Miešanie', 'Ján',
          '+421905123418', now(), 'v', 'x', now());
  insert into inbox_test values ('c1', v_c1), ('c2', v_c2), ('c3', v_c3), ('cx', v_cx), ('shop', v_shop), ('other', v_other);
end $$;

set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000a';
do $$
declare
  v_shop uuid := (select v from inbox_test where k = 'shop');
  v_c1 uuid := (select v from inbox_test where k = 'c1');
  v_c2 uuid := (select v from inbox_test where k = 'c2');
  v_c3 uuid := (select v from inbox_test where k = 'c3');
  v_cx uuid := (select v from inbox_test where k = 'cx');
  v_counts jsonb;
  v_head jsonb;
  v_at timestamptz;
  r record;
begin
  -- the list: newest activity first, the last message (spaces folded, the SK version), the masked phone, waiting
  assert (select array_agg(id order by ord) from (select id, row_number() over () as ord
          from public.owner_conversations_inbox(v_shop)) x) = array[v_c1, v_c2, v_c3], 'newest first';
  select * into r from public.owner_conversations_inbox(v_shop) where id = v_c1;
  assert r.waiting and r.last_text = 'To neviem potvrdiť.' and r.last_role = 'assistant', r.last_text;
  assert r.contact_name = 'Ján Novák' and r.phone_masked = '+421 905 ··· 418' and r.phone_verified and r.contact_conversations = 2;
  assert r.next_booking_at is not null, 'the contact''s next booking';
  select * into r from public.owner_conversations_inbox(v_shop) where id = v_c2;
  assert not r.waiting, 'the shop replied: not waiting';
  assert r.last_text = 'Áno, máme.' and r.contact_name is null and r.phone_masked is null;
  -- the filters
  assert (select array_agg(id) from public.owner_conversations_inbox(v_shop, p_filter => 'waiting')) = array[v_c1];
  assert (select array_agg(id) from public.owner_conversations_inbox(v_shop, p_filter => 'booked')) = array[v_c3];
  v_counts := public.owner_conversations_inbox_counts(v_shop);
  assert (v_counts ->> 'all')::int = 3 and (v_counts ->> 'waiting')::int = 1 and (v_counts ->> 'booked')::int = 1, v_counts::text;
  -- the head: events only from its own data
  v_head := public.owner_conversation_head(v_c1);
  assert v_head ->> 'phone_masked' = '+421 905 ··· 418' and (v_head ->> 'waiting')::boolean and (v_head ->> 'has_phone')::boolean;
  assert jsonb_array_length(v_head -> 'events') = 1 and v_head -> 'events' -> 0 ->> 'kind' = 'contact_left';
  assert public.owner_conversation_head(v_c3) -> 'events' -> 0 ->> 'kind' = 'booking_confirmed';

  -- drafts: save, get, the row shows it, clear, an empty text clears
  v_at := public.owner_draft_save(v_c1, 'email', 'Predmet', 'Dobrý deň, RAL 7016 namiešame.');
  assert v_at is not null;
  assert public.owner_draft_get(v_c1) ->> 'channel' = 'email' and public.owner_draft_get(v_c1) ->> 'subject' = 'Predmet';
  assert (select draft_text from public.owner_conversations_inbox(v_shop) where id = v_c1) = 'Dobrý deň, RAL 7016 namiešame.';
  perform public.owner_draft_save(v_c1, 'sms', null, 'Druhá verzia');
  assert public.owner_draft_get(v_c1) ->> 'body' = 'Druhá verzia' and public.owner_draft_get(v_c1) ->> 'channel' = 'sms', 'one per conversation';
  v_at := public.owner_draft_save(v_c1, 'sms', '', '   ');
  assert v_at is null, 'empty: no time';
  assert public.owner_draft_get(v_c1) is null, 'empty clears';
  perform public.owner_draft_save(v_c2, 'sms', null, 'Koncept');
  perform public.owner_draft_clear(v_c2);
  assert public.owner_draft_get(v_c2) is null;
  perform public.owner_draft_save(v_c3, 'sms', null, 'Zostáva pre majiteľa a');
  -- another shop's conversation: refused
  begin perform public.owner_draft_save(v_cx, 'sms', null, 'x'); raise exception 'saved into another shop';
  exception when insufficient_privilege then null; end;
  begin perform public.owner_conversation_head(v_cx); raise exception 'read another shop''s head';
  exception when insufficient_privilege then null; end;
  assert not exists (select 1 from public.owner_conversations_inbox((select v from inbox_test where k = 'other')));
  -- no direct grants
  begin perform 1 from public.owner_conversation_drafts; raise exception 'read the drafts table';
  exception when insufficient_privilege then null; end;
  begin perform public.owner_draft_shop(v_c1); raise exception 'called the helper';
  exception when insufficient_privilege then null; end;
end $$;

-- another owner of the same shop never sees owner a's draft
reset role;
insert into public.shop_members (shop_id, user_id)
values ((select v from inbox_test where k = 'shop'), '00000000-0000-0000-0000-00000000000c');
set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000c';
do $$
declare
  v_c3 uuid := (select v from inbox_test where k = 'c3');
begin
  assert public.owner_draft_get(v_c3) is null, 'not my draft';
  assert (select draft_text from public.owner_conversations_inbox((select v from inbox_test where k = 'shop')) where id = v_c3) is null;
end $$;
reset role;
reset request.jwt.claim.sub;
set role anon;
do $$
begin
  perform public.owner_draft_get((select v from inbox_test where k = 'c1')); raise exception 'a visitor read a draft';
exception when insufficient_privilege then null;
end $$;
reset role;
delete from public.shops where slug in ('crm-inbox', 'crm-inbox-b');
delete from public.shop_members where user_id = '00000000-0000-0000-0000-00000000000c'
  and shop_id not in (select id from public.shops);
drop table inbox_test;

\echo '--- update 91: "Keď asistent nevie odpovedať" — ask_contact and alert_email_on default on, members only, only the keys given, alerts closed on a change, crm_alerts_due skips a shop with e-mail off'
create temporary table flags_test (k text primary key, v uuid);
grant all on flags_test to public;
do $$
declare
  v_shop uuid;
  v_other uuid;
  v_c uuid;
begin
  insert into public.shops (slug, name, address, city, country, timezone, location, phone, opening_hours, is_active)
  select 'flags-a', 'Flags A', address, city, 'SK', timezone, location, phone, opening_hours, true
  from public.shops where slug = 'potraviny-centrum'
  returning id into v_shop;
  insert into public.shop_members (shop_id, user_id) values (v_shop, '00000000-0000-0000-0000-00000000000a');
  insert into public.shops (slug, name, address, city, country, timezone, location, phone, opening_hours, is_active)
  select 'flags-b', 'Flags B', address, city, 'SK', timezone, location, phone, opening_hours, true
  from public.shops where slug = 'potraviny-centrum'
  returning id into v_other;
  insert into public.assistant_conversations (shop_id, token_hash, message_count) values (v_shop, 'x', 2) returning id into v_c;
  insert into public.shop_owner_alerts (shop_id, kind, conversation_id) values (v_shop, 'callback', v_c);
  insert into flags_test values ('shop', v_shop), ('other', v_other);
  -- before anything is saved: both on, the chat asks for a contact, the alert is due
  assert public.shop_asks_contact('flags-a');
  assert public.shop_asks_contact('no-such-shop'), 'an unknown shop reads the default';
  assert exists (select 1 from public.crm_alerts_due(100) where shop_id = v_shop), 'the alert is due';
end $$;

set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000a';
do $$
declare
  v_shop uuid := (select v from flags_test where k = 'shop');
  v_other uuid := (select v from flags_test where k = 'other');
  v jsonb;
begin
  assert public.owner_assistant_flags(v_shop) = '{"ask_contact": true, "alert_email_on": true}'::jsonb, public.owner_assistant_flags(v_shop)::text;
  v := public.owner_save_assistant_flags(v_shop, '{"ask_contact": false}');
  assert v = '{"ask_contact": false, "alert_email_on": true}'::jsonb, 'only the key given changes: ' || v::text;
  v := public.owner_save_assistant_flags(v_shop, '{"alert_email_on": false, "other": 1}');
  assert v = '{"ask_contact": false, "alert_email_on": false}'::jsonb, v::text;
  begin perform public.owner_save_assistant_flags(v_shop, '{"ask_contact": "no"}'); raise exception 'a text accepted';
  exception when invalid_parameter_value then null; end;
  -- another shop: refused, read and write
  begin perform public.owner_assistant_flags(v_other); raise exception 'read another shop';
  exception when insufficient_privilege then null; end;
  begin perform public.owner_save_assistant_flags(v_other, '{"ask_contact": false}'); raise exception 'wrote another shop';
  exception when insufficient_privilege then null; end;
  -- the table itself is not written by owners
  begin update public.shop_assistant_settings set ask_contact = true where shop_id = v_shop; raise exception 'wrote the table';
  exception when insufficient_privilege then null; end;
end $$;
reset role;
reset request.jwt.claim.sub;
do $$
declare
  v_shop uuid := (select v from flags_test where k = 'shop');
begin
  assert not public.shop_asks_contact('flags-a'), 'the chat no longer asks';
  -- switching the e-mail off closed the waiting alert; a new one while off is not due
  assert not exists (select 1 from public.shop_owner_alerts where shop_id = v_shop and resolved_at is null), 'closed on the change';
  insert into public.shop_owner_alerts (shop_id, kind) values (v_shop, 'callback');
  assert not exists (select 1 from public.crm_alerts_due(100) where shop_id = v_shop), 'no e-mail while it is off';
end $$;
set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000a';
select public.owner_save_assistant_flags((select v from flags_test where k = 'shop'), '{"alert_email_on": true}');
reset role;
reset request.jwt.claim.sub;
do $$
declare
  v_shop uuid := (select v from flags_test where k = 'shop');
begin
  -- the alert that waited while it was off is never e-mailed later; a new one is
  assert not exists (select 1 from public.crm_alerts_due(100) where shop_id = v_shop), 'old news stays unsent';
  insert into public.shop_owner_alerts (shop_id, kind) values (v_shop, 'callback');
  assert exists (select 1 from public.crm_alerts_due(100) where shop_id = v_shop), 'on again: the new alert is due';
end $$;
set role anon;
do $$
begin
  assert public.shop_asks_contact('flags-b'), 'a visitor reads the switch';
  begin perform public.owner_assistant_flags((select v from flags_test where k = 'shop')); raise exception 'a visitor read the flags';
  exception when insufficient_privilege then null; end;
  begin perform public.crm_alerts_due(1); raise exception 'a visitor read the alerts';
  exception when insufficient_privilege then null; end;
end $$;
reset role;
delete from public.shops where slug in ('flags-a', 'flags-b');
drop table flags_test;

\echo '--- update 92: "Štýl asistenta" — waiter only for food, a new restaurant defaults to waiter, existing ones stay plain, name ≤ 20 plain text, plan needed, kind change to goods falls back to plain'
create temporary table style_test (k text primary key, v uuid);
grant all on style_test to public;
do $$
declare
  v_goods uuid;
  v_food uuid;
begin
  insert into public.shops (slug, name, address, city, country, timezone, location, phone, opening_hours, is_active)
  select 'style-goods', 'Style Goods', address, city, 'SK', timezone, location, phone, opening_hours, true
  from public.shops where slug = 'potraviny-centrum'
  returning id into v_goods;
  insert into public.shops (slug, name, address, city, country, timezone, location, phone, opening_hours, is_active, kind)
  select 'style-food', 'Style Food', address, city, 'SK', timezone, location, phone, opening_hours, true, 'food'
  from public.shops where slug = 'potraviny-centrum'
  returning id into v_food;
  insert into public.shop_members (shop_id, user_id) values (v_goods, '00000000-0000-0000-0000-00000000000a'), (v_food, '00000000-0000-0000-0000-00000000000a');
  insert into style_test values ('goods', v_goods), ('food', v_food);
  -- the one rule
  assert public.assistant_style_of(null, 'goods') = 'plain';
  assert public.assistant_style_of(null, 'food') = 'waiter', 'a new restaurant talks as a waiter';
  assert public.assistant_style_of('waiter', 'goods') = 'plain', 'waiter only for food';
  assert public.assistant_style_of('friendly', 'food') = 'friendly';
  assert public.shop_assistant_persona('style-food') = '{"style": "waiter", "name": null}'::jsonb, public.shop_assistant_persona('style-food')::text;
  assert public.shop_assistant_persona('style-goods') ->> 'style' = 'plain';
  assert public.shop_assistant_persona('no-such-shop') is null;
end $$;

set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000a';
do $$
declare
  v_goods uuid := (select v from style_test where k = 'goods');
begin
  -- without the plan: refused
  begin perform public.owner_set_assistant_style(v_goods, 'friendly', null); raise exception 'saved without the plan';
  exception when insufficient_privilege then null; end;
end $$;
reset role;
reset request.jwt.claim.sub;
insert into public.subscriptions (shop_id, status, plan, current_period_end, stripe_subscription_id)
select v, 'active', 'pro', now() + interval '30 days', 'sub_style_' || k from style_test
on conflict (shop_id) do update set status = 'active', current_period_end = now() + interval '30 days';
set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000a';
do $$
declare
  v_goods uuid := (select v from style_test where k = 'goods');
  v_food uuid := (select v from style_test where k = 'food');
  v jsonb;
  v_msg text;
begin
  assert public.owner_assistant_style(v_food) ->> 'style' = 'waiter';
  -- waiter only for a restaurant
  begin perform public.owner_set_assistant_style(v_goods, 'waiter', null); raise exception 'waiter for a goods shop';
  exception when invalid_parameter_value then
    get stacked diagnostics v_msg = message_text;
    assert v_msg = 'not_food', v_msg;
  end;
  begin perform public.owner_set_assistant_style(v_goods, 'pirate', null); raise exception 'an unknown style';
  exception when invalid_parameter_value then null; end;
  -- the name: ≤ 20 characters, plain text, empty = none
  begin perform public.owner_set_assistant_style(v_food, 'waiter', 'Marco Polo the Great Waiter'); raise exception 'a long name';
  exception when invalid_parameter_value then null; end;
  v := public.owner_set_assistant_style(v_food, 'waiter', '  <b>Marco</b> ');
  assert v = '{"style": "waiter", "name": "Marco"}'::jsonb, v::text;
  assert exists (select 1 from public.shop_activity where shop_id = v_food and action = 'assistant_style_changed');
  v := public.owner_set_assistant_style(v_goods, 'friendly', '');
  assert v = '{"style": "friendly", "name": null}'::jsonb, v::text;
  -- the table itself is not written by owners
  begin update public.shop_assistant_settings set style = 'waiter' where shop_id = v_goods; raise exception 'wrote the table';
  exception when insufficient_privilege then null; end;
  -- the restaurant becomes a goods shop: its waiter talks plain from then on
  perform public.owner_set_shop_kind(v_food, 'goods');
end $$;
reset role;
reset request.jwt.claim.sub;
do $$
declare
  v_food uuid := (select v from style_test where k = 'food');
begin
  assert (select style from public.shop_assistant_settings where shop_id = v_food) = 'plain', 'kind change fell back to plain';
  assert public.shop_assistant_persona('style-food') = '{"style": "plain", "name": "Marco"}'::jsonb, public.shop_assistant_persona('style-food')::text;
  assert public.shop_assistant_persona('style-goods') = '{"style": "friendly", "name": null}'::jsonb;
end $$;
set role anon;
do $$
begin
  assert public.shop_assistant_persona('style-goods') ->> 'style' = 'friendly', 'a visitor reads the persona';
  begin perform public.owner_assistant_style((select v from style_test where k = 'goods')); raise exception 'a visitor read the owner view';
  exception when insufficient_privilege then null; end;
  begin perform (select style from public.shop_assistant_settings limit 1); raise exception 'a visitor read the table';
  exception when insufficient_privilege then null; end;
end $$;
reset role;
delete from public.subscriptions where shop_id in (select v from style_test);
delete from public.shops where slug in ('style-goods', 'style-food');
drop table style_test;

\echo '--- update 93: blog photos — the cover belongs to the post (another shop''s photo refused), the cover first in blog_photo_list with its focus, an imported post whose photos the owner took keeps them on the next import, a replaced file keeps the photo''s id'
create temporary table t93 (k text primary key, v text);
grant all on t93 to public;
set role service_role;
do $$
declare
  v_a uuid := (select id from public.shops where slug = 'potraviny-centrum');
  v_r jsonb;
  v_post uuid;
  v_p1 uuid;
  v_p2 uuid;
  v_other uuid;
  v_list jsonb;
begin
  v_r := public.blog_import_post(v_a, '123456789_9301', 'Fotky', 'Dve fotky', now() - interval '1 day', now() - interval '1 day', null, '[]',
    '[{"kind": "photo", "fb_media_id": "9301001", "source_url": "https://scontent.example/a.jpg"},
      {"kind": "photo", "fb_media_id": "9301002", "source_url": "https://scontent.example/b.jpg"}]');
  v_post := (v_r ->> 'post_id')::uuid;
  select id into v_p1 from public.blog_photos where post_id = v_post and fb_media_id = '9301001';
  select id into v_p2 from public.blog_photos where post_id = v_post and fb_media_id = '9301002';
  perform public.blog_photo_stored(v_p1, 1600, v_a || '/' || v_post || '/' || v_p1 || '-1600.webp', 'webp', 1600, 900, true);
  perform public.blog_photo_stored(v_p2, 1600, v_a || '/' || v_post || '/' || v_p2 || '-1600.webp', 'webp', 800, 1200, true);
  -- another shop's photo (for the refusal)
  insert into public.blog_posts (shop_id, slug, title, body, source, status, publish_at)
  values ((select id from public.shops where slug <> 'potraviny-centrum' order by slug limit 1), 'iny-93', 'Iný', 'x', 'cacaduu', 'draft', now())
  returning id into v_other;
  -- before a choice: the first photo is the cover (center)
  v_list := public.blog_photo_list(v_post);
  assert (v_list -> 0 ->> 'id')::uuid = v_p1 and (v_list -> 0 ->> 'cover')::boolean and v_list -> 0 ->> 'focus' = 'center', v_list::text;
  insert into t93 values ('post', v_post), ('p1', v_p1), ('p2', v_p2), ('shop', v_a);
end $$;
reset role;

set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000a';
do $$
declare
  v_post uuid := (select v::uuid from t93 where k = 'post');
  v_p1 uuid := (select v::uuid from t93 where k = 'p1');
  v_p2 uuid := (select v::uuid from t93 where k = 'p2');
begin
  -- the cover: a photo of THIS post, top
  perform public.owner_blog_set_cover(v_post, v_p2, 'top');
  begin perform public.owner_blog_set_cover(v_post, gen_random_uuid(), 'top'); raise exception 'a photo of no post';
  exception when invalid_parameter_value then assert sqlerrm = 'photo'; end;
  begin perform public.owner_blog_set_cover(v_post, v_p1, 'left'); raise exception 'a bad focus';
  exception when invalid_parameter_value then assert sqlerrm = 'focus'; end;
  -- the AI's door knows the sizes and the cover
  assert (select (public.owner_blog_ai_hit(v_post) ->> 'cover_photo_id')::uuid) = v_p2;
  -- reordering an imported post's photos makes them the owner's (logged once)
  assert not (select photos_by_owner from public.blog_posts where id = v_post);
  perform public.owner_blog_photo_order(v_post, array[v_p2, v_p1]);
  assert (select photos_by_owner from public.blog_posts where id = v_post);
  assert (select count(*) from public.shop_activity where action = 'blog_photos_owned' and details ->> 'post_id' = v_post::text) = 1;
  perform public.owner_blog_photos_take(v_post);
  assert (select count(*) from public.shop_activity where action = 'blog_photos_owned' and details ->> 'post_id' = v_post::text) = 1, 'once';
end $$;
reset role;

-- another owner: no cover, no taking
set role authenticated;
set request.jwt.claim.sub = '00000000-0000-0000-0000-00000000000b';
do $$
begin
  begin perform public.owner_blog_set_cover((select v::uuid from t93 where k = 'post'), null, 'center'); raise exception 'another owner set a cover';
  exception when insufficient_privilege then null; end;
  begin perform public.owner_blog_photos_take((select v::uuid from t93 where k = 'post')); raise exception 'another owner took photos';
  exception when insufficient_privilege then null; end;
end $$;
reset role;

set role service_role;
do $$
declare
  v_a uuid := (select v::uuid from t93 where k = 'shop');
  v_post uuid := (select v::uuid from t93 where k = 'post');
  v_p1 uuid := (select v::uuid from t93 where k = 'p1');
  v_p2 uuid := (select v::uuid from t93 where k = 'p2');
  v_r jsonb;
  v_old text;
  v_list jsonb := public.blog_photo_list((select v::uuid from t93 where k = 'post'));
begin
  -- the chosen cover first, with its focus
  assert (v_list -> 0 ->> 'id')::uuid = v_p2 and v_list -> 0 ->> 'focus' = 'top' and v_list -> 1 ->> 'cover' is null, v_list::text;
  -- the next import with other photos: the owner's photos stay (ids, order, cover)
  v_r := public.blog_import_post(v_a, '123456789_9301', 'Fotky', 'Dve fotky', now() - interval '1 day', now(), null, '[]',
    '[{"kind": "photo", "fb_media_id": "9301999", "source_url": "https://scontent.example/c.jpg"}]');
  assert v_r ->> 'result' = 'same', v_r::text;
  assert (select array_agg(id order by position) from public.blog_photos where post_id = v_post) = array[v_p2, v_p1];
  assert (select cover_photo_id from public.blog_posts where id = v_post) = v_p2;
  -- a text edit on Facebook still comes, the photos still stay
  v_r := public.blog_import_post(v_a, '123456789_9301', 'Fotky', 'Dve fotky – opravené', now() - interval '1 day', now(), null, '[]',
    '[{"kind": "photo", "fb_media_id": "9301999", "source_url": "https://scontent.example/c.jpg"}]');
  assert v_r ->> 'result' = 'updated' and v_r -> 'removed' = '[]'::jsonb, v_r::text;
  assert (select count(*) from public.blog_photos where post_id = v_post) = 2;
  -- "Vymeniť": the new file into the same row, the old one returned for deletion
  v_old := public.blog_photo_swapped(v_p1, 1600, v_a || '/' || v_post || '/' || v_p1 || '-1600-ab12cd34.webp', 'webp', 1200, 1200, true);
  assert v_old = v_a || '/' || v_post || '/' || v_p1 || '-1600.webp', v_old;
  assert (select path_large ~ '-ab12cd34\.webp$' and width = 1200 from public.blog_photos where id = v_p1);
  begin perform public.blog_photo_swapped(v_p1, 1600, 'bad/path.webp', 'webp', 10, 10); raise exception 'a bad path';
  exception when check_violation then null; end;
  -- deleting the cover photo: the first photo is the cover again
  perform public.blog_photo_delete(v_p2);
  assert (select cover_photo_id from public.blog_posts where id = v_post) is null;
  assert (public.blog_photo_list(v_post) -> 0 ->> 'id')::uuid = v_p1;
  delete from public.blog_posts where id = v_post or slug = 'iny-93';
end $$;
reset role;
set role anon;
do $$
begin
  begin perform public.blog_photo_list((select v::uuid from t93 where k = 'post')); raise exception 'a visitor read the list directly';
  exception when insufficient_privilege then null; end;
  begin perform public.owner_blog_set_cover((select v::uuid from t93 where k = 'post'), null, 'top'); raise exception 'a visitor set a cover';
  exception when insufficient_privilege then null; end;
end $$;
reset role;
drop table t93;

